window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2020-4"]={"track":"written","round":"2020-4","questions":[{"id":"written-2020-4-1","no":1,"unit":"소프트웨어 설계","q":"XP(eXtreme Programming)의 기본원리로 볼 수 없는 것은?","choices":["Linear Sequential Method","Pair Programming","Collective Ownership","Continuous Integration"],"ans":1,"rate":64,"exp":{"concept":"XP(eXtreme Programming)는 고객과 자주 소통하며 짧은 주기로 조금씩 개발하고 계속 테스트·통합하는 애자일 방법론이다. 짝 프로그래밍, 공동 소유, 지속적인 통합, 테스트 주도 개발, 리팩토링 같은 실천 사항을 둔다. 단계를 한 번씩 순서대로만 밟는 방식과는 정반대의 생각이다.","choices":[{"verdict":"정답","why":"선형 순차적 방법(Linear Sequential Method)은 요구 분석부터 유지보수까지 차례대로 한 번씩 진행하는 폭포수 모형의 다른 이름이다. 변화에 빠르게 대응하려는 XP의 원리가 아니다."},{"verdict":"오답","why":"짝 프로그래밍(Pair Programming)은 두 사람이 한 컴퓨터로 함께 코딩하는 XP의 실천 사항이다."},{"verdict":"오답","why":"공동 소유(Collective Ownership)는 코드를 팀 전체가 함께 소유하고 누구나 고칠 수 있게 하는 XP의 실천 사항이다."},{"verdict":"오답","why":"지속적인 통합(Continuous Integration)은 작업이 끝날 때마다 코드를 자주 통합하는 XP의 실천 사항이다."}],"keywords":[{"term":"XP 5가지 가치","desc":"용기, 단순성, 의사소통, 피드백, 존중"},{"term":"짝 프로그래밍(Pair Programming)","desc":"두 명이 한 컴퓨터에서 함께 코드를 작성하고 검토한다"},{"term":"지속적인 통합(Continuous Integration)","desc":"작은 단위로 자주 코드를 합쳐 통합 문제를 빨리 찾는다"},{"term":"선형 순차적 모형","desc":"폭포수 모형의 다른 이름, 단계를 순서대로 한 번씩 진행"}],"memo":"Linear Sequential은 폭포수 모형을 뜻한다. 애자일 문항에서 '선형·순차'가 보이면 바로 지운다."}},{"id":"written-2020-4-2","no":2,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh) 객체지향 분석 기법에서 동적 모델링에 활용되는 다이어그램은?","choices":["객체 다이어그램(Object Diagram)","패키지 다이어그램(Package Diagram)","상태 다이어그램(State Diagram)","자료 흐름도(Data Flow Diagram)"],"ans":3,"rate":55,"exp":{"concept":"럼바우(Rumbaugh)의 객체 모델링 기법(OMT)은 시스템을 세 가지 관점으로 나눠 그린다. 객체 모델링은 객체 다이어그램으로 객체와 관계를, 동적 모델링은 상태 다이어그램으로 시간에 따른 상태 변화를, 기능 모델링은 자료 흐름도(DFD)로 데이터가 어떻게 처리되는지를 표현한다.","choices":[{"verdict":"오답","why":"객체 다이어그램은 객체 모델링에서 객체와 그 관계를 표현할 때 쓴다."},{"verdict":"오답","why":"패키지 다이어그램은 UML의 구조 다이어그램으로, 요소들을 패키지로 묶어 의존 관계를 보여 준다. 럼바우의 세 모델링에 쓰이는 도구가 아니다."},{"verdict":"정답","why":"상태 다이어그램(State Diagram)은 사건(이벤트)에 따라 객체의 상태가 어떻게 바뀌는지 보여 주며, 동적 모델링에 쓰인다."},{"verdict":"오답","why":"자료 흐름도(DFD)는 입력이 처리되어 출력이 되는 과정을 그리며, 기능 모델링에 쓰인다."}],"keywords":[{"term":"객체 모델링(Object Modeling)","desc":"객체 다이어그램으로 객체·속성·관계를 표현"},{"term":"동적 모델링(Dynamic Modeling)","desc":"상태 다이어그램으로 시간 흐름에 따른 상태 변화를 표현"},{"term":"기능 모델링(Functional Modeling)","desc":"자료 흐름도(DFD)로 데이터 처리 과정을 표현"}],"memo":"럼바우 순서는 객체 → 동적 → 기능, 짝은 객체-객체도, 동적-상태도, 기능-DFD로 묶어 외운다."}},{"id":"written-2020-4-3","no":3,"unit":"소프트웨어 설계","q":"CASE(Computer Aided Software Engineering)의 주요 기능으로 옳지 않은 것은?","choices":["S/W 라이프 사이클 전 단계의 연결","그래픽 지원","다양한 소프트웨어 개발 모형 지원","언어 번역"],"ans":4,"rate":78,"wiki":[{"title":"CASE","url":"https://itwiki.kr/w/CASE"}],"exp":{"concept":"CASE(Computer Aided Software Engineering)는 소프트웨어 개발 과정의 여러 작업을 컴퓨터 도구로 자동화해 돕는 것이다. 분석·설계·구현·테스트 등 생명 주기 각 단계를 서로 연결하고, 다이어그램을 그리는 그래픽 기능을 제공하며, 여러 개발 모형을 지원한다. 프로그래밍 언어를 기계어로 바꾸는 일은 컴파일러 같은 언어 번역기의 몫이다.","choices":[{"verdict":"오답","why":"CASE는 요구 분석에서 유지보수까지 생명 주기 전 단계의 산출물을 연결해 관리한다. 주요 기능이 맞다."},{"verdict":"오답","why":"CASE는 자료 흐름도 같은 다이어그램을 그릴 수 있게 그래픽을 지원한다. 주요 기능이 맞다."},{"verdict":"오답","why":"CASE는 폭포수, 프로토타입 등 다양한 소프트웨어 개발 모형을 지원한다. 주요 기능이 맞다."},{"verdict":"정답","why":"언어 번역은 컴파일러·인터프리터 같은 언어 번역 프로그램의 기능이다. CASE의 주요 기능으로 꼽지 않는다."}],"keywords":[{"term":"CASE","desc":"소프트웨어 개발 작업을 자동화해 지원하는 도구·기법"},{"term":"상위 CASE","desc":"요구 분석·설계 같은 앞 단계를 지원"},{"term":"하위 CASE","desc":"코드 작성·테스트·문서화 같은 뒤 단계를 지원"}],"memo":"CASE 주요 기능은 '생명 주기 연결, 그래픽 지원, 다양한 모형 지원' 세 가지로 외운다."}},{"id":"written-2020-4-4","no":4,"unit":"소프트웨어 설계","q":"객체지향 기법의 캡슐화(Encapsulation)에 대한 설명으로 틀린 것은?","choices":["인터페이스가 단순화 된다.","소프트웨어 재사용성이 높아진다.","변경 발생 시 오류의 파급효과가 적다.","상위 클래스의 모든 속성과 연산을 하위 클래스가 물려받는 것을 의미한다."],"ans":4,"rate":80,"exp":{"concept":"캡슐화(Encapsulation)는 데이터(속성)와 그 데이터를 다루는 함수(연산)를 하나로 묶고, 내부 구현은 숨긴 채 필요한 인터페이스만 밖에 보여 주는 것이다. 리모컨 내부 회로를 몰라도 버튼만 누르면 되는 것과 같다. 내부가 숨겨져 있으니 고쳐도 다른 곳에 영향이 덜 간다.","choices":[{"verdict":"오답","why":"내부 구현을 숨기고 필요한 연산만 공개하므로 외부에서 보는 인터페이스가 단순해진다. 맞는 설명이다."},{"verdict":"오답","why":"잘 묶인 객체는 다른 곳에 그대로 가져다 쓰기 쉬워 재사용성이 높아진다. 맞는 설명이다."},{"verdict":"오답","why":"내부가 감춰져 있어 내부를 고쳐도 다른 모듈로 오류가 번지는 파급 효과가 적다. 맞는 설명이다."},{"verdict":"정답","why":"상위 클래스의 속성과 연산을 하위 클래스가 물려받는 것은 상속(Inheritance)이다. 캡슐화의 설명이 아니다."}],"keywords":[{"term":"캡슐화(Encapsulation)","desc":"데이터와 연산을 하나로 묶고 내부를 숨기는 것"},{"term":"정보 은닉(Information Hiding)","desc":"다른 객체에게 내부 정보를 숨기고 인터페이스로만 접근하게 함"},{"term":"상속(Inheritance)","desc":"상위 클래스의 속성과 연산을 하위 클래스가 물려받음"}],"memo":"'물려받는다'는 말이 나오면 상속, '묶고 숨긴다'는 말이 나오면 캡슐화다."}},{"id":"written-2020-4-5","no":5,"unit":"소프트웨어 설계","q":"다음 내용이 설명하는 객체지향 설계 원칙은?\n<img src=\"data/img/eip_written_20200926_005.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["인터페이스 분리 원칙","단일 책임 원칙","개방 폐쇄의 원칙","리스코프 교체의 원칙"],"ans":1,"rate":72,"wiki":[{"title":"객체지향 설계 원칙","url":"https://itwiki.kr/w/객체지향 설계 원칙"}],"exp":{"concept":"객체지향 설계 원칙 SOLID 중 인터페이스 분리 원칙(ISP)은 클라이언트가 자신이 쓰지 않는 메서드에 의존하지 않도록 인터페이스를 작게 나누라는 원칙이다. 지문의 '사용하지 않는 메서드와 의존 관계를 맺으면 안 된다', '사용하지 않는 인터페이스 때문에 영향을 받으면 안 된다'가 바로 이 원칙이다. 리모컨 하나에 쓰지도 않는 버튼 100개를 붙이지 말고 용도별로 나누라는 뜻이다.","choices":[{"verdict":"정답","why":"인터페이스 분리 원칙(ISP, Interface Segregation Principle)은 클라이언트가 사용하지 않는 메서드나 인터페이스에 의존하지 않게 인터페이스를 쪼개라는 원칙이다. 지문과 정확히 맞는다."},{"verdict":"오답","why":"단일 책임 원칙(SRP, Single Responsibility Principle)은 하나의 클래스는 하나의 책임만 가져야 한다는 원칙이다."},{"verdict":"오답","why":"개방 폐쇄 원칙(OCP, Open-Closed Principle)은 기능 확장에는 열려 있고 기존 코드 변경에는 닫혀 있어야 한다는 원칙이다."},{"verdict":"오답","why":"리스코프 치환 원칙(LSP, Liskov Substitution Principle)은 하위 클래스가 상위 클래스를 대신해도 프로그램이 올바르게 동작해야 한다는 원칙이다."}],"keywords":[{"term":"SRP","desc":"단일 책임 원칙, 클래스는 하나의 책임만"},{"term":"OCP","desc":"개방 폐쇄 원칙, 확장에는 열리고 수정에는 닫힘"},{"term":"LSP","desc":"리스코프 치환 원칙, 자식은 부모 자리를 대신할 수 있어야 함"},{"term":"ISP","desc":"인터페이스 분리 원칙, 사용하지 않는 메서드에 의존하지 않음"},{"term":"DIP","desc":"의존 역전 원칙, 구체 클래스가 아닌 추상화에 의존"}],"memo":"지문에 '사용하지 않는'과 '인터페이스'가 함께 나오면 ISP다."}},{"id":"written-2020-4-6","no":6,"unit":"소프트웨어 설계","q":"파이프 필터 형태의 소프트웨어 아키텍처에 대한 설명으로 옳은 것은?","choices":["노드와 간선으로 구성된다.","서브시스템이 입력데이터를 받아 처리하고 결과를 다음 서브시스템으로 넘겨주는 과정을 반복한다.","계층 모델이라고도 한다.","3개의 서브시스템(모델, 뷰, 제어)으로 구성되어 있다."],"ans":2,"rate":68,"exp":{"concept":"파이프-필터(Pipe-Filter) 구조는 데이터가 파이프를 따라 흐르면서 필터(서브시스템)를 하나씩 거치며 처리되는 아키텍처다. 각 필터는 입력을 받아 처리한 뒤 결과를 다음 필터로 넘긴다. 공장의 컨베이어 벨트에서 제품이 공정을 차례로 거치는 모습과 같다.","choices":[{"verdict":"오답","why":"노드와 간선으로 이루어진다는 것은 그래프 구조에 대한 설명이다. 파이프-필터 구조의 핵심 특징이 아니다."},{"verdict":"정답","why":"서브시스템(필터)이 입력 데이터를 받아 처리하고 그 결과를 다음 서브시스템으로 넘기는 과정을 반복하는 것이 파이프-필터 구조다."},{"verdict":"오답","why":"계층 모델은 레이어 패턴(Layers Pattern)으로, 시스템을 계층으로 나눠 위·아래 계층끼리만 상호 작용하는 구조다."},{"verdict":"오답","why":"모델, 뷰, 제어(컨트롤러) 세 서브시스템으로 구성되는 것은 MVC(Model-View-Controller) 패턴이다."}],"keywords":[{"term":"파이프-필터 패턴","desc":"데이터 스트림을 필터가 차례로 처리하고 파이프로 전달"},{"term":"레이어 패턴","desc":"시스템을 계층으로 나눠 인접 계층끼리 상호 작용"},{"term":"MVC 패턴","desc":"모델·뷰·컨트롤러로 나눠 데이터·화면·제어를 분리"}],"memo":"파이프-필터는 '받아서 처리하고 다음으로 넘긴다'. 유닉스의 ls | grep처럼 파이프로 이어지는 모습을 떠올린다."}},{"id":"written-2020-4-7","no":7,"unit":"소프트웨어 설계","q":"코드화 대상 항목의 중량, 면적, 용량 등의 물리적 수치를 이용하여 만든 코드는?","choices":["순차 코드","10진 코드","표의 숫자 코드","블록 코드"],"ans":3,"rate":60,"wiki":[{"title":"코드","url":"https://itwiki.kr/w/코드"}],"exp":{"concept":"코드는 대상을 구분하기 위해 붙이는 기호다. 표의 숫자 코드(유효 숫자 코드, Significant Digit Code)는 대상 항목의 길이, 무게, 면적, 용량 같은 물리적 수치를 코드에 그대로 넣어 만든다. 예를 들어 120-720-1500처럼 규격 수치가 코드에 드러난다.","choices":[{"verdict":"오답","why":"순차 코드는 자료가 발생한 순서나 크기 순서대로 일련번호를 붙이는 코드다."},{"verdict":"오답","why":"10진 코드는 대상을 0~9의 10진수로 나누고 다시 10진수로 세분하는 코드로, 도서 분류에 쓰인다."},{"verdict":"정답","why":"표의 숫자 코드는 중량, 면적, 용량 같은 물리적 수치를 그대로 코드에 적용한다."},{"verdict":"오답","why":"블록 코드는 공통된 특성별로 블록(구간)을 나누고 각 블록 안에서 일련번호를 붙이는 코드다."}],"keywords":[{"term":"순차 코드(Sequence Code)","desc":"발생 순서·크기 순서대로 일련번호 부여"},{"term":"블록 코드(Block Code)","desc":"공통 특성별로 블록을 나누고 블록 안에서 번호 부여"},{"term":"10진 코드(Decimal Code)","desc":"0~9로 나누고 다시 10진 분할, 도서 분류식"},{"term":"표의 숫자 코드(Significant Digit Code)","desc":"길이·무게·용량 등 물리적 수치를 코드에 반영"},{"term":"연상 코드(Mnemonic Code)","desc":"명칭이나 약호를 넣어 보고 무엇인지 연상되게 한 코드"}],"memo":"'물리적 수치'가 나오면 표의 숫자 코드, '연상'이 되면 연상 코드다."}},{"id":"written-2020-4-8","no":8,"unit":"소프트웨어 설계","q":"디자인 패턴 사용의 장٠단점에 대한 설명으로 거리가 먼 것은?","choices":["소프트웨어 구조 파악이 용이하다.","객체지향 설계 및 구현의 생산성을 높이는데 적합하다.","재사용을 위한 개발 시간이 단축된다.","절차형 언어와 함께 이용될 때 효율이 극대화된다."],"ans":4,"rate":78,"exp":{"concept":"디자인 패턴은 객체지향 설계에서 자주 생기는 문제에 대한 검증된 해결 방법을 정리해 둔 것이다. 같은 패턴 이름을 쓰면 개발자끼리 구조를 쉽게 이해하고, 설계를 재사용해 개발 시간을 줄일 수 있다. 다만 객체지향을 전제로 만들어졌기 때문에 절차형 언어와는 잘 맞지 않는다.","choices":[{"verdict":"오답","why":"패턴 이름만으로 구조를 짐작할 수 있어 소프트웨어 구조 파악이 쉬워진다. 맞는 장점이다."},{"verdict":"오답","why":"검증된 설계를 재사용하므로 객체지향 설계와 구현의 생산성을 높인다. 맞는 장점이다."},{"verdict":"오답","why":"이미 정리된 해법을 재사용하므로 개발 시간이 단축된다. 맞는 장점이다."},{"verdict":"정답","why":"디자인 패턴은 객체지향 설계·구현을 위한 것이라 절차형 언어와 함께 쓰면 효율이 떨어진다. 효율이 극대화된다는 설명은 틀렸다."}],"keywords":[{"term":"디자인 패턴(Design Pattern)","desc":"객체지향 설계에서 반복되는 문제의 검증된 해결 방법"},{"term":"GoF 디자인 패턴","desc":"생성·구조·행위 패턴으로 나눈 23가지 패턴"},{"term":"디자인 패턴의 단점","desc":"객체지향 기반이라 절차형 언어와는 효율이 떨어지고 초기 투자 비용이 든다"}],"memo":"디자인 패턴의 짝은 '객체지향'이다. '절차형'과 묶인 보기는 틀린 설명이다."}},{"id":"written-2020-4-9","no":9,"unit":"소프트웨어 설계","q":"DFD(data flow diagram)에 대한 설명으로 틀린 것은?","choices":["자료 흐름 그래프 또는 버블(bubble) 차트라고도 한다.","구조적 분석 기법에 이용된다.","시간 흐름을 명확하게 표현할 수 있다.","DFD의 요소는 화살표, 원, 사각형, 직선(단선/이중선)으로 표시한다."],"ans":3,"rate":60,"wiki":[{"title":"자료 흐름도","url":"https://itwiki.kr/w/자료 흐름도"}],"exp":{"concept":"자료 흐름도(DFD, Data Flow Diagram)는 데이터가 어디서 들어와 어떤 처리를 거쳐 어디로 나가는지를 그림으로 보여 주는 구조적 분석 도구다. 데이터의 흐름을 중심으로 그리기 때문에 언제, 어떤 순서로 일이 일어나는지 같은 시간 흐름은 나타내지 못한다.","choices":[{"verdict":"오답","why":"DFD는 자료 흐름 그래프, 버블(Bubble) 차트라고도 부른다. 맞는 설명이다."},{"verdict":"오답","why":"DFD는 구조적 분석 기법의 대표 도구다. 맞는 설명이다."},{"verdict":"정답","why":"DFD는 자료의 흐름과 변환 과정만 보여 줄 뿐 시간의 흐름이나 처리 순서는 표현하지 못한다. 틀린 설명이다."},{"verdict":"오답","why":"DFD의 요소는 자료 흐름(화살표), 프로세스(원), 단말(사각형), 자료 저장소(직선·평행선)로 표시한다. 맞는 설명이다."}],"keywords":[{"term":"프로세스(Process)","desc":"자료를 변환하는 처리, 원으로 표시"},{"term":"자료 흐름(Data Flow)","desc":"자료의 이동, 화살표로 표시"},{"term":"자료 저장소(Data Store)","desc":"자료가 저장되는 곳, 평행선으로 표시"},{"term":"단말(Terminator)","desc":"시스템 밖의 데이터 출처·도착지, 사각형으로 표시"}],"memo":"DFD는 '흐름'은 그리지만 '시간'은 못 그린다. 시간·상태 변화는 상태 다이어그램의 몫이다."}},{"id":"written-2020-4-10","no":10,"unit":"소프트웨어 설계","q":"그래픽 표기법을 이용하여 소프트웨어 구성 요소를 모델링하는 럼바우 분석 기법에 포함되지 않는 것은?","choices":["객체 모델링","기능 모델링","동적 모델링","블랙박스 분석 모델링"],"ans":4,"rate":88,"wiki":[{"title":"럼바우 분석 기법","url":"https://itwiki.kr/w/럼바우 분석 기법"}],"exp":{"concept":"럼바우(Rumbaugh) 분석 기법은 소프트웨어 구성 요소를 그래픽 표기법으로 모델링하는 객체지향 분석 기법으로, 객체 모델링, 동적 모델링, 기능 모델링 세 단계로 이루어진다. 블랙박스 분석이라는 단계는 없다.","choices":[{"verdict":"오답","why":"객체 모델링은 객체 다이어그램으로 객체와 관계를 표현하는 럼바우 기법의 단계다."},{"verdict":"오답","why":"기능 모델링은 자료 흐름도(DFD)로 처리 과정을 표현하는 럼바우 기법의 단계다."},{"verdict":"오답","why":"동적 모델링은 상태 다이어그램으로 시간에 따른 상태 변화를 표현하는 럼바우 기법의 단계다."},{"verdict":"정답","why":"블랙박스 분석 모델링은 럼바우 기법의 구성에 없다. 블랙박스는 내부를 보지 않고 입력과 출력만 보는 테스트 방식에서 쓰는 말이다."}],"keywords":[{"term":"럼바우 OMT(Object Modeling Technique)","desc":"객체·동적·기능 모델링으로 분석하는 기법"},{"term":"객체 모델링","desc":"객체 다이어그램, 가장 먼저 수행"},{"term":"동적 모델링","desc":"상태 다이어그램, 상태 변화 표현"},{"term":"기능 모델링","desc":"자료 흐름도(DFD), 데이터 처리 표현"}],"memo":"럼바우는 '객·동·기' 세 개뿐이다. 그 밖의 이름이 붙은 모델링은 오답이다."}},{"id":"written-2020-4-11","no":11,"unit":"소프트웨어 설계","q":"UML의 기본 구성요소가 아닌 것은?","choices":["Things","Terminal","Relationship","Diagram"],"ans":2,"rate":62,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"exp":{"concept":"UML(Unified Modeling Language)은 시스템을 그림으로 표현하는 표준 모델링 언어다. 기본 구성 요소는 사물(Things), 관계(Relationships), 다이어그램(Diagrams) 세 가지다. 사물은 표현할 대상, 관계는 사물끼리의 연결, 다이어그램은 이것들을 모아 그린 그림이다.","choices":[{"verdict":"오답","why":"사물(Things)은 모델을 구성하는 대상(클래스, 유스케이스, 컴포넌트 등)으로 UML의 기본 구성 요소다."},{"verdict":"정답","why":"Terminal은 UML의 기본 구성 요소가 아니다. UML 구성 요소는 사물, 관계, 다이어그램 세 가지뿐이다."},{"verdict":"오답","why":"관계(Relationships)는 사물과 사물 사이의 연관, 집합, 일반화, 의존 등의 연결로 UML의 기본 구성 요소다."},{"verdict":"오답","why":"다이어그램(Diagrams)은 사물과 관계를 그림으로 표현한 것으로 UML의 기본 구성 요소다."}],"keywords":[{"term":"사물(Things)","desc":"구조·행동·그룹·주해 사물, 모델의 대상"},{"term":"관계(Relationships)","desc":"연관, 집합, 포함, 일반화, 의존, 실체화"},{"term":"다이어그램(Diagrams)","desc":"구조 다이어그램과 행위 다이어그램으로 나뉨"}],"memo":"UML 구성 요소는 '사·관·다' 세 글자로 외운다."}},{"id":"written-2020-4-12","no":12,"unit":"소프트웨어 설계","q":"소프트웨어의 상위설계에 속하지 않는 것은?","choices":["아키텍처 설계","모듈 설계","인터페이스 정의","사용자 인터페이스 설계"],"ans":2,"rate":52,"wiki":[{"title":"소프트웨어 설계","url":"https://itwiki.kr/w/소프트웨어 설계"}],"exp":{"concept":"소프트웨어 설계는 상위 설계와 하위 설계로 나뉜다. 상위 설계는 시스템 전체의 뼈대를 정하는 것으로 아키텍처 설계, 데이터 설계, 인터페이스 정의, 사용자 인터페이스 설계가 속한다. 하위 설계는 그 뼈대 안의 각 부품을 자세히 정하는 것으로 모듈 설계, 자료 구조 설계, 알고리즘 설계가 속한다.","choices":[{"verdict":"오답","why":"아키텍처 설계는 시스템 전체 구조를 정하는 상위 설계다."},{"verdict":"정답","why":"모듈 설계는 각 모듈의 내부를 구체적으로 정하는 하위 설계에 속한다. 상위 설계가 아니다."},{"verdict":"오답","why":"인터페이스 정의는 시스템 구성 요소 사이의 연결 방법을 정하는 상위 설계다."},{"verdict":"오답","why":"사용자 인터페이스 설계는 사용자와 시스템이 주고받는 방식을 정하는 상위 설계다."}],"keywords":[{"term":"상위 설계(아키텍처 설계, 예비 설계)","desc":"아키텍처, 데이터, 인터페이스 정의, 사용자 인터페이스 설계"},{"term":"하위 설계(모듈 설계, 상세 설계)","desc":"모듈, 자료 구조, 알고리즘 설계"}],"memo":"집으로 치면 상위 설계는 설계도와 출입구, 하위 설계는 방 안의 가구 배치다. '모듈'은 하위 설계."}},{"id":"written-2020-4-13","no":13,"unit":"소프트웨어 설계","q":"다음 중 자료사전(Data Dictionary)에서 선택의 의미를 나타내는 것은?","choices":["[ ]","{ }","＋","＝"],"ans":1,"rate":73,"wiki":[{"title":"자료 사전","url":"https://itwiki.kr/w/자료 사전"}],"exp":{"concept":"자료 사전(DD, Data Dictionary)은 자료 흐름도에 나오는 자료의 이름과 구성을 기호로 정의해 모아 둔 사전이다. 정의는 =, 연결은 +, 선택은 [ ], 반복은 { }, 생략은 ( )로 표시하고, 주석은 **로 표시한다.","choices":[{"verdict":"정답","why":"[ ]는 여러 항목 중 하나를 고르는 선택을 뜻하며, 항목 사이를 |로 구분한다."},{"verdict":"오답","why":"{ }는 같은 항목을 여러 번 되풀이하는 반복을 뜻한다."},{"verdict":"오답","why":"+는 자료와 자료를 이어 붙이는 연결을 뜻한다."},{"verdict":"오답","why":"=는 자료가 무엇으로 구성되는지 나타내는 정의를 뜻한다."}],"keywords":[{"term":"=","desc":"정의, ~로 구성된다"},{"term":"+","desc":"연결, 그리고"},{"term":"[ ]","desc":"선택, 여러 개 중 하나"},{"term":"{ }","desc":"반복"},{"term":"( )","desc":"생략 가능"}],"memo":"대괄호 [ ]는 고르기(선택), 중괄호 { }는 되풀이(반복). '선대반중'으로 짝지어 외운다."}},{"id":"written-2020-4-14","no":14,"unit":"소프트웨어 설계","q":"소프트웨어의 사용자 인터페이스개발시스템(User Interface Development System)이 가져야 할 기능이 아닌 것은?","choices":["사용자 입력의 검증","에러 처리와 에러 메시지 처리","도움과 프롬프트(prompt) 제공","소스 코드 분석 및 오류 복구"],"ans":4,"rate":77,"exp":{"concept":"사용자 인터페이스 개발 시스템(UIDS, User Interface Development System)은 사용자 인터페이스를 만들고 운영하는 데 필요한 기능을 제공한다. 사용자 입력을 검증하고, 에러를 처리하며 에러 메시지를 보여 주고, 도움말과 프롬프트를 제공하는 것이 주요 기능이다. 소스 코드 분석은 사용자 인터페이스와 관계없는 개발 도구의 일이다.","choices":[{"verdict":"오답","why":"사용자가 입력한 값이 올바른지 검사하는 것은 UIDS의 기능이다."},{"verdict":"오답","why":"에러를 처리하고 에러 메시지를 보여 주는 것은 UIDS의 기능이다."},{"verdict":"오답","why":"사용자에게 도움말과 입력 안내(프롬프트)를 제공하는 것은 UIDS의 기능이다."},{"verdict":"정답","why":"소스 코드 분석 및 오류 복구는 코드 분석 도구나 디버거의 역할로, 사용자 인터페이스 개발 시스템의 기능이 아니다."}],"keywords":[{"term":"UIDS","desc":"사용자 인터페이스 개발·운영을 지원하는 시스템"},{"term":"UIDS 주요 기능","desc":"사용자 입력 검증, 에러 처리와 에러 메시지 처리, 도움과 프롬프트 제공"}],"memo":"UIDS는 '사용자와 마주하는 일'만 한다. 소스 코드를 다루는 보기는 무관하다."}},{"id":"written-2020-4-15","no":15,"unit":"소프트웨어 설계","q":"요구 사항 명세기법에 대한 설명으로 틀린 것은?","choices":["비정형 명세기법은 사용자의 요구를 표현할 때 자연어를 기반으로 서술한다.","비정형 명세기법은 사용자의 요구를 표현할 때 Z 비정형 명세기법을 사용한다.","정형 명세기법은 사용자의 요구를 표현할 때 수학적인 원리와 표기법을 이용한다.","정형 명세기법은 비정형 명세기법에 비해 표현이 간결하다."],"ans":2,"rate":64,"wiki":[{"title":"요구사항 명세","url":"https://itwiki.kr/w/요구사항 명세"}],"exp":{"concept":"요구 사항 명세 기법은 비정형과 정형으로 나뉜다. 비정형 명세는 자연어로 서술하므로 이해하기 쉽지만 모호할 수 있다. 정형 명세는 수학적 원리와 기호를 사용해 정확하고 간결하지만 이해하기 어렵다. Z, VDM, 페트리넷(Petri-net), CSP 등이 정형 명세 언어다.","choices":[{"verdict":"오답","why":"비정형 명세 기법은 자연어(일상 언어)를 기반으로 요구를 서술한다. 맞는 설명이다."},{"verdict":"정답","why":"Z는 수학적 표기법을 쓰는 대표적인 정형 명세 언어다. 비정형 명세 기법에 쓴다는 설명은 틀렸다."},{"verdict":"오답","why":"정형 명세 기법은 수학적 원리와 표기법으로 요구를 표현한다. 맞는 설명이다."},{"verdict":"오답","why":"정형 명세는 수학 기호로 표현하므로 자연어보다 간결하다. 맞는 설명이다."}],"keywords":[{"term":"정형 명세(Formal Specification)","desc":"수학적 원리·기호로 표현, 정확하고 간결하지만 이해가 어려움"},{"term":"비정형 명세(Informal Specification)","desc":"자연어 기반 서술, 이해는 쉽지만 모호할 수 있음"},{"term":"Z 명세","desc":"집합론과 술어 논리 기반의 정형 명세 언어"}],"memo":"Z는 수학 기호 언어라 '정형'에 속한다. 'Z 비정형'이라는 말 자체가 함정이다."}},{"id":"written-2020-4-16","no":16,"unit":"소프트웨어 설계","q":"소프트웨어 개발 단계에서 요구 분석 과정에 대한 설명으로 거리가 먼 것은?","choices":["분석 결과의 문서화를 통해 향후 유지보수에 유용하게 활용 할 수 있다.","개발 비용이 가장 많이 소요되는 단계이다.","자료흐름도, 자료 사전 등이 효과적으로 이용될 수 있다.","보다 구체적인 명세를 위해 소단위 명세서(Mini-Spec)가 활용될 수 있다."],"ans":2,"rate":84,"wiki":[{"title":"요구사항 분석","url":"https://itwiki.kr/w/요구사항 분석"}],"exp":{"concept":"요구 분석은 사용자가 원하는 것을 정확히 파악해 명세서로 정리하는 단계다. 자료 흐름도(DFD), 자료 사전(DD), 소단위 명세서(Mini-Spec) 같은 도구를 쓰고, 그 결과를 문서로 남겨 이후 설계와 유지보수에 활용한다. 소프트웨어 생명 주기에서 비용이 가장 많이 드는 단계는 유지보수 단계다.","choices":[{"verdict":"오답","why":"요구 분석 결과를 문서로 남기면 나중에 유지보수할 때 근거 자료로 쓸 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"소프트웨어 생명 주기 중 비용이 가장 많이 드는 단계는 유지보수 단계다. 요구 분석 단계라는 설명은 거리가 멀다."},{"verdict":"오답","why":"자료 흐름도와 자료 사전은 구조적 요구 분석의 대표 도구다. 맞는 설명이다."},{"verdict":"오답","why":"소단위 명세서(Mini-Spec)는 DFD의 각 처리 절차를 구체적으로 기술하는 도구로 요구 분석에 쓰인다. 맞는 설명이다."}],"keywords":[{"term":"요구 분석(Requirement Analysis)","desc":"사용자 요구를 이해하고 명세서로 정리하는 단계"},{"term":"소단위 명세서(Mini-Spec)","desc":"DFD의 처리 절차를 구조적 언어 등으로 자세히 기술한 문서"},{"term":"유지보수 단계","desc":"생명 주기에서 비용이 가장 많이 드는 단계"}],"memo":"'가장 비용이 많이 드는 단계'를 물으면 언제나 유지보수다."}},{"id":"written-2020-4-17","no":17,"unit":"소프트웨어 설계","q":"애자일 방법론에 해당하지 않는 것은?","choices":["기능중심 개발","스크럼","익스트림 프로그래밍","모듈중심 개발"],"ans":4,"rate":64,"wiki":[{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"}],"exp":{"concept":"애자일(Agile) 방법론은 절차와 문서보다 사람과 소통, 변화 대응을 중시하며 짧은 주기로 반복 개발하는 방법론의 묶음이다. 대표적으로 XP(익스트림 프로그래밍), 스크럼(Scrum), 린(Lean), 기능 중심 개발(FDD), 크리스탈(Crystal), ASD, DSDM이 있다.","choices":[{"verdict":"오답","why":"기능 중심 개발(FDD, Feature Driven Development)은 신규 기능 단위로 짧게 반복 개발하는 애자일 방법론이다."},{"verdict":"오답","why":"스크럼(Scrum)은 스프린트 단위로 반복하며 팀이 스스로 일을 관리하는 애자일 방법론이다."},{"verdict":"오답","why":"익스트림 프로그래밍(XP)은 고객 참여와 짧은 릴리즈를 반복하는 대표적인 애자일 방법론이다."},{"verdict":"정답","why":"모듈 중심 개발은 애자일 방법론으로 분류되는 이름이 아니다. 출제 범위의 표준 애자일 방법론 목록에 없다."}],"keywords":[{"term":"스크럼(Scrum)","desc":"스프린트 단위 반복, 제품 책임자·스크럼 마스터·개발팀으로 구성"},{"term":"XP(eXtreme Programming)","desc":"고객 참여, 짧은 릴리즈, 테스트 주도 개발을 강조"},{"term":"FDD(Feature Driven Development)","desc":"기능(Feature) 단위로 짧게 설계·구현을 반복"},{"term":"린(Lean)","desc":"낭비를 제거하는 도요타 생산 방식을 소프트웨어 개발에 적용"}],"memo":"애자일 종류는 XP, 스크럼, 린, FDD, 크리스탈, ASD, DSDM. '기능 중심'은 있고 '모듈 중심'은 없다."}},{"id":"written-2020-4-18","no":18,"unit":"소프트웨어 설계","q":"클라이언트와 서버 간의 통신을 담당하는 시스템 소프트웨어를 무엇이라고 하는가?","choices":["웨어러블","하이웨어","미들웨어","응용 소프트웨어"],"ans":3,"rate":91,"wiki":[{"title":"미들웨어","url":"https://itwiki.kr/w/미들웨어"}],"exp":{"concept":"미들웨어(Middleware)는 이름처럼 '중간(Middle)'에 있는 소프트웨어로, 운영체제와 응용 프로그램 사이, 또는 클라이언트와 서버 사이에서 서로 통신하고 데이터를 주고받도록 이어 준다. 서로 다른 시스템을 잇는 통역사와 같다.","choices":[{"verdict":"오답","why":"웨어러블(Wearable)은 몸에 착용하는 기기(스마트워치 등)를 말한다. 통신 담당 시스템 소프트웨어가 아니다."},{"verdict":"오답","why":"하이웨어는 출제 범위의 표준 용어가 아니다."},{"verdict":"정답","why":"미들웨어는 클라이언트와 서버 사이의 통신을 담당하며 서로 다른 시스템을 연결하는 시스템 소프트웨어다."},{"verdict":"오답","why":"응용 소프트웨어는 사용자의 특정 업무(문서 작성, 회계 등)를 처리하는 프로그램이다."}],"keywords":[{"term":"미들웨어(Middleware)","desc":"클라이언트-서버, 운영체제-응용 프로그램 사이를 연결하는 소프트웨어"},{"term":"WAS(Web Application Server)","desc":"동적 웹 서비스를 처리하는 미들웨어"},{"term":"TP-Monitor","desc":"트랜잭션 처리를 감시·제어하는 미들웨어"}],"memo":"'사이에서 이어 준다'는 설명이면 미들웨어(Middle + Software)다."}},{"id":"written-2020-4-19","no":19,"unit":"소프트웨어 설계","q":"GoF(Gangs of Four) 디자인 패턴 분류에 해당하지 않는 것은?","choices":["생성 패턴","구조 패턴","행위 패턴","추상 패턴"],"ans":4,"rate":76,"exp":{"concept":"GoF(Gang of Four)는 디자인 패턴 23가지를 정리한 네 명의 저자를 말한다. 이들은 패턴을 목적에 따라 생성 패턴(객체 만들기), 구조 패턴(클래스·객체 조합하기), 행위 패턴(객체 사이의 책임 분배와 상호 작용) 세 가지로 분류했다.","choices":[{"verdict":"오답","why":"생성 패턴은 객체 생성 방법을 다루는 GoF 분류로, Singleton, Factory Method 등이 속한다."},{"verdict":"오답","why":"구조 패턴은 클래스와 객체를 조합해 더 큰 구조를 만드는 GoF 분류로, Adapter, Composite 등이 속한다."},{"verdict":"오답","why":"행위 패턴은 객체 사이의 상호 작용과 책임 분배를 다루는 GoF 분류로, Observer, Strategy 등이 속한다."},{"verdict":"정답","why":"추상 패턴은 GoF 디자인 패턴의 분류가 아니다. Abstract Factory는 생성 패턴에 속하는 패턴 이름일 뿐이다."}],"keywords":[{"term":"생성 패턴(Creational)","desc":"객체 생성 담당, 5가지: Abstract Factory, Builder, Factory Method, Prototype, Singleton"},{"term":"구조 패턴(Structural)","desc":"구조 조합 담당, 7가지: Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy"},{"term":"행위 패턴(Behavioral)","desc":"상호 작용 담당, 11가지: Observer, Strategy, Command, Iterator 등"}],"memo":"GoF 분류는 '생·구·행' 셋뿐이다. 패턴 수는 5·7·11, 합쳐서 23."}},{"id":"written-2020-4-20","no":20,"unit":"소프트웨어 설계","q":"바람직한 소프트웨어 설계 지침이 아닌 것은?","choices":["적당한 모듈의 크기를 유지한다.","모듈 간의 접속 관계를 분석하여 복잡도와 중복을 줄인다.","모듈 간의 결합도는 강할수록 바람직하다.","모듈 간의 효과적인 제어를 위해 설계에서 계층적 자료 조직이 제시되어야 한다."],"ans":3,"rate":92,"wiki":[{"title":"응집도","url":"https://itwiki.kr/w/응집도"},{"title":"결합도","url":"https://itwiki.kr/w/결합도"},{"title":"모듈화","url":"https://itwiki.kr/w/모듈화"}],"exp":{"concept":"좋은 소프트웨어 설계는 모듈을 적당한 크기로 나누고, 각 모듈은 자기 일에 집중하며(응집도는 높게), 다른 모듈에는 덜 기대도록(결합도는 낮게) 만든다. 결합도가 강하면 한 모듈을 고칠 때 다른 모듈까지 줄줄이 고쳐야 한다.","choices":[{"verdict":"오답","why":"모듈은 너무 크지도 작지도 않게 적당한 크기를 유지해야 한다. 바람직한 지침이다."},{"verdict":"오답","why":"모듈 간 접속 관계를 분석해 복잡도와 중복을 줄이는 것은 바람직한 지침이다."},{"verdict":"정답","why":"결합도는 약할수록(낮을수록) 좋다. 결합도가 강할수록 바람직하다는 설명은 틀렸다."},{"verdict":"오답","why":"모듈 간 효과적인 제어를 위해 계층적 자료 조직을 제시하는 것은 바람직한 지침이다."}],"keywords":[{"term":"결합도(Coupling)","desc":"모듈 사이의 의존 정도, 낮을수록 좋음"},{"term":"응집도(Cohesion)","desc":"모듈 내부 요소들의 관련 정도, 높을수록 좋음"},{"term":"모듈화(Modularity)","desc":"시스템을 기능 단위의 모듈로 나누는 것"}],"memo":"좋은 설계는 '결합도는 낮게, 응집도는 높게'. 결합도가 '강할수록 좋다'는 보기는 항상 오답이다."}},{"id":"written-2020-4-21","no":21,"unit":"소프트웨어 개발","q":"소프트웨어 패키징 도구 활용 시 고려 사항으로 틀린 것은?","choices":["반드시 내부 콘텐츠에 대한 암호화 및 보안을 고려한다.","보안을 위하여 이기종 연동을 고려하지 않아도 된다.","사용자 편의성을 위한 복잡성 및 비효율성 문제를 고려한다.","제품 소프트웨어 종류에 적합한 암호화 알고리즘을 적용한다."],"ans":2,"rate":92,"wiki":[{"title":"소프트웨어 패키징","url":"https://itwiki.kr/w/소프트웨어 패키징"}],"exp":{"concept":"소프트웨어 패키징은 완성된 소프트웨어를 사용자에게 배포할 수 있는 형태로 묶는 일이다. 패키징 도구를 쓸 때는 내부 콘텐츠의 암호화와 보안, 서로 다른 콘텐츠·단말기 사이의 DRM 연동, 사용자 편의성, 제품에 맞는 암호화 알고리즘을 고려해야 한다.","choices":[{"verdict":"오답","why":"패키징 도구는 반드시 내부 콘텐츠의 암호화와 보안을 고려해야 한다. 맞는 고려 사항이다."},{"verdict":"정답","why":"패키징 도구는 이기종 콘텐츠와 단말기 사이의 DRM 연동을 고려해야 한다. 이기종 연동을 고려하지 않아도 된다는 설명은 틀렸다."},{"verdict":"오답","why":"보안을 강화하면 사용이 불편해질 수 있으므로 사용자 편의성을 위한 복잡성과 비효율성 문제를 고려한다. 맞는 고려 사항이다."},{"verdict":"오답","why":"제품 소프트웨어 종류에 맞는 암호화 알고리즘을 적용해야 한다. 맞는 고려 사항이다."}],"keywords":[{"term":"소프트웨어 패키징","desc":"모듈별로 만든 실행 파일을 묶어 배포용 설치 파일로 만드는 것"},{"term":"패키징 도구","desc":"배포 콘텐츠를 암호화·보안 처리해 배포 가능한 형태로 만드는 도구"},{"term":"DRM(Digital Rights Management)","desc":"디지털 콘텐츠의 저작권을 보호하고 이용을 통제하는 기술"}],"memo":"패키징 도구 고려 사항은 '암호화·보안, 이기종 연동, 사용자 편의성, 알맞은 암호 알고리즘'. '고려하지 않아도 된다'는 보기는 의심한다."}},{"id":"written-2020-4-22","no":22,"unit":"소프트웨어 개발","q":"EAI(Enterprise Application Integration) 구축유형 중 Hybrid에 대한 설명으로 틀린 것은?","choices":["Hub &Spoke와 Message Bus의 혼합방식이다.","필요한 경우 한 가지 방식으로 EAI구현이 가능하다.","데이터 병목현상을 최소화할 수 있다.","중간에 미들웨어를 두지 않고 각 애플리케이션을 point to point로 연결한다."],"ans":4,"rate":71,"exp":{"concept":"EAI(Enterprise Application Integration)는 기업 안의 여러 애플리케이션을 연결해 정보를 주고받게 하는 솔루션이다. 구축 유형으로 Point-to-Point, Hub & Spoke, Message Bus, Hybrid가 있다. Hybrid는 그룹 안은 Hub & Spoke, 그룹 사이는 Message Bus 방식으로 섞어 쓰는 형태다.","choices":[{"verdict":"오답","why":"Hybrid는 Hub & Spoke와 Message Bus를 혼합한 방식이다. 맞는 설명이다."},{"verdict":"오답","why":"Hybrid는 필요한 경우 한 가지 방식으로도 EAI를 구현할 수 있어 유연하다. 맞는 설명이다."},{"verdict":"오답","why":"Hybrid는 두 방식을 섞어 한 허브에 몰리는 데이터 병목 현상을 최소화할 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"미들웨어 없이 애플리케이션을 1:1로 직접 연결하는 것은 Point-to-Point 방식이다. Hybrid의 설명이 아니다."}],"keywords":[{"term":"Point-to-Point","desc":"미들웨어 없이 애플리케이션끼리 1:1로 직접 연결"},{"term":"Hub & Spoke","desc":"중앙 허브를 거쳐 연결하는 중앙 집중형, 허브 장애 시 전체 영향"},{"term":"Message Bus(ESB)","desc":"애플리케이션 사이에 미들웨어(버스)를 두어 처리, 확장성 높음"},{"term":"Hybrid","desc":"그룹 내부는 Hub & Spoke, 그룹 간은 Message Bus"}],"memo":"'미들웨어를 두지 않고 직접 연결'은 Point-to-Point만의 특징이다."}},{"id":"written-2020-4-23","no":23,"unit":"소프트웨어 개발","q":"소스코드 품질분석 도구 중 정적분석 도구가 아닌 것은?","choices":["pmd","checkstyle","valance","cppcheck"],"ans":3,"rate":65,"exp":{"concept":"정적 분석은 프로그램을 실행하지 않고 소스 코드만 읽어 코딩 표준 위반, 잠재적 오류 등을 찾는 방법이다. 대표 도구로 pmd, checkstyle, cppcheck, SonarQube, ccm, cobertura가 있다. 반대로 동적 분석은 프로그램을 실제로 실행하면서 메모리 누수 같은 문제를 찾으며, Avalanche, Valgrind가 대표 도구다.","choices":[{"verdict":"오답","why":"pmd는 자바 등의 소스 코드에서 미사용 변수, 중복 코드 같은 문제를 찾는 정적 분석 도구다."},{"verdict":"오답","why":"checkstyle은 자바 코드가 코딩 표준을 지키는지 검사하는 정적 분석 도구다."},{"verdict":"정답","why":"valance는 정적 분석 도구 목록에 들지 않는다. 이름이 비슷한 Avalanche, Valgrind는 프로그램을 실행하며 분석하는 동적 분석 도구다."},{"verdict":"오답","why":"cppcheck는 C/C++ 코드의 메모리 누수, 버퍼 오버플로 같은 결함을 찾는 정적 분석 도구다."}],"keywords":[{"term":"정적 분석(Static Analysis)","desc":"실행하지 않고 소스 코드를 분석"},{"term":"동적 분석(Dynamic Analysis)","desc":"프로그램을 실행하며 메모리 누수·스레드 결함 등을 분석"},{"term":"정적 분석 도구","desc":"pmd, checkstyle, cppcheck, SonarQube, ccm, cobertura"},{"term":"동적 분석 도구","desc":"Avalanche, Valgrind"}],"memo":"동적 분석 도구는 Avalanche와 Valgrind 둘만 외우면 된다. valance는 두 이름과 비슷하게 지은 보기일 뿐 어느 목록에도 없다."}},{"id":"written-2020-4-24","no":24,"unit":"소프트웨어 개발","q":"다음 Postfix 연산식에 대한 연산결과로 옳은 것은?\n<img src=\"data/img/eip_written_20200926_024.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["35","42","77","360"],"ans":2,"rate":88,"wiki":[{"title":"후위식","url":"https://itwiki.kr/w/후위식"}],"exp":{"concept":"후위 표기식(Postfix)은 연산자가 피연산자 뒤에 오는 표기법이다. 스택으로 계산하는데, 숫자는 스택에 넣고 연산자를 만나면 스택에서 두 수를 꺼내 계산한 뒤 결과를 다시 넣는다. 식 3 4 * 5 6 * +를 계산하면 3*4=12, 5*6=30, 12+30=42다.","choices":[{"verdict":"오답","why":"35는 이 식의 계산 결과가 아니다. 3*4=12와 5*6=30을 더하면 42다."},{"verdict":"정답","why":"3 4 *에서 12, 5 6 *에서 30, 마지막 +에서 12+30=42가 된다."},{"verdict":"오답","why":"77은 (3+4)*(5+6)처럼 *와 +를 서로 바꿔 계산한 값이다. 앞의 두 수는 곱하고(12), 뒤의 두 수도 곱한 뒤(30), 마지막에 더해야 한다."},{"verdict":"오답","why":"360은 12와 30을 곱한 값이다. 마지막 연산자는 *가 아니라 +이다."}],"keywords":[{"term":"후위 표기법(Postfix)","desc":"연산자가 피연산자 뒤에 오는 표기, 예: A B +"},{"term":"전위 표기법(Prefix)","desc":"연산자가 피연산자 앞에 오는 표기, 예: + A B"},{"term":"중위 표기법(Infix)","desc":"연산자가 피연산자 사이에 오는 일반 표기, 예: A + B"}],"memo":"후위식은 '숫자 두 개 + 연산자' 묶음을 앞에서부터 괄호로 묶으면 중위식 (3*4)+(5*6)으로 바로 바뀐다."}},{"id":"written-2020-4-25","no":25,"unit":"소프트웨어 개발","q":"인터페이스 보안을 위해 네트워크 영역에 적용될 수 있는 것으로 거리가 먼 것은?","choices":["IPSec","SSL","SMTP","S-HTTP"],"ans":3,"rate":74,"wiki":[{"title":"IPSec","url":"https://itwiki.kr/w/IPSec"},{"title":"SSL","url":"https://itwiki.kr/w/SSL"}],"exp":{"concept":"인터페이스 보안은 시스템과 시스템이 데이터를 주고받는 구간을 보호하는 것이다. 네트워크 영역에서는 전송 데이터를 암호화하는 보안 프로토콜을 쓰는데, 네트워크 계층의 IPSec, 전송 계층의 SSL/TLS, 응용 계층의 S-HTTP가 대표적이다. SMTP는 그냥 메일을 보내는 프로토콜이다.","choices":[{"verdict":"오답","why":"IPSec(IP Security)은 네트워크 계층에서 IP 패킷 단위로 암호화와 인증을 제공하는 보안 프로토콜이다."},{"verdict":"오답","why":"SSL(Secure Sockets Layer)은 전송 계층과 응용 계층 사이에서 데이터를 암호화해 주고받게 하는 보안 프로토콜이다."},{"verdict":"정답","why":"SMTP(Simple Mail Transfer Protocol)는 전자 우편을 전송하는 프로토콜이다. 보안 기능을 위한 프로토콜이 아니다."},{"verdict":"오답","why":"S-HTTP(Secure HTTP)는 웹에서 주고받는 메시지를 암호화하는 응용 계층 보안 프로토콜이다."}],"keywords":[{"term":"IPSec","desc":"네트워크 계층에서 IP 패킷을 암호화·인증하는 보안 프로토콜"},{"term":"SSL/TLS","desc":"전송 계층 위에서 데이터를 암호화하는 보안 프로토콜"},{"term":"S-HTTP","desc":"웹 메시지 자체를 암호화하는 응용 계층 보안 프로토콜"},{"term":"SMTP","desc":"전자 우편 전송 프로토콜, 포트 25"}],"memo":"보안 프로토콜은 이름에 Sec, Secure, S가 붙는다. SMTP의 S는 Simple이다."}},{"id":"written-2020-4-26","no":26,"unit":"소프트웨어 개발","q":"검증(Validation) 검사 기법 중 개발자의 장소에서 사용자가 개발자 앞에서 행해지며, 오류와 사용상의 문제점을 사용자와 개발자가 함께 확인하면서 검사하는 기법은?","choices":["디버깅 검사","형상 검사","자료구조 검사","알파 검사"],"ans":4,"rate":79,"wiki":[{"title":"확인과 검증","url":"https://itwiki.kr/w/확인과 검증"},{"title":"소프트웨어 테스트","url":"https://itwiki.kr/w/소프트웨어 테스트"}],"exp":{"concept":"검증(Validation) 검사는 완성된 소프트웨어가 사용자의 요구를 만족하는지 확인하는 테스트로, 알파 검사와 베타 검사가 대표적이다. 알파 검사는 개발자의 장소에서 사용자가 개발자 앞에서 사용해 보며 문제를 함께 확인한다. 베타 검사는 개발자 없이 사용자의 장소에서 실제 환경으로 사용해 보는 검사다.","choices":[{"verdict":"오답","why":"디버깅은 테스트로 발견된 오류의 원인을 찾아 고치는 작업이다. 검증 검사 기법이 아니다."},{"verdict":"오답","why":"형상 검사는 소프트웨어 구성 요소, 목록, 유지보수에 필요한 정보가 빠짐없이 갖춰졌는지 확인하는 검사다."},{"verdict":"오답","why":"자료구조 검사는 출제 범위의 표준 검증 검사 기법이 아니다."},{"verdict":"정답","why":"알파 검사는 개발자의 장소에서 사용자가 개발자 앞에서 수행하며, 통제된 환경에서 오류와 사용상 문제를 함께 확인한다."}],"keywords":[{"term":"알파 테스트(Alpha Test)","desc":"개발자 장소, 개발자가 지켜보는 통제된 환경에서 사용자가 수행"},{"term":"베타 테스트(Beta Test)","desc":"사용자 장소, 개발자 없이 실제 환경에서 사용자가 수행"},{"term":"검증(Validation)","desc":"사용자 요구에 맞는 제품을 만들었는지 확인"}],"memo":"알파는 '개발자 앞에서', 베타는 '개발자 없이'. 장소와 개발자 동석 여부로 구분한다."}},{"id":"written-2020-4-27","no":27,"unit":"소프트웨어 개발","q":"다음 초기 자료에 대하여 삽입 정렬(Insertion Sort)을 이용하여 오름차순 정렬할 경우 1회전 후의 결과는?\n<img src=\"data/img/eip_written_20200926_027.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["3, 4, 8, 7, 9","3, 4, 9, 7, 8","7, 8, 3, 4, 9","3, 8, 4, 9, 7"],"ans":4,"rate":68,"wiki":[{"title":"정렬 알고리즘","url":"https://itwiki.kr/w/정렬 알고리즘"},{"title":"삽입 정렬","url":"https://itwiki.kr/w/삽입 정렬"}],"exp":{"concept":"삽입 정렬은 카드 게임에서 손에 든 카드를 정리하듯, 두 번째 값부터 하나씩 꺼내 앞쪽의 이미 정렬된 부분에서 알맞은 자리에 끼워 넣는 정렬이다. 초기 자료 8, 3, 4, 9, 7에서 1회전은 두 번째 값 3을 앞의 8과 비교해 8 앞에 넣는 것이므로 3, 8, 4, 9, 7이 된다.","choices":[{"verdict":"오답","why":"3, 4, 8, 7, 9는 1회전 결과가 아니다. 1회전에서는 두 번째 값 3만 제자리를 찾는다."},{"verdict":"오답","why":"3, 4, 9, 7, 8은 삽입 정렬의 어느 회전 결과에도 해당하지 않는다."},{"verdict":"오답","why":"7, 8, 3, 4, 9는 삽입 정렬의 1회전 결과가 아니다. 1회전에서는 앞의 두 값(8, 3)만 정렬된다."},{"verdict":"정답","why":"두 번째 값 3을 꺼내 8과 비교하면 3이 작으므로 8을 뒤로 밀고 3을 맨 앞에 넣는다. 결과는 3, 8, 4, 9, 7이다."}],"keywords":[{"term":"삽입 정렬(Insertion Sort)","desc":"정렬된 앞부분에 다음 값을 알맞은 위치에 끼워 넣는 정렬, 평균 O(n²)"},{"term":"선택 정렬(Selection Sort)","desc":"남은 값 중 최솟값을 골라 맨 앞과 교환"},{"term":"버블 정렬(Bubble Sort)","desc":"인접한 두 값을 비교해 교환하며 큰 값을 뒤로 보냄"}],"memo":"삽입 정렬 n회전 후에는 앞의 n+1개만 정렬되어 있고 나머지는 처음 순서 그대로다. 뒷부분이 바뀐 보기는 지운다."}},{"id":"written-2020-4-28","no":28,"unit":"소프트웨어 개발","q":"소프트웨어 설치 매뉴얼에 대한 설명으로 틀린 것은?","choices":["설치과정에서 표시될 수 있는 예외상황에 관련 내용을 별도로 구분하여 설명한다.","설치 시작부터 완료할 때까지의 전 과정을 빠짐없이 순서대로 설명한다.","설치 매뉴얼은 개발자 기준으로 작성한다.","설치 매뉴얼에는 목차, 개요, 기본사항 등이 기본적으로 포함되어야 한다."],"ans":3,"rate":94,"exp":{"concept":"소프트웨어 설치 매뉴얼은 사용자가 처음 소프트웨어를 설치할 때 따라 하는 안내서다. 그래서 개발자가 아니라 사용자 기준으로, 설치 시작부터 완료까지 순서대로 빠짐없이 쓰고, 예외 상황은 따로 정리해 설명한다.","choices":[{"verdict":"오답","why":"설치 중 나타날 수 있는 예외 상황은 별도로 구분해 설명해야 한다. 맞는 설명이다."},{"verdict":"오답","why":"설치 시작부터 완료까지 전 과정을 빠짐없이 순서대로 설명해야 한다. 맞는 설명이다."},{"verdict":"정답","why":"설치 매뉴얼은 실제로 설치하는 사용자 기준으로 작성해야 한다. 개발자 기준이라는 설명은 틀렸다."},{"verdict":"오답","why":"설치 매뉴얼에는 목차, 개요, 기본 사항 등이 기본으로 포함되어야 한다. 맞는 설명이다."}],"keywords":[{"term":"설치 매뉴얼","desc":"사용자 기준으로 설치 과정을 순서대로 설명하는 문서"},{"term":"사용자 매뉴얼","desc":"사용자가 소프트웨어를 사용하는 방법을 설명하는 문서"}],"memo":"매뉴얼 문제에서 '개발자 기준'이 나오면 틀린 보기다. 매뉴얼은 언제나 사용자 기준."}},{"id":"written-2020-4-29","no":29,"unit":"소프트웨어 개발","q":"인터페이스 구현 검증 도구가 아닌 것은?","choices":["ESB","xUnit","STAF","NTAF"],"ans":1,"rate":60,"exp":{"concept":"인터페이스 구현 검증 도구는 시스템 사이의 인터페이스가 제대로 동작하는지 테스트하는 도구다. xUnit, STAF, FitNesse, NTAF, Selenium, watir 등이 있다. ESB는 인터페이스를 검증하는 도구가 아니라 애플리케이션들을 연결해 주는 통합 미들웨어다.","choices":[{"verdict":"정답","why":"ESB(Enterprise Service Bus)는 애플리케이션 사이를 버스 형태의 미들웨어로 연결하는 통합 방식이다. 인터페이스 구현 검증 도구가 아니다."},{"verdict":"오답","why":"xUnit은 JUnit, CppUnit, NUnit처럼 여러 언어를 지원하는 단위 테스트 프레임워크로, 인터페이스 구현 검증 도구다."},{"verdict":"오답","why":"STAF는 서비스 호출, 컴포넌트 재사용 등 다양한 환경을 지원하는 테스트 프레임워크로, 분산 환경 각 테스트 대상에 데몬을 두고 테스트한다."},{"verdict":"오답","why":"NTAF는 NHN의 테스트 자동화 프레임워크로, STAF와 FitNesse를 통합한 인터페이스 구현 검증 도구다."}],"keywords":[{"term":"xUnit","desc":"Java(JUnit), C++(CppUnit), .Net(NUnit) 등을 지원하는 단위 테스트 프레임워크"},{"term":"STAF","desc":"분산 환경에 데몬을 두고 테스트하는 프레임워크"},{"term":"FitNesse","desc":"웹 기반 테스트 케이스 설계·실행·결과 확인 프레임워크"},{"term":"NTAF","desc":"STAF와 FitNesse를 통합한 NHN의 테스트 자동화 프레임워크"},{"term":"ESB(Enterprise Service Bus)","desc":"애플리케이션 통합을 위한 버스형 미들웨어"}],"memo":"검증 도구는 '테스트 프레임워크' 이름들(xUnit, STAF, FitNesse, NTAF, Selenium, watir)이다. ESB는 연계(통합) 쪽이다."}},{"id":"written-2020-4-30","no":30,"unit":"소프트웨어 개발","q":"소프트웨어 형상 관리에서 관리 항목에 포함되지 않는 것은?","choices":["프로젝트 요구 분석서","소스 코드","운영 및 설치 지침서","프로젝트 개발 비용"],"ans":4,"rate":77,"wiki":[{"title":"형상 관리","url":"https://itwiki.kr/w/형상 관리"}],"exp":{"concept":"형상 관리(SCM, Software Configuration Management)는 개발 과정에서 만들어지는 산출물의 변경을 추적하고 통제하는 활동이다. 관리 대상(형상 항목)은 요구 분석서, 설계서, 소스 코드, 운영 및 설치 지침서, 테스트 자료처럼 개발 중 만들어지는 산출물이다. 개발 비용 같은 관리 정보는 형상 항목이 아니다.","choices":[{"verdict":"오답","why":"프로젝트 요구 분석서는 개발 산출물로 형상 관리 항목이다."},{"verdict":"오답","why":"소스 코드는 가장 대표적인 형상 관리 항목이다."},{"verdict":"오답","why":"운영 및 설치 지침서도 개발 과정의 산출물로 형상 관리 항목이다."},{"verdict":"정답","why":"프로젝트 개발 비용은 프로젝트 관리 정보이지 소프트웨어 산출물이 아니므로 형상 관리 항목에 포함되지 않는다."}],"keywords":[{"term":"형상 관리(SCM)","desc":"소프트웨어 변경 사항을 관리하는 활동"},{"term":"형상 관리 절차","desc":"형상 식별 → 형상 통제 → 형상 감사 → 형상 기록"},{"term":"형상 항목(CI, Configuration Item)","desc":"형상 관리 대상이 되는 산출물"}],"memo":"형상 관리 대상은 '문서와 코드 같은 산출물'이다. 비용·인력 같은 관리 숫자는 해당 없다."}},{"id":"written-2020-4-31","no":31,"unit":"소프트웨어 개발","q":"다음 설명에 해당하는 것은?\n<img src=\"data/img/eip_written_20200926_031.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["외부 스키마","내부 스키마","개념 스키마","슈퍼 스키마"],"ans":2,"rate":68,"wiki":[{"title":"스키마","url":"https://itwiki.kr/w/스키마"}],"exp":{"concept":"데이터베이스 스키마는 보는 관점에 따라 외부, 개념, 내부 스키마로 나뉜다. 외부 스키마는 사용자 각자가 보는 부분, 개념 스키마는 조직 전체의 논리적 구조, 내부 스키마는 실제 저장 장치에 데이터가 어떻게 저장되는지를 정의한다. 지문의 '물리적 저장 장치의 입장', '레코드 형식', '내부 레코드의 물리적 순서'는 내부 스키마의 특징이다.","choices":[{"verdict":"오답","why":"외부 스키마는 사용자나 응용 프로그래머 각자의 입장에서 본 논리적 구조로, 서브 스키마라고도 한다."},{"verdict":"정답","why":"내부 스키마는 물리적 저장 장치 입장에서 본 구조로, 저장 레코드의 형식, 데이터 항목의 표현 방법, 레코드의 물리적 순서를 정의한다."},{"verdict":"오답","why":"개념 스키마는 조직 전체의 관점에서 본 데이터베이스의 전체적인 논리 구조다."},{"verdict":"오답","why":"슈퍼 스키마는 3단계 스키마에 속하지 않으며 출제 범위의 표준 용어가 아니다."}],"keywords":[{"term":"외부 스키마(External Schema)","desc":"사용자·응용 프로그램 관점의 논리 구조, 서브 스키마"},{"term":"개념 스키마(Conceptual Schema)","desc":"조직 전체 관점의 논리 구조, 보통 스키마라 하면 이것"},{"term":"내부 스키마(Internal Schema)","desc":"물리적 저장 장치 관점의 구조"}],"memo":"'물리적'이 보이면 내부 스키마, '조직 전체'면 개념 스키마, '사용자 각자'면 외부 스키마."}},{"id":"written-2020-4-32","no":32,"unit":"소프트웨어 개발","q":"다음 트리에 대한 INORDER 운행 결과는?\n<img src=\"data/img/eip_written_20200926_032.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["D B A E C F","A B D C E F","D B E C F A","A B C D E F"],"ans":1,"rate":65,"wiki":[{"title":"순회","url":"https://itwiki.kr/w/순회"},{"title":"트리","url":"https://itwiki.kr/w/트리"}],"exp":{"concept":"트리 순회는 노드를 방문하는 순서를 정하는 방법이다. 중위 순회(Inorder)는 왼쪽 서브트리 → 루트 → 오른쪽 서브트리 순으로 방문한다. 그림의 트리는 A가 루트이고, A의 왼쪽 자식 B 아래에 왼쪽 자식 D, A의 오른쪽 자식 C 아래에 왼쪽 E와 오른쪽 F가 있다. 왼쪽 서브트리(D, B), 루트 A, 오른쪽 서브트리(E, C, F) 순서이므로 D B A E C F가 된다.","choices":[{"verdict":"정답","why":"왼쪽 서브트리에서 D, B, 루트 A, 오른쪽 서브트리에서 E, C, F 순으로 방문한 중위 순회 결과다."},{"verdict":"오답","why":"A B D C E F는 루트 → 왼쪽 → 오른쪽 순인 전위 순회(Preorder) 결과다."},{"verdict":"오답","why":"D B E C F A는 어느 순회 결과도 아니다. 후위 순회(왼쪽 → 오른쪽 → 루트)는 C의 두 자식 E, F를 먼저 방문한 뒤 C를 방문하므로 D B E F C A다."},{"verdict":"오답","why":"A B C D E F는 위층부터 왼쪽에서 오른쪽으로 차례대로 방문한 레벨 순서 결과로, 중위 순회가 아니다."}],"keywords":[{"term":"전위 순회(Preorder)","desc":"Root → Left → Right"},{"term":"중위 순회(Inorder)","desc":"Left → Root → Right"},{"term":"후위 순회(Postorder)","desc":"Left → Right → Root"}],"memo":"전·중·후는 루트(Root)를 언제 방문하느냐로 정해진다. 중위는 루트가 가운데, 결과 맨 앞이 루트면 중위가 아니다."}},{"id":"written-2020-4-33","no":33,"unit":"소프트웨어 개발","q":"n 개의 노드로 구성된 무방향 그래프의 최대 간선수는?","choices":["n－1","n／2","n(n－1)／2","n(n＋1)"],"ans":3,"rate":79,"exp":{"concept":"무방향 그래프에서 간선이 가장 많은 경우는 모든 노드가 서로 하나씩 연결된 완전 그래프다. n개의 노드 중 2개를 고르는 경우의 수만큼 간선이 생기므로 n(n-1)/2개다. 예를 들어 노드 4개면 4×3/2=6개다.","choices":[{"verdict":"오답","why":"n-1은 n개의 노드를 모두 연결하는 데 필요한 최소 간선 수(신장 트리의 간선 수)다."},{"verdict":"오답","why":"n/2는 그래프의 최대 간선 수와 관계없는 값이다."},{"verdict":"정답","why":"n개 노드에서 2개를 고르는 조합 수 nC2 = n(n-1)/2가 무방향 완전 그래프의 간선 수, 즉 최대 간선 수다."},{"verdict":"오답","why":"n(n+1)은 최대 간선 수 공식이 아니다. 방향 그래프의 최대 간선 수는 n(n-1)이다."}],"keywords":[{"term":"무방향 완전 그래프","desc":"최대 간선 수 n(n-1)/2"},{"term":"방향 완전 그래프","desc":"최대 간선 수 n(n-1)"},{"term":"신장 트리(Spanning Tree)","desc":"모든 노드를 잇는 사이클 없는 부분 그래프, 간선 n-1개"}],"memo":"방향 그래프는 A→B와 B→A를 따로 세므로 n(n-1), 무방향은 그 절반인 n(n-1)/2."}},{"id":"written-2020-4-34","no":34,"unit":"소프트웨어 개발","q":"다음이 설명하는 테스트 용어는?\n<img src=\"data/img/eip_written_20200926_034.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["테스트 케이스","테스트 시나리오","테스트 오라클","테스트 데이터"],"ans":3,"rate":54,"wiki":[{"title":"테스트 오라클","url":"https://itwiki.kr/w/테스트 오라클"}],"exp":{"concept":"테스트 오라클(Test Oracle)은 테스트 결과가 맞는지 틀렸는지 판단하기 위해 미리 정의해 둔 참 값을 입력해 결과와 비교하는 기법이나 활동이다. 시험 답안지를 채점하는 정답표와 같다. 종류에는 참(True) 오라클, 샘플링(Sampling) 오라클, 휴리스틱(Heuristic, 추정) 오라클, 일관성 검사(Consistent) 오라클이 있다.","choices":[{"verdict":"오답","why":"테스트 케이스는 특정 요구 사항을 확인하려고 만든 입력 값, 실행 조건, 기대 결과의 집합이다."},{"verdict":"오답","why":"테스트 시나리오는 여러 테스트 케이스를 묶어 동작 순서대로 기술한 문서다."},{"verdict":"정답","why":"테스트 오라클은 사전에 정의된 참 값과 비교해 테스트 결과의 참·거짓을 판단하는 기법이며, 참, 샘플링, 휴리스틱, 일관성 검사 오라클이 있다."},{"verdict":"오답","why":"테스트 데이터는 테스트를 실행할 때 사용하는 입력 데이터다."}],"keywords":[{"term":"참 오라클(True Oracle)","desc":"모든 입력 값에 대해 기대 결과를 제공해 모든 오류를 검출"},{"term":"샘플링 오라클(Sampling Oracle)","desc":"특정 몇 개의 입력 값에 대해서만 기대 결과 제공"},{"term":"휴리스틱 오라클(Heuristic Oracle)","desc":"특정 입력 값은 기대 결과를 주고 나머지는 추정으로 처리"},{"term":"일관성 검사 오라클(Consistent Oracle)","desc":"변경 전후의 결과 값이 같은지 확인"}],"memo":"'참 값과 비교해 판단'이 나오면 오라클. 종류는 '참·샘·휴·일'로 외운다."}},{"id":"written-2020-4-35","no":35,"unit":"소프트웨어 개발","q":"빌드 자동화 도구에 대한 설명으로 틀린 것은?","choices":["Gradle은 실행할 처리 명령들을 모아 태스크로 만든 후 태스크 단위로 실행한다.","빌드 자동화 도구는 지속적인 통합개발환경 에 서 유용하게 활용된다.","빌드 자동화 도구에는 Ant, Gradle, Jenkins등이 있다.","Jenkins는 Groovy 기반으로 한 오픈소스로 안드로이드 앱 개발 환경에서 사용된다."],"ans":4,"rate":65,"exp":{"concept":"빌드 자동화 도구는 소스 코드를 컴파일하고 묶어 실행 가능한 결과물로 만드는 과정을 자동으로 처리한다. Ant, Maven, Gradle, Jenkins가 대표적이다. Jenkins는 자바 기반의 빌드 자동화 도구로 지속적 통합(CI) 서버로 많이 쓰이고, 그루비(Groovy) 기반으로 안드로이드 앱 개발 환경에서 쓰이는 것은 Gradle이다.","choices":[{"verdict":"오답","why":"Gradle은 실행할 처리 명령을 모아 태스크(Task)로 만들고 태스크 단위로 실행한다. 맞는 설명이다."},{"verdict":"오답","why":"빌드 자동화 도구는 코드를 자주 통합하는 지속적 통합 개발 환경에서 유용하다. 맞는 설명이다."},{"verdict":"오답","why":"Ant, Gradle, Jenkins는 모두 빌드 자동화 도구로 분류된다. 맞는 설명이다."},{"verdict":"정답","why":"Jenkins는 자바 기반의 오픈소스 도구다. 그루비(Groovy) 기반으로 안드로이드 앱 개발 환경에서 쓰이는 것은 Gradle이므로 틀린 설명이다."}],"keywords":[{"term":"Jenkins","desc":"자바 기반 오픈소스 빌드 자동화 도구, 서블릿 컨테이너에서 실행되는 서버 기반 도구로 지속적 통합(CI)에 많이 쓰임"},{"term":"Gradle","desc":"그루비 기반 오픈소스, 안드로이드 공식 빌드 도구, 태스크 단위 실행"},{"term":"Ant","desc":"아파치 재단의 자바 빌드 도구, XML 기반 빌드 스크립트"},{"term":"Maven","desc":"아파치 재단의 빌드 도구, 의존성 관리에 강함"}],"memo":"Groovy 기반·안드로이드는 Gradle, 자바 기반·CI 서버는 Jenkins. 둘을 맞바꾼 보기가 단골 함정이다."}},{"id":"written-2020-4-36","no":36,"unit":"소프트웨어 개발","q":"저작권 관리 구성 요소에 대한 설명이 틀린 것은?","choices":["콘텐츠 제공자(Contents Provider) : 콘텐츠를 제공하는 저작권자","콘텐츠 분배자(Contents Distributor) : 콘텐츠를 메타 데이터와 함께 배포 가능한 단위로 묶는 기능","클리어링 하우스(Clearing House) : 키 관리 및 라이선스 발급 관리","DRM 컨트롤러 : 배포된 콘텐츠의 이용 권한을 통제"],"ans":2,"rate":64,"exp":{"concept":"디지털 저작권 관리(DRM)는 여러 구성 요소가 역할을 나눠 맡는다. 콘텐츠 제공자는 콘텐츠를 만든 저작권자, 패키저(Packager)는 콘텐츠를 메타데이터와 함께 배포 가능한 단위로 묶는 프로그램, 콘텐츠 분배자는 암호화된 콘텐츠를 유통하는 쇼핑몰 같은 곳이다. 클리어링 하우스는 키와 라이선스를 관리하고, DRM 컨트롤러는 이용 권한을 통제한다.","choices":[{"verdict":"오답","why":"콘텐츠 제공자(Contents Provider)는 콘텐츠를 제공하는 저작권자다. 맞는 연결이다."},{"verdict":"정답","why":"콘텐츠를 메타데이터와 함께 배포 가능한 단위로 묶는 것은 패키저(Packager)의 기능이다. 콘텐츠 분배자는 암호화된 콘텐츠를 유통하는 곳이므로 틀린 설명이다."},{"verdict":"오답","why":"클리어링 하우스(Clearing House)는 저작권에 대한 사용 권한, 라이선스 발급, 키 관리, 사용량에 따른 결제를 관리한다. 맞는 연결이다."},{"verdict":"오답","why":"DRM 컨트롤러는 배포된 콘텐츠의 이용 권한을 통제한다. 맞는 연결이다."}],"keywords":[{"term":"콘텐츠 분배자(Contents Distributor)","desc":"암호화된 콘텐츠를 유통하는 곳(쇼핑몰 등)"},{"term":"패키저(Packager)","desc":"콘텐츠를 메타데이터와 함께 배포 단위로 묶는 프로그램"},{"term":"클리어링 하우스(Clearing House)","desc":"키 관리, 라이선스 발급, 사용량 결제 관리"},{"term":"보안 컨테이너","desc":"콘텐츠 원본을 안전하게 유통하기 위한 전자적 보안 장치"}],"memo":"'묶는다(패키징)'는 패키저, '유통한다'는 분배자. 이름 그대로 연결한다."}},{"id":"written-2020-4-37","no":37,"unit":"소프트웨어 개발","q":"블랙박스 테스트 기법으로 거리가 먼 것은?","choices":["기초 경로 검사","동치 클래스 분해","경계값 분석","원인 결과 그래프"],"ans":1,"rate":63,"wiki":[{"title":"블랙박스 테스트","url":"https://itwiki.kr/w/블랙박스 테스트"},{"title":"화이트박스 테스트","url":"https://itwiki.kr/w/화이트박스 테스트"}],"exp":{"concept":"블랙박스 테스트는 프로그램 내부를 보지 않고 입력과 출력만으로 기능이 맞는지 확인하는 테스트다. 동치 분할, 경계값 분석, 원인-효과(원인-결과) 그래프, 오류 예측, 비교 검사가 있다. 반대로 화이트박스 테스트는 코드 내부 구조를 보며 경로를 검사하며, 기초 경로 검사와 제어 구조 검사가 있다.","choices":[{"verdict":"정답","why":"기초 경로 검사(Basis Path Testing)는 코드의 논리 흐름을 보고 실행 경로를 정의하는 화이트박스 테스트 기법이다."},{"verdict":"오답","why":"동치 클래스 분해(동치 분할)는 입력 자료를 유효·무효 그룹으로 나누어 대표 값으로 검사하는 블랙박스 테스트 기법이다."},{"verdict":"오답","why":"경계값 분석은 입력 범위의 경계 부근에서 오류가 잘 난다는 점을 이용한 블랙박스 테스트 기법이다."},{"verdict":"오답","why":"원인-결과 그래프는 입력(원인)과 출력(결과)의 관계를 그래프로 분석해 테스트 케이스를 만드는 블랙박스 테스트 기법이다."}],"keywords":[{"term":"블랙박스 테스트","desc":"동치 분할, 경계값 분석, 원인-효과 그래프, 오류 예측, 비교 검사"},{"term":"화이트박스 테스트","desc":"기초 경로 검사, 제어 구조 검사(조건·루프·데이터 흐름)"},{"term":"기초 경로 검사","desc":"McCabe 복잡도로 독립 경로를 구해 검사하는 화이트박스 기법"}],"memo":"'경로·구조·루프·조건'이 들어가면 화이트박스, '값·분할·그래프·예측'은 블랙박스."}},{"id":"written-2020-4-38","no":38,"unit":"소프트웨어 개발","q":"해싱함수 중 레코드 키를 여러 부분으로 나누고, 나눈 부분의 각 숫자를 더하거나 XOR한 값을 홈 주소로 사용하는 방식은?","choices":["제산법","폴딩법","기수변환법","숫자분석법"],"ans":2,"rate":56,"wiki":[{"title":"해시","url":"https://itwiki.kr/w/해시"}],"exp":{"concept":"해싱 함수는 레코드 키를 계산해 저장할 주소(홈 주소)를 정하는 함수다. 폴딩법(Folding)은 종이를 접듯이 키를 여러 부분으로 나눈 뒤 각 부분을 더하거나 XOR(배타적 논리합)한 값을 홈 주소로 쓴다.","choices":[{"verdict":"오답","why":"제산법(Division)은 키를 해시표 크기보다 큰 수 중 가장 작은 소수로 나눈 나머지를 홈 주소로 쓰는 방식이다."},{"verdict":"정답","why":"폴딩법은 키를 여러 부분으로 나누고 각 부분을 더하거나 XOR한 값을 홈 주소로 쓰는 방식이다."},{"verdict":"오답","why":"기수 변환법(Radix)은 키의 숫자를 다른 진법으로 변환한 뒤 주소 범위를 넘는 높은 자리를 잘라 홈 주소로 쓰는 방식이다."},{"verdict":"오답","why":"숫자 분석법(Digit Analysis)은 키의 각 자리 숫자 분포를 분석해 고르게 분포된 자리들을 골라 홈 주소로 쓰는 방식이다."}],"keywords":[{"term":"제산법(Division)","desc":"키를 소수로 나눈 나머지를 주소로 사용"},{"term":"제곱법(Mid-Square)","desc":"키를 제곱한 값의 중간 부분을 주소로 사용"},{"term":"폴딩법(Folding)","desc":"키를 여러 부분으로 나눠 더하거나 XOR한 값을 주소로 사용"},{"term":"기수 변환법(Radix)","desc":"키를 다른 진법으로 바꿔 넘치는 자리를 잘라 사용"},{"term":"숫자 분석법(Digit Analysis)","desc":"자리별 분포를 보고 고른 자리들을 주소로 사용"}],"memo":"'나눠서 더하거나 XOR'은 종이 접기(Folding)를 떠올린다."}},{"id":"written-2020-4-39","no":39,"unit":"소프트웨어 개발","q":"다음에서 설명하는 클린 코드 작성 원칙은?\n<img src=\"data/img/eip_written_20200926_039.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["다형성","단순성","추상화","의존성"],"ans":2,"rate":85,"wiki":[{"title":"객체지향 설계 원칙","url":"https://itwiki.kr/w/객체지향 설계 원칙"}],"exp":{"concept":"클린 코드(Clean Code)는 누구나 쉽게 읽고 고칠 수 있게 작성한 코드다. 작성 원칙으로 가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화가 있다. 지문의 '한 번에 한 가지 처리만 수행', '클래스/메소드/함수를 최소 단위로 분리'는 단순성 원칙이다.","choices":[{"verdict":"오답","why":"다형성은 하나의 메시지에 객체마다 다르게 반응하는 객체지향의 특징으로, 클린 코드 작성 원칙에 속하지 않는다."},{"verdict":"정답","why":"단순성은 한 번에 한 가지 처리만 하도록 코드를 간단하게 작성하고, 클래스·메소드·함수를 최소 단위로 분리하는 원칙이다."},{"verdict":"오답","why":"추상화는 상위 클래스·메소드·함수에서는 애플리케이션의 특성을 간략하게 나타내고 세부 내용은 하위에서 구현하는 원칙이다."},{"verdict":"오답","why":"의존성 배제는 코드가 다른 모듈에 미치는 영향을 최소화하고, 코드를 고칠 때 다른 부분에 영향이 없도록 하는 원칙이다."}],"keywords":[{"term":"가독성","desc":"누구든 읽기 쉽게, 이해하기 쉬운 이름과 들여쓰기 사용"},{"term":"단순성","desc":"한 번에 한 가지 처리, 최소 단위로 분리"},{"term":"의존성 배제","desc":"다른 모듈에 미치는 영향 최소화"},{"term":"중복성 최소화","desc":"중복된 코드를 제거하고 공통 코드를 사용"},{"term":"추상화","desc":"상위에서는 간략히, 세부 구현은 하위에서"}],"memo":"클린 코드 원칙은 '가·단·의·중·추'. '한 가지만'은 단순성이다."}},{"id":"written-2020-4-40","no":40,"unit":"소프트웨어 개발","q":"디지털 저작권 관리(DRM) 기술과 거리가 먼 것은?","choices":["콘텐츠 암호화 및 키 관리","콘텐츠 식별체계 표현","콘텐츠 오류 감지 및 복구","라이선스 발급 및 관리"],"ans":3,"rate":78,"wiki":[{"title":"DRM","url":"https://itwiki.kr/w/DRM"}],"exp":{"concept":"디지털 저작권 관리(DRM) 기술은 콘텐츠가 허락된 사람에게만 허락된 방식으로 쓰이도록 보호하는 기술이다. 콘텐츠 암호화와 키 관리, 콘텐츠 식별 체계, 저작권 표현(라이선스), 라이선스 발급·관리, 정책 관리, 크랙 방지, 인증 기술 등이 있다. 오류를 감지하고 복구하는 것은 저작권 보호와 관계없는 통신·저장 기술이다.","choices":[{"verdict":"오답","why":"콘텐츠를 암호화하고 키를 관리하는 것은 DRM의 핵심 기술이다."},{"verdict":"오답","why":"콘텐츠에 고유 식별 번호를 부여하는 식별 체계 표현은 DRM 기술이다."},{"verdict":"정답","why":"콘텐츠 오류 감지 및 복구는 저작권 보호와 관련 없는 기술로, DRM 기술과 거리가 멀다."},{"verdict":"오답","why":"라이선스를 발급하고 관리하는 것은 DRM 기술이다."}],"keywords":[{"term":"암호화(Encryption)","desc":"콘텐츠와 라이선스를 암호화하고 전자 서명으로 보호"},{"term":"키 관리(Key Management)","desc":"콘텐츠를 암호화한 키의 저장·분배 관리"},{"term":"식별 기술(Identification)","desc":"콘텐츠에 고유 식별 체계를 부여"},{"term":"저작권 표현(Right Expression)","desc":"라이선스 내용을 표현하는 기술"},{"term":"크랙 방지(Tamper Resistance)","desc":"크랙에 의한 콘텐츠 사용 방지"}],"memo":"DRM은 '저작권 보호'가 목적이다. 오류 복구처럼 보호와 무관한 기능을 고르면 된다."}},{"id":"written-2020-4-41","no":41,"unit":"데이터베이스 구축","q":"다음 설명과 관련 있는 트랜잭션의 특징은?\n<img src=\"data/img/eip_written_20200926_041.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Durability","Isolation","Consistency","Atomicity"],"ans":4,"rate":67,"wiki":[{"title":"트랜잭션 특성","url":"https://itwiki.kr/w/트랜잭션 특성"}],"exp":{"concept":"트랜잭션은 데이터베이스에서 하나의 논리적 작업 단위이며, ACID라는 네 가지 성질을 가진다. 원자성(Atomicity)은 트랜잭션의 연산이 모두 실행되거나 하나도 실행되지 않아야 한다는 성질로, 계좌 이체에서 출금만 되고 입금이 안 되는 일이 없게 한다.","choices":[{"verdict":"오답","why":"지속성(Durability)은 성공적으로 완료된 트랜잭션의 결과가 시스템이 고장 나도 영구히 반영되어야 한다는 성질이다."},{"verdict":"오답","why":"독립성(Isolation)은 둘 이상의 트랜잭션이 동시에 실행될 때 한 트랜잭션이 끝나기 전에는 다른 트랜잭션이 그 결과를 참조할 수 없다는 성질이다."},{"verdict":"오답","why":"일관성(Consistency)은 트랜잭션이 성공적으로 끝나면 언제나 일관성 있는 데이터베이스 상태로 변환된다는 성질이다."},{"verdict":"정답","why":"원자성(Atomicity)은 트랜잭션의 연산이 모두 반영되거나(Commit) 전혀 반영되지 않아야(Rollback) 한다는 성질로, 지문과 맞는다."}],"keywords":[{"term":"원자성(Atomicity)","desc":"All or Nothing, 모두 실행되거나 전혀 실행되지 않음"},{"term":"일관성(Consistency)","desc":"실행 후에도 데이터베이스가 일관된 상태 유지"},{"term":"독립성(Isolation)","desc":"동시 실행 트랜잭션끼리 서로 간섭하지 않음"},{"term":"지속성(Durability)","desc":"완료된 결과는 영구히 반영"}],"memo":"'모두 실행되거나 모두 실행되지 않아야'는 원자성(All or Nothing)의 공식 문장이다."}},{"id":"written-2020-4-42","no":42,"unit":"데이터베이스 구축","q":"데이터베이스에 영향을 주는 생성, 읽기, 갱신, 삭제 연산으로 프로세스와 테이블 간에 매트릭스를 만들어서 트랜잭션을 분석하는 것은?","choices":["CASE 분석","일치 분석","CRUD 분석","연관성 분석"],"ans":3,"rate":70,"exp":{"concept":"CRUD 분석은 데이터베이스에 영향을 주는 생성(Create), 읽기(Read), 갱신(Update), 삭제(Delete) 연산을 기준으로, 프로세스와 테이블 사이에 매트릭스(표)를 만들어 트랜잭션을 분석하는 방법이다. 이 표를 CRUD 매트릭스라고 하며, 많이 쓰이는 테이블을 찾아 성능 설계에 활용한다.","choices":[{"verdict":"오답","why":"CASE 분석은 출제 범위에서 프로세스-테이블 매트릭스 분석을 가리키는 용어가 아니다. CASE는 개발 자동화 도구를 뜻한다."},{"verdict":"오답","why":"일치 분석은 출제 범위의 표준 용어가 아니다."},{"verdict":"정답","why":"CRUD 분석은 생성·읽기·갱신·삭제 연산으로 프로세스와 테이블 간 매트릭스를 만들어 트랜잭션을 분석한다."},{"verdict":"오답","why":"연관성 분석은 데이터 사이의 연관 규칙을 찾는 데이터 마이닝 기법을 가리키는 말로, 지문의 매트릭스 분석이 아니다."}],"keywords":[{"term":"CRUD","desc":"Create(생성), Read(읽기), Update(갱신), Delete(삭제)"},{"term":"CRUD 매트릭스","desc":"프로세스와 테이블 사이에 CRUD 연산을 표시한 표"},{"term":"트랜잭션 분석","desc":"CRUD 매트릭스를 바탕으로 테이블별 트랜잭션 양을 분석"}],"memo":"생성·읽기·갱신·삭제의 첫 글자를 영어로 모으면 바로 CRUD다."}},{"id":"written-2020-4-43","no":43,"unit":"데이터베이스 구축","q":"정규화된 엔티티, 속성, 관계를 시스템의 성능 향상과 개발 운영의 단순화를 위해 중복, 통합, 분리 등을 수행하는 데이터 모델링 기법은?","choices":["인덱스정규화","반정규화","집단화","머징"],"ans":2,"rate":65,"wiki":[{"title":"반정규화","url":"https://itwiki.kr/w/반정규화"}],"exp":{"concept":"반정규화(Denormalization)는 정규화로 잘게 나눈 테이블을, 시스템 성능 향상과 개발·운영 단순화를 위해 일부러 중복시키거나 통합하거나 분리하는 기법이다. 조인이 너무 많아 느려질 때 테이블을 다시 합치는 것이 대표적이다. 대신 데이터 일관성이 깨질 위험이 생긴다.","choices":[{"verdict":"오답","why":"인덱스 정규화는 출제 범위의 표준 용어가 아니다."},{"verdict":"정답","why":"반정규화는 정규화된 엔티티·속성·관계를 성능 향상과 개발 운영의 단순화를 위해 중복, 통합, 분리하는 기법이다."},{"verdict":"오답","why":"집단화(Aggregation)는 관련 있는 여러 개체를 묶어 하나의 상위 개체로 만드는 추상화 개념이다."},{"verdict":"오답","why":"머징은 출제 범위에서 이 기법을 가리키는 표준 용어가 아니다."}],"keywords":[{"term":"정규화(Normalization)","desc":"이상 현상을 없애기 위해 테이블을 분해하는 과정"},{"term":"반정규화(Denormalization)","desc":"성능을 위해 정규화된 구조를 중복·통합·분리하는 기법"},{"term":"반정규화 방법","desc":"테이블 통합·분할, 중복 테이블 추가, 중복 속성 추가"}],"memo":"정규화의 '반대(反)' 방향으로 일부러 중복을 허용하는 것이 반정규화다. 목적은 '성능'."}},{"id":"written-2020-4-44","no":44,"unit":"데이터베이스 구축","q":"학생 테이블을 생성한 후, 성별 필드가 누락되어 이를 추가하려고 한다. 이에 적합한 SQL 명령어는?","choices":["INSERT","ALTER","DROP","MODIFY"],"ans":2,"rate":71,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"이미 만든 테이블의 구조(열 추가, 변경, 삭제)를 바꿀 때는 데이터 정의어(DDL)인 ALTER를 쓴다. 학생 테이블에 성별 열을 추가하려면 ALTER TABLE 학생 ADD 성별 CHAR(1); 처럼 쓴다.","choices":[{"verdict":"오답","why":"INSERT는 테이블에 새 행(튜플)을 삽입하는 데이터 조작어(DML)다. 열을 추가하는 명령이 아니다."},{"verdict":"정답","why":"ALTER는 테이블 정의를 변경하는 DDL로, ADD로 열을 추가할 수 있다."},{"verdict":"오답","why":"DROP은 테이블 같은 객체 자체를 삭제하는 DDL이다."},{"verdict":"오답","why":"MODIFY는 독립된 SQL 명령어가 아니다. 일부 DBMS에서 ALTER TABLE 안에서 열 정의를 바꿀 때 쓰는 절일 뿐이다."}],"keywords":[{"term":"CREATE","desc":"테이블 등 객체를 정의(생성)하는 DDL"},{"term":"ALTER","desc":"테이블 정의를 변경하는 DDL, ADD·DROP 등으로 열 추가·삭제"},{"term":"DROP","desc":"객체를 삭제하는 DDL"},{"term":"INSERT","desc":"새 행을 삽입하는 DML"}],"memo":"구조(열)를 바꾸면 ALTER, 내용(행)을 넣으면 INSERT."}},{"id":"written-2020-4-45","no":45,"unit":"데이터베이스 구축","q":"정규화의 필요성으로 거리가 먼 것은?","choices":["데이터 구조의 안정성 최대화","중복 데이터의 활성화","수정, 삭제 시 이상현상의 최소화","테이블 불일치 위험의 최소화"],"ans":2,"rate":88,"exp":{"concept":"정규화는 테이블을 잘게 나누어 중복을 없애고 삽입·삭제·갱신 이상 현상을 막는 과정이다. 목적은 데이터 구조를 안정적으로 만들고, 중복 데이터를 최소화하며, 테이블 간 불일치 위험을 줄이는 것이다.","choices":[{"verdict":"오답","why":"정규화는 데이터 구조의 안정성을 최대화하기 위해 필요하다. 맞는 필요성이다."},{"verdict":"정답","why":"정규화는 중복 데이터를 최소화하려는 것이다. 중복 데이터의 활성화는 정규화의 목적과 정반대다."},{"verdict":"오답","why":"정규화는 수정, 삭제 시 발생하는 이상 현상을 최소화한다. 맞는 필요성이다."},{"verdict":"오답","why":"정규화는 테이블 사이의 불일치 위험을 최소화한다. 맞는 필요성이다."}],"keywords":[{"term":"정규화(Normalization)","desc":"중복을 줄이고 이상 현상을 없애기 위해 릴레이션을 분해하는 과정"},{"term":"이상 현상(Anomaly)","desc":"삽입 이상, 삭제 이상, 갱신 이상"},{"term":"함수적 종속","desc":"어떤 속성 값이 다른 속성 값을 유일하게 결정하는 관계"}],"memo":"정규화의 적은 '중복'이다. 중복을 늘리거나 살린다는 보기는 틀렸다."}},{"id":"written-2020-4-46","no":46,"unit":"데이터베이스 구축","q":"개체-관계 모델의 E-R 다이어그램에서 사용되는 기호와 그 의미의 연결이 틀린 것은?","choices":["사각형 - 개체 타입","삼각형 - 속성","선 - 개체타입과 속성을 연결","마름모 - 관계 타입"],"ans":2,"rate":84,"wiki":[{"title":"ER 다이어그램","url":"https://itwiki.kr/w/ER 다이어그램"}],"exp":{"concept":"E-R 다이어그램은 개체, 속성, 관계를 정해진 도형으로 그린다. 사각형은 개체 타입, 마름모는 관계 타입, 타원은 속성, 선은 개체 타입과 속성을 연결하는 데 쓴다. 이중 타원은 다중값 속성, 밑줄 그은 타원은 기본키 속성이다.","choices":[{"verdict":"오답","why":"사각형은 개체 타입을 나타낸다. 맞는 연결이다."},{"verdict":"정답","why":"속성은 타원으로 나타낸다. 삼각형은 E-R 다이어그램의 기본 기호가 아니다."},{"verdict":"오답","why":"선은 개체 타입과 속성, 개체 타입과 관계 타입을 연결한다. 맞는 연결이다."},{"verdict":"오답","why":"마름모는 관계 타입을 나타낸다. 맞는 연결이다."}],"keywords":[{"term":"사각형","desc":"개체 타입(Entity)"},{"term":"마름모","desc":"관계 타입(Relationship)"},{"term":"타원","desc":"속성(Attribute)"},{"term":"이중 타원","desc":"다중값 속성"},{"term":"밑줄 타원","desc":"기본키 속성"}],"memo":"개체는 네모, 관계는 마름모, 속성은 동그라미(타원). 삼각형은 E-R에 없다."}},{"id":"written-2020-4-47","no":47,"unit":"데이터베이스 구축","q":"다음 SQL문에서 빈칸에 들어갈 내용으로 옳은 것은?\n<img src=\"data/img/eip_written_20200926_047.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["FROM","SET","INTO","TO"],"ans":2,"rate":70,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"UPDATE 문은 테이블에 이미 있는 행의 값을 바꾸는 데이터 조작어(DML)다. 형식은 UPDATE 테이블명 SET 열이름 = 값 WHERE 조건; 이다. 지문은 회원 테이블에서 회원번호가 'N4'인 행의 전화번호를 '010-14'로 바꾸는 문장이므로 빈칸에는 SET이 들어간다.","choices":[{"verdict":"오답","why":"FROM은 SELECT·DELETE 문에서 대상 테이블을 지정할 때 쓴다."},{"verdict":"정답","why":"UPDATE 문은 SET 뒤에 바꿀 열과 새 값을 적는다. UPDATE 회원 SET 전화번호='010-14' WHERE 회원번호='N4'; 가 완성된 문장이다."},{"verdict":"오답","why":"INTO는 INSERT INTO 테이블명처럼 INSERT 문에서 쓴다."},{"verdict":"오답","why":"TO는 GRANT 권한 ON 객체 TO 사용자처럼 권한 부여에서 쓴다."}],"keywords":[{"term":"UPDATE","desc":"UPDATE 테이블 SET 열=값 WHERE 조건"},{"term":"INSERT","desc":"INSERT INTO 테이블(열) VALUES(값)"},{"term":"DELETE","desc":"DELETE FROM 테이블 WHERE 조건"}],"memo":"DML 짝꿍: INSERT-INTO, DELETE-FROM, UPDATE-SET."}},{"id":"written-2020-4-48","no":48,"unit":"데이터베이스 구축","q":"릴레이션에 있는 모든 튜플에 대해 유일성은 만족시키지만 최소성은 만족시키지 못하는 키는?","choices":["후보키","기본키","슈퍼키","외래키"],"ans":3,"rate":66,"exp":{"concept":"키는 튜플(행)을 구별하는 속성이다. 유일성은 키 값으로 모든 튜플을 하나씩 구별할 수 있다는 뜻이고, 최소성은 꼭 필요한 속성만으로 이루어져 하나라도 빼면 유일성이 깨진다는 뜻이다. 슈퍼키는 유일성만 만족하고, 후보키는 유일성과 최소성을 모두 만족한다.","choices":[{"verdict":"오답","why":"후보키는 유일성과 최소성을 모두 만족하는 키다."},{"verdict":"오답","why":"기본키는 후보키 중에서 선택한 대표 키로, 유일성과 최소성을 모두 만족하고 NULL을 가질 수 없다."},{"verdict":"정답","why":"슈퍼키는 속성들의 집합으로 유일성은 만족하지만 불필요한 속성이 섞여 있을 수 있어 최소성은 만족하지 못한다."},{"verdict":"오답","why":"외래키는 다른 릴레이션의 기본키를 참조하는 속성으로, 릴레이션 사이의 관계를 표현한다."}],"keywords":[{"term":"슈퍼키(Super Key)","desc":"유일성만 만족"},{"term":"후보키(Candidate Key)","desc":"유일성과 최소성 모두 만족"},{"term":"기본키(Primary Key)","desc":"후보키 중 선택한 주 키, NULL 불가"},{"term":"대체키(Alternate Key)","desc":"후보키 중 기본키로 선택되지 않은 키"},{"term":"외래키(Foreign Key)","desc":"다른 릴레이션의 기본키를 참조"}],"memo":"학번은 후보키, 학번+이름은 슈퍼키(이름을 빼도 구별되니 최소성 위반)로 예를 들어 기억한다."}},{"id":"written-2020-4-49","no":49,"unit":"데이터베이스 구축","q":"DBA가 사용자 PARK에게 테이블 [STUDENT]의 데이터를 갱신할 수 있는 시스템 권한을 부여하고자 하는 SQL문을 작성하고자 한다. 다음에 주어진 SQL문의 빈칸을 알맞게 채운 것은?\n<img src=\"data/img/eip_written_20200926_049.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["㉠ INSERT, ㉡ INTO","㉠ ALTER, ㉡ TO","㉠ UPDATE, ㉡ ON","㉠ REPLACE, ㉡ IN"],"ans":3,"rate":68,"exp":{"concept":"GRANT는 사용자에게 권한을 주는 데이터 제어어(DCL)다. 형식은 GRANT 권한 ON 객체 TO 사용자; 이다. 테이블 STUDENT의 데이터를 갱신하는 권한은 UPDATE이므로 GRANT UPDATE ON STUDENT TO PARK; 가 된다.","choices":[{"verdict":"오답","why":"INSERT는 행을 삽입하는 권한이고, INTO는 GRANT 문의 객체 지정 키워드가 아니다."},{"verdict":"오답","why":"ALTER는 테이블 구조를 변경하는 권한이다. 또 객체 앞에는 TO가 아니라 ON을 쓴다."},{"verdict":"정답","why":"데이터 갱신 권한은 UPDATE이고, 권한을 줄 객체 앞에는 ON을 쓴다. GRANT UPDATE ON STUDENT TO PARK; 로 완성된다."},{"verdict":"오답","why":"REPLACE는 표준 SQL 권한이 아니고, IN도 GRANT 문의 키워드가 아니다."}],"keywords":[{"term":"GRANT","desc":"GRANT 권한 ON 객체 TO 사용자, 권한 부여"},{"term":"REVOKE","desc":"REVOKE 권한 ON 객체 FROM 사용자, 권한 회수"},{"term":"WITH GRANT OPTION","desc":"받은 권한을 다른 사용자에게 다시 줄 수 있게 함"}],"memo":"GRANT는 ON ~ TO ~, REVOKE는 ON ~ FROM ~. 주는 건 TO, 뺏는 건 FROM."}},{"id":"written-2020-4-50","no":50,"unit":"데이터베이스 구축","q":"관계대수에 대한 설명으로 틀린 것은?","choices":["주어진 릴레이션 조작을 위한 연산의 집합이다.","일반 집합 연산과 순수 관계 연산으로 구분된다.","질의에 대한 해를 구하기 위해 수행해야 할 연산의 순서를 명시한다.","원하는 정보와 그 정보를 어떻게 유도하는가를 기술하는 비절차적방법이다."],"ans":4,"rate":78,"wiki":[{"title":"관계대수","url":"https://itwiki.kr/w/관계대수"}],"exp":{"concept":"관계대수는 원하는 결과를 얻기 위해 릴레이션에 어떤 연산을 어떤 순서로 적용할지 기술하는 절차적 언어다. 합집합·교집합·차집합·카티션 프로덕트 같은 일반 집합 연산과 Select·Project·Join·Division 같은 순수 관계 연산으로 나뉜다. 반면 관계해석은 무엇을 원하는지만 기술하는 비절차적 언어다.","choices":[{"verdict":"오답","why":"관계대수는 릴레이션을 조작하기 위한 연산의 집합이다. 맞는 설명이다."},{"verdict":"오답","why":"관계대수는 일반 집합 연산과 순수 관계 연산으로 구분된다. 맞는 설명이다."},{"verdict":"오답","why":"관계대수는 질의의 해를 구하기 위해 수행할 연산의 순서를 명시한다. 맞는 설명이다."},{"verdict":"정답","why":"원하는 정보가 무엇인지만 기술하는 비절차적 방법은 관계해석이다. 관계대수는 어떻게 유도하는지 순서를 기술하는 절차적 방법이므로 틀린 설명이다."}],"keywords":[{"term":"관계대수(Relational Algebra)","desc":"결과를 얻는 연산 순서를 명시하는 절차적 언어"},{"term":"관계해석(Relational Calculus)","desc":"원하는 정보만 정의하는 비절차적 언어, 프레디킷 해석 기반"},{"term":"순수 관계 연산자","desc":"Select(σ), Project(π), Join(⋈), Division(÷)"},{"term":"일반 집합 연산자","desc":"합집합(∪), 교집합(∩), 차집합(-), 카티션 프로덕트(×)"}],"memo":"대수는 '절차적(How)', 해석은 '비절차적(What)'. 수학 계산 순서를 적는 게 대수라고 기억한다."}},{"id":"written-2020-4-51","no":51,"unit":"데이터베이스 구축","q":"다음 SQL문의 실행 결과는?\n<div class=\"q-spec\">\n<span class=\"q-spec__label\">보기</span>\n<img src=\"data/img/eip_written_20200926_051.png\" alt=\"문제 이미지\" class=\"q-img\" />\n</div>","choices":["<table class=\"q-tbl is-data\"><thead><tr><th>과목이름</th></tr></thead><tbody><tr><td>DB</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>과목이름</th></tr></thead><tbody><tr><td>DB</td></tr><tr><td>DB</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>과목이름</th></tr></thead><tbody><tr><td>DB</td></tr><tr><td>DB</td></tr><tr><td>운영체제</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>과목이름</th></tr></thead><tbody><tr><td>DB</td></tr><tr><td>운영체제</td></tr></tbody></table>"],"ans":3,"rate":65,"exp":{"concept":"EXISTS는 하위 질의 결과가 한 행이라도 있으면 참이 되는 조건이다. 이 문장은 성적 테이블의 각 행마다, 같은 학번을 가진 학생 중 학과가 전산 또는 전기이고 주소가 경기인 학생이 있는지 확인한다. 조건을 만족하는 학생은 2000(전기, 경기)과 4000(전산, 경기)뿐이다. 성적에서 학번 2000의 DB, 학번 4000의 DB와 운영체제, 총 3행이 출력되고, DISTINCT가 없으므로 DB는 두 번 나온다.","choices":[{"verdict":"오답","why":"DB 한 행만 나오는 것은 결과가 아니다. DISTINCT가 없으므로 2000과 4000의 DB가 각각 출력되고, 4000의 운영체제도 출력된다."},{"verdict":"오답","why":"학번 4000은 운영체제 과목 성적도 있으므로 운영체제 행이 빠질 수 없다."},{"verdict":"정답","why":"학번 2000의 DB, 학번 4000의 DB, 학번 4000의 운영체제가 출력되어 DB, DB, 운영체제 3행이 된다."},{"verdict":"오답","why":"DISTINCT가 없으므로 중복된 DB가 한 번으로 줄어들지 않는다. DB는 두 번 출력된다."}],"keywords":[{"term":"EXISTS","desc":"하위 질의 결과가 존재하면 참"},{"term":"상관 하위 질의","desc":"바깥 질의의 행 값(성적.학번)을 안쪽 질의에서 참조하는 하위 질의"},{"term":"IN","desc":"괄호 안 값 중 하나와 일치하면 참"},{"term":"DISTINCT","desc":"결과에서 중복 행을 제거"}],"memo":"조건에 맞는 학생부터 고르고, 그 학번의 성적 행을 모두 세라. DISTINCT가 없으면 중복도 그대로 나온다."}},{"id":"written-2020-4-52","no":52,"unit":"데이터베이스 구축","q":"로킹(Locking) 기법에 대한 설명으로 틀린 것은?","choices":["로킹의 대상이 되는 객체의 크기를 로킹 단위라고 한다.","로킹 단위가 작아지면 병행성 수준이 낮아진다.","데이터베이스도 로킹 단위가 될 수 있다.","로킹 단위가 커지면 로크 수가 작아 로킹 오버헤드가 감소한다."],"ans":2,"rate":71,"wiki":[{"title":"데이터베이스 로킹","url":"https://itwiki.kr/w/데이터베이스 로킹"}],"exp":{"concept":"로킹(Locking)은 여러 트랜잭션이 같은 데이터를 동시에 바꾸지 못하게 잠그는 병행 제어 기법이다. 잠그는 대상의 크기를 로킹 단위라 하며, 데이터베이스, 파일, 레코드, 필드 모두 로킹 단위가 될 수 있다. 로킹 단위가 작으면 잠그는 범위가 좁아 여러 트랜잭션이 동시에 일할 수 있지만(병행성 높음), 관리할 로크가 많아 오버헤드가 커진다.","choices":[{"verdict":"오답","why":"로킹 대상이 되는 객체의 크기를 로킹 단위라고 한다. 맞는 설명이다."},{"verdict":"정답","why":"로킹 단위가 작아지면 잠기는 범위가 좁아져 동시에 처리할 수 있는 트랜잭션이 많아지므로 병행성 수준은 높아진다. 낮아진다는 설명은 틀렸다."},{"verdict":"오답","why":"데이터베이스 전체도 로킹 단위가 될 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"로킹 단위가 커지면 로크 수가 적어져 로킹 오버헤드가 감소한다. 맞는 설명이다."}],"keywords":[{"term":"로킹(Locking)","desc":"데이터에 잠금을 걸어 동시 접근을 제어하는 병행 제어 기법"},{"term":"로킹 단위 작음","desc":"로크 수 많음, 오버헤드 증가, 병행성 높음"},{"term":"로킹 단위 큼","desc":"로크 수 적음, 오버헤드 감소, 병행성 낮음"}],"memo":"로킹 단위와 병행성은 반대로 움직이고, 로킹 단위와 오버헤드도 반대로 움직인다. 작게 잠글수록 동시에 많이 일한다."}},{"id":"written-2020-4-53","no":53,"unit":"데이터베이스 구축","q":"사용자 X1에게 department 테이블에 대한 검색 연산을 회수하는 명령은?","choices":["delete select on department to X1;","remove select on department from X1;","revoke select on department from X1;","grant select on department from X1;"],"ans":3,"rate":86,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"},{"title":"DCL","url":"https://itwiki.kr/w/DCL"}],"exp":{"concept":"데이터 제어어(DCL)에서 권한을 주는 명령은 GRANT, 권한을 회수하는 명령은 REVOKE다. 회수할 때는 REVOKE 권한 ON 객체 FROM 사용자; 형식을 쓴다. 따라서 X1에게서 department 테이블의 검색(SELECT) 권한을 빼앗으려면 revoke select on department from X1; 이다.","choices":[{"verdict":"오답","why":"DELETE는 테이블의 행을 삭제하는 데이터 조작어로, 권한 회수 명령이 아니다."},{"verdict":"오답","why":"REMOVE는 SQL의 권한 회수 명령어가 아니다."},{"verdict":"정답","why":"REVOKE 권한 ON 객체 FROM 사용자 형식에 맞게 SELECT 권한을 회수하는 명령이다."},{"verdict":"오답","why":"GRANT는 권한을 부여하는 명령이며, 사용자 앞에는 FROM이 아니라 TO를 쓴다."}],"keywords":[{"term":"GRANT","desc":"GRANT 권한 ON 객체 TO 사용자, 권한 부여"},{"term":"REVOKE","desc":"REVOKE 권한 ON 객체 FROM 사용자, 권한 회수"},{"term":"CASCADE","desc":"REVOKE 시 그 사용자가 다른 사용자에게 준 권한까지 연쇄 회수"}],"memo":"GRANT ~ TO, REVOKE ~ FROM. 주는 건 '누구에게(TO)', 뺏는 건 '누구로부터(FROM)'."}},{"id":"written-2020-4-54","no":54,"unit":"데이터베이스 구축","q":"뷰(VIEW)에 대한 설명으로 틀린 것은?","choices":["뷰 위에 또 다른 뷰를 정의할 수 있다.","뷰에 대한 조작에서 삽입, 갱신, 삭제 연산은 제약이 따른다.","뷰의 정의는 기본 테이블과 같이 ALTER문을 이용하여 변경한다.","뷰가 정의된 기본 테이블이 제거되면 뷰도 자동적으로 제거된다."],"ans":3,"rate":62,"wiki":[{"title":"데이터베이스 뷰","url":"https://itwiki.kr/w/데이터베이스 뷰"}],"exp":{"concept":"뷰(View)는 기본 테이블에서 필요한 부분만 뽑아 만든 가상 테이블이다. 실제 데이터를 따로 저장하지 않고 정의만 가지고 있다. 뷰의 정의는 ALTER로 고칠 수 없어서, 바꾸려면 DROP으로 지우고 CREATE로 다시 만들어야 한다.","choices":[{"verdict":"오답","why":"뷰를 바탕으로 또 다른 뷰를 정의할 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"뷰는 가상 테이블이라 삽입, 갱신, 삭제 연산에 제약이 있다. 맞는 설명이다."},{"verdict":"정답","why":"뷰는 ALTER 문으로 정의를 변경할 수 없다. 변경하려면 삭제(DROP) 후 다시 생성(CREATE)해야 하므로 틀린 설명이다."},{"verdict":"오답","why":"뷰가 정의된 기본 테이블이 제거되면 그 테이블을 바탕으로 한 뷰도 함께 제거된다. 맞는 설명이다."}],"keywords":[{"term":"뷰(View)","desc":"하나 이상의 기본 테이블에서 유도된 가상 테이블"},{"term":"뷰의 장점","desc":"논리적 데이터 독립성 제공, 데이터 보안, 사용자 관점 단순화"},{"term":"뷰의 단점","desc":"독립적인 인덱스를 가질 수 없고, ALTER로 정의 변경 불가, 삽입·삭제·갱신 제약"}],"memo":"뷰는 고치려면 '지우고 다시 만든다'. ALTER와 뷰가 같이 나오면 틀린 보기다."}},{"id":"written-2020-4-55","no":55,"unit":"데이터베이스 구축","q":"데이터 모델에 표시해야 할 요소로 거리가 먼 것은?","choices":["논리적 데이터 구조","출력 구조","연산","제약조건"],"ans":2,"rate":51,"wiki":[{"title":"데이터_모델","url":"https://itwiki.kr/w/데이터_모델"}],"exp":{"concept":"데이터 모델은 현실 세계의 데이터를 컴퓨터에 표현하기 위해 단순화한 틀이다. 데이터 모델에 표시해야 할 요소는 데이터의 논리적 구조(Structure), 그 구조에 적용할 연산(Operation), 데이터가 지켜야 할 제약 조건(Constraint) 세 가지다.","choices":[{"verdict":"오답","why":"논리적 데이터 구조는 개체와 관계를 나타내는 데이터 모델의 요소다."},{"verdict":"정답","why":"출력 구조는 데이터 모델에 표시해야 할 요소가 아니다. 데이터 모델의 요소는 구조, 연산, 제약 조건이다."},{"verdict":"오답","why":"연산은 데이터 구조에 적용해 실제 데이터를 처리하는 작업으로, 데이터 모델의 요소다."},{"verdict":"오답","why":"제약 조건은 데이터베이스에 저장될 수 있는 실제 데이터의 논리적인 제약으로, 데이터 모델의 요소다."}],"keywords":[{"term":"구조(Structure)","desc":"논리적으로 표현된 개체 타입 사이의 관계"},{"term":"연산(Operation)","desc":"데이터 인스턴스에 적용 가능한 처리 도구"},{"term":"제약 조건(Constraint)","desc":"저장될 수 있는 데이터의 논리적 제약"},{"term":"데이터 모델 구성 요소","desc":"개체(Entity), 속성(Attribute), 관계(Relationship)"}],"memo":"데이터 모델에 표시할 요소는 '구조·연산·제약 조건' 세 가지. '출력'은 없다."}},{"id":"written-2020-4-56","no":56,"unit":"데이터베이스 구축","q":"제 3정규형에서 보이스코드 정규형(BCNF)으로 정규화하기 위한 작업은?","choices":["원자 값이 아닌 도메인을 분해","부분 함수 종속 제거","이행 함수 종속 제거","결정자가 후보키가 아닌 함수 종속 제거"],"ans":4,"rate":73,"wiki":[{"title":"함수 종속","url":"https://itwiki.kr/w/함수 종속"},{"title":"후보 키","url":"https://itwiki.kr/w/후보 키"}],"exp":{"concept":"정규화는 단계마다 없애는 종속이 정해져 있다. 1NF는 도메인을 원자값으로, 2NF는 부분 함수 종속 제거, 3NF는 이행 함수 종속 제거, BCNF는 결정자이면서 후보키가 아닌 것을 제거, 4NF는 다치 종속 제거, 5NF는 조인 종속 제거다. 3NF에서 BCNF로 가려면 모든 결정자가 후보키가 되도록 결정자가 후보키가 아닌 함수 종속을 없애야 한다.","choices":[{"verdict":"오답","why":"원자값이 아닌 도메인을 분해하는 것은 비정규 릴레이션을 1NF로 만드는 작업이다."},{"verdict":"오답","why":"부분 함수 종속을 제거하는 것은 1NF를 2NF로 만드는 작업이다."},{"verdict":"오답","why":"이행 함수 종속을 제거하는 것은 2NF를 3NF로 만드는 작업이다."},{"verdict":"정답","why":"결정자가 후보키가 아닌 함수 종속을 제거하는 것이 3NF를 BCNF로 만드는 작업이다."}],"keywords":[{"term":"1NF","desc":"모든 도메인이 원자값"},{"term":"2NF","desc":"부분 함수 종속 제거, 완전 함수 종속 만족"},{"term":"3NF","desc":"이행 함수 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보키가 아닌 것 제거"},{"term":"4NF와 5NF","desc":"4NF는 다치 종속 제거, 5NF는 조인 종속 제거"}],"memo":"정규화 순서는 '도·부·이·결·다·조'(도메인 원자값 → 부분 → 이행 → 결정자 → 다치 → 조인)."}},{"id":"written-2020-4-57","no":57,"unit":"데이터베이스 구축","q":"A1, A2, A3 3개 속성을 갖는 한 릴레이션에서 A1의 도메인은 3개 값, A2의 도메인은 2개 값, A3의 도메인은 4개 값을 갖는다. 이 릴레이션에 존재할 수 있는 가능한 튜플(Tuple)의 최대 수는?","choices":["24","12","8","9"],"ans":1,"rate":78,"exp":{"concept":"릴레이션에 들어갈 수 있는 튜플은 각 속성이 자기 도메인에서 값을 하나씩 골라 만든 조합이다. 서로 다른 조합의 최대 개수는 각 도메인 크기의 곱(카티션 곱)과 같다. A1 3개, A2 2개, A3 4개이므로 3 × 2 × 4 = 24개다.","choices":[{"verdict":"정답","why":"3 × 2 × 4 = 24로, 세 도메인 값으로 만들 수 있는 모든 조합의 수가 최대 튜플 수다."},{"verdict":"오답","why":"12는 3 × 4처럼 일부 속성만 곱한 값이다. A2의 2개 값까지 세 도메인을 모두 곱해야 한다."},{"verdict":"오답","why":"8은 2 × 4처럼 일부 속성만 곱한 값이다. A1의 3개 값도 곱해야 한다."},{"verdict":"오답","why":"9는 3 + 2 + 4로 더한 값이다. 조합의 수는 더하기가 아니라 곱하기로 구한다."}],"keywords":[{"term":"튜플(Tuple)","desc":"릴레이션의 행, 카디널리티는 튜플의 수"},{"term":"도메인(Domain)","desc":"한 속성이 가질 수 있는 원자값들의 집합"},{"term":"카티션 곱(Cartesian Product)","desc":"두 집합의 모든 원소 쌍을 만드는 연산, 개수는 곱"}],"memo":"가능한 튜플 수는 '도메인 크기를 모두 곱한다'. 더하면 오답 9가 나온다."}},{"id":"written-2020-4-58","no":58,"unit":"데이터베이스 구축","q":"데이터베이스 설계 시 물리적 설계 단계에서 수행하는 사항이 아닌 것은?","choices":["저장 레코드 양식 설계","레코드 집중의 분석 및 설계","접근 경로 설계","목표 DBMS에 맞는 스키마 설계"],"ans":4,"rate":66,"exp":{"concept":"데이터베이스 설계는 요구 조건 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현 순서로 진행한다. 논리적 설계는 개념 모델을 목표 DBMS에 맞는 논리 스키마로 바꾸는 단계이고, 물리적 설계는 그 스키마를 실제 저장 장치에 어떻게 저장할지 정하는 단계다. 물리적 설계에서는 저장 레코드 양식, 레코드 집중(클러스터링), 접근 경로(인덱스 등)를 설계한다.","choices":[{"verdict":"오답","why":"저장 레코드의 양식(형식)을 설계하는 것은 물리적 설계에서 하는 일이다."},{"verdict":"오답","why":"자주 함께 쓰이는 레코드를 가까이 저장하도록 레코드 집중을 분석·설계하는 것은 물리적 설계에서 하는 일이다."},{"verdict":"오답","why":"인덱스 등 접근 경로를 설계하는 것은 물리적 설계에서 하는 일이다."},{"verdict":"정답","why":"목표 DBMS에 맞는 스키마 설계는 논리적 설계 단계에서 하는 일이다. 물리적 설계 사항이 아니다."}],"keywords":[{"term":"개념적 설계","desc":"DBMS와 무관하게 E-R 다이어그램 등으로 개념 스키마 작성"},{"term":"논리적 설계","desc":"목표 DBMS에 맞는 논리 스키마 설계, 트랜잭션 인터페이스 설계"},{"term":"물리적 설계","desc":"저장 레코드 양식, 레코드 집중, 접근 경로 설계"}],"memo":"'목표 DBMS에 맞는'은 논리적 설계, '저장·레코드·접근 경로'는 물리적 설계의 표시어다."}},{"id":"written-2020-4-59","no":59,"unit":"데이터베이스 구축","q":"한 릴레이션 스키마가 4개 속성, 2개 후보키 그리고 그 스키마의 대응 릴레이션 인스턴스가 7개 튜플을 갖는다면 그 릴레이션의 차수(degree)는?","choices":["1","2","4","7"],"ans":3,"rate":70,"exp":{"concept":"릴레이션의 차수(Degree)는 속성(열)의 개수이고, 카디널리티(Cardinality)는 튜플(행)의 개수다. 이 릴레이션은 속성이 4개이므로 차수는 4다. 후보키가 2개라는 정보와 튜플이 7개라는 정보는 차수와 관계없다.","choices":[{"verdict":"오답","why":"1은 차수와 관계없는 값이다. 차수는 속성의 수 4다."},{"verdict":"오답","why":"2는 후보키의 개수다. 차수는 후보키 수가 아니라 속성의 수다."},{"verdict":"정답","why":"차수는 속성의 개수이므로 4다."},{"verdict":"오답","why":"7은 튜플의 개수, 즉 카디널리티다."}],"keywords":[{"term":"차수(Degree)","desc":"속성(열)의 수"},{"term":"카디널리티(Cardinality)","desc":"튜플(행)의 수"},{"term":"속성(Attribute)","desc":"릴레이션의 열, 데이터의 가장 작은 논리적 단위"}],"memo":"속성 수=차수(Degree), 튜플 수=카디널리티(Cardinality). 후보키 개수처럼 함께 주어진 다른 숫자는 함정이다."}},{"id":"written-2020-4-60","no":60,"unit":"데이터베이스 구축","q":"데이터웨어하우스의 기본적인 OLAP(on-line analytical processing) 연산이 아닌 것은?","choices":["translate","roll-up","dicing","drill-down"],"ans":1,"rate":59,"wiki":[{"title":"OLAP","url":"https://itwiki.kr/w/OLAP"}],"exp":{"concept":"OLAP(On-Line Analytical Processing)은 데이터 웨어하우스의 다차원 데이터를 사용자가 여러 관점에서 분석하는 기술이다. 기본 연산으로 요약 수준을 올리는 Roll-up, 세분화하는 Drill-down, 한 차원을 잘라 보는 Slicing, 여러 차원을 잘라 보는 Dicing, 축을 바꾸는 Pivoting 등이 있다.","choices":[{"verdict":"정답","why":"translate는 OLAP 연산이 아니다."},{"verdict":"오답","why":"Roll-up은 분석 단위를 상위로 올려 데이터를 요약하는 OLAP 연산이다(일별 → 월별)."},{"verdict":"오답","why":"Dicing은 여러 차원에서 범위를 지정해 데이터를 잘라 보는 OLAP 연산이다."},{"verdict":"오답","why":"Drill-down은 분석 단위를 하위로 내려 더 상세하게 보는 OLAP 연산이다(월별 → 일별)."}],"keywords":[{"term":"Roll-up","desc":"상세 데이터를 상위 수준으로 요약"},{"term":"Drill-down","desc":"요약 데이터를 하위 수준으로 상세화"},{"term":"Slicing","desc":"다차원 데이터에서 한 차원의 특정 값으로 잘라 보기"},{"term":"Dicing","desc":"여러 차원의 범위를 지정해 잘라 보기"},{"term":"Pivoting","desc":"보고서의 행·열 축을 서로 바꾸기"}],"memo":"OLAP 연산은 위아래(Roll-up, Drill-down), 자르기(Slice, Dice), 돌리기(Pivot). '번역(translate)'은 없다."}},{"id":"written-2020-4-61","no":61,"unit":"프로그래밍 언어 활용","q":"UNIX SHELL 환경 변수를 출력하는 명령어가 아닌 것은?","choices":["configenv","printenv","env","setenv"],"ans":1,"rate":49,"exp":{"concept":"유닉스(UNIX) 쉘에서 환경 변수를 확인하는 명령어로 env, printenv, setenv가 있다. env와 printenv는 현재 환경 변수 목록을 출력하고, setenv는 C 쉘(csh)에서 환경 변수를 설정하는 명령인데 인자 없이 실행하면 환경 변수 목록을 출력한다.","choices":[{"verdict":"정답","why":"configenv는 유닉스의 환경 변수 출력 명령어가 아니다."},{"verdict":"오답","why":"printenv는 환경 변수 목록이나 지정한 환경 변수의 값을 출력한다."},{"verdict":"오답","why":"env는 환경 변수 목록을 출력하며, 바꾼 환경에서 프로그램을 실행할 때도 쓴다."},{"verdict":"오답","why":"setenv는 C 쉘에서 환경 변수를 설정하는 명령으로, 인자 없이 실행하면 환경 변수 목록을 출력한다."}],"keywords":[{"term":"env","desc":"전체 환경 변수 출력"},{"term":"printenv","desc":"전체 또는 특정 환경 변수 값 출력"},{"term":"setenv","desc":"C 쉘에서 환경 변수 설정, 인자 없으면 목록 출력"},{"term":"export","desc":"본 쉘 계열에서 변수를 환경 변수로 지정"}],"memo":"환경 변수 출력은 env, printenv, setenv 세 개. 이름에 env가 들어가도 configenv는 없다."}},{"id":"written-2020-4-62","no":62,"unit":"프로그래밍 언어 활용","q":"Java 프로그래밍 언어의 정수 데이터 타입 중 'long'의 크기는?","choices":["1byte","2byte","4byte","8byte"],"ans":4,"rate":80,"exp":{"concept":"자바의 정수형 데이터 타입은 크기가 고정되어 있다. byte는 1바이트, short는 2바이트, int는 4바이트, long은 8바이트다. 실행 환경이 바뀌어도 크기가 달라지지 않는다.","choices":[{"verdict":"오답","why":"1바이트는 byte 타입의 크기다."},{"verdict":"오답","why":"2바이트는 short 타입의 크기다. 자바의 char도 2바이트다."},{"verdict":"오답","why":"4바이트는 int 타입의 크기다."},{"verdict":"정답","why":"long 타입은 8바이트(64비트)다."}],"keywords":[{"term":"byte","desc":"1바이트 정수"},{"term":"short","desc":"2바이트 정수"},{"term":"int","desc":"4바이트 정수, 정수의 기본형"},{"term":"long","desc":"8바이트 정수, 리터럴 끝에 L을 붙임"}],"memo":"자바 정수형은 byte·short·int·long 순서로 1·2·4·8바이트, 두 배씩 커진다."}},{"id":"written-2020-4-63","no":63,"unit":"프로그래밍 언어 활용","q":"Java에서 사용되는 출력 함수가 아닌 것은?","choices":["System.out.print( )","System.out.println( )","System.out.printing( )","System.out.printf( )"],"ans":3,"rate":88,"exp":{"concept":"자바의 표준 출력은 System.out 객체의 메서드로 한다. print()는 줄바꿈 없이 출력하고, println()은 출력 후 줄을 바꾸며, printf()는 %d, %s 같은 서식을 지정해 출력한다. printing()이라는 메서드는 없어서 쓰면 컴파일 오류가 난다.","choices":[{"verdict":"오답","why":"System.out.print()는 줄바꿈 없이 출력하는 자바 출력 메서드다."},{"verdict":"오답","why":"System.out.println()은 출력 후 줄을 바꾸는 자바 출력 메서드다."},{"verdict":"정답","why":"System.out.printing()이라는 메서드는 자바에 없다. 사용하면 메서드를 찾을 수 없다는 컴파일 오류가 난다."},{"verdict":"오답","why":"System.out.printf()는 서식 문자열로 형식을 지정해 출력하는 자바 출력 메서드다."}],"keywords":[{"term":"print()","desc":"줄바꿈 없이 출력"},{"term":"println()","desc":"출력 후 줄바꿈"},{"term":"printf()","desc":"서식 지정 출력, 예: printf(\"%d\", n)"}],"memo":"자바 출력 3형제는 print, println, printf. 'ing'로 끝나는 출력 메서드는 없다."}},{"id":"written-2020-4-64","no":64,"unit":"프로그래밍 언어 활용","q":"운영체제에서 커널의 기능이 아닌 것은?","choices":["프로세스 생성, 종료","사용자 인터페이스","기억 장치 할당, 회수","파일 시스템 관리"],"ans":2,"rate":66,"wiki":[{"title":"커널","url":"https://itwiki.kr/w/커널"}],"exp":{"concept":"커널(Kernel)은 운영체제의 핵심으로, 하드웨어를 직접 관리한다. 프로세스 생성·종료와 스케줄링, 기억 장치 할당·회수, 파일 시스템 관리, 입출력 관리가 커널의 일이다. 사용자의 명령을 받아 해석해 커널에 전달하는 사용자 인터페이스 역할은 쉘(Shell)이 맡는다.","choices":[{"verdict":"오답","why":"프로세스의 생성과 종료는 커널의 프로세스 관리 기능이다."},{"verdict":"정답","why":"사용자 인터페이스는 쉘(명령어 해석기)이 담당한다. 커널의 기능이 아니다."},{"verdict":"오답","why":"기억 장치의 할당과 회수는 커널의 메모리 관리 기능이다."},{"verdict":"오답","why":"파일 시스템 관리는 커널의 기능이다."}],"keywords":[{"term":"커널(Kernel)","desc":"프로세스·메모리·파일·입출력을 관리하는 운영체제의 핵심"},{"term":"쉘(Shell)","desc":"사용자 명령을 해석해 커널에 전달하는 명령어 해석기"},{"term":"유틸리티(Utility)","desc":"편집기, 컴파일러 등 사용자 편의를 위한 프로그램"}],"memo":"커널은 속(핵심), 쉘은 껍데기(사용자와 마주함). 사용자 인터페이스는 껍데기 쪽이다."}},{"id":"written-2020-4-65","no":65,"unit":"프로그래밍 언어 활용","q":"OSI 7계층에서 단말기 사이에 오류 수정과 흐름제어를 수행하여 신뢰성 있고 명확한 데이터를 전달하는 계층은?","choices":["전송 계층","응용 계층","세션 계층","표현 계층"],"ans":1,"rate":82,"wiki":[{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"}],"exp":{"concept":"OSI 7계층은 통신 과정을 물리, 데이터 링크, 네트워크, 전송, 세션, 표현, 응용 계층으로 나눈 모델이다. 전송 계층은 송신 단말과 수신 단말 사이(종단 간)에서 오류 제어와 흐름 제어를 수행해 신뢰성 있는 데이터 전송을 보장한다. TCP, UDP가 이 계층의 프로토콜이다.","choices":[{"verdict":"정답","why":"전송 계층은 종단 간(End-to-End) 오류 수정과 흐름 제어로 신뢰성 있고 투명한 데이터 전송을 제공한다."},{"verdict":"오답","why":"응용 계층은 사용자가 네트워크에 접근할 수 있도록 응용 서비스(HTTP, FTP 등)를 제공하는 계층이다."},{"verdict":"오답","why":"세션 계층은 송수신 측 사이의 대화(세션)를 설정·유지하고 동기점으로 동기화를 관리하는 계층이다."},{"verdict":"오답","why":"표현 계층은 데이터의 형식 변환, 암호화, 압축을 담당하는 계층이다."}],"keywords":[{"term":"데이터 링크 계층","desc":"인접 노드 사이의 흐름·오류 제어, 프레임 전송"},{"term":"네트워크 계층","desc":"경로 설정(라우팅), 패킷 전송"},{"term":"전송 계층","desc":"종단 간 신뢰성 있는 전송, 오류·흐름 제어, TCP·UDP"},{"term":"세션 계층","desc":"대화 관리와 동기화"},{"term":"표현 계층","desc":"형식 변환, 암호화, 압축"}],"memo":"오류·흐름 제어가 '인접 노드 사이'면 데이터 링크, '단말기 사이(종단 간)'면 전송 계층."}},{"id":"written-2020-4-66","no":66,"unit":"프로그래밍 언어 활용","q":"다음 쉘 스크립트의 의미로 옳은 것은?\n<img src=\"data/img/eip_written_20200926_066.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["wow 사용자가 로그인한 경우에만 반복문을 수행한다.","wow 사용자가 로그인할 때까지 반복문을 수행한다.","wow 문자열을 복사한다.","wow 사용자에 대한 정보를 무한 반복하여 출력한다."],"ans":2,"rate":71,"exp":{"concept":"쉘 스크립트의 until 문은 조건이 참이 될 때까지 반복한다(while의 반대). who는 현재 로그인한 사용자 목록을 출력하고, grep wow는 그중 wow가 들어간 줄을 찾는다. grep이 wow를 찾으면 성공(참)이 되어 반복이 끝나고, 못 찾으면 sleep 5로 5초 쉬고 다시 확인한다. 즉 wow 사용자가 로그인할 때까지 5초마다 확인하는 스크립트다.","choices":[{"verdict":"오답","why":"로그인한 경우에만 반복하는 것은 while 문의 동작이다. until은 조건이 참(wow가 로그인함)이 되면 반복을 끝낸다."},{"verdict":"정답","why":"wow가 로그인하지 않은 동안 5초씩 쉬며 반복하고, 로그인하면 반복을 끝낸다. wow 사용자가 로그인할 때까지 반복하는 스크립트다."},{"verdict":"오답","why":"스크립트에 문자열을 복사하는 명령은 없다. grep은 찾는 명령이다."},{"verdict":"오답","why":"반복 안에서 하는 일은 sleep 5뿐이며, wow가 로그인하면 반복이 끝나므로 무한 반복 출력이 아니다."}],"keywords":[{"term":"until 조건; do ...; done","desc":"조건이 참이 될 때까지 반복"},{"term":"while 조건; do ...; done","desc":"조건이 참인 동안 반복"},{"term":"who","desc":"현재 로그인한 사용자 목록 출력"},{"term":"grep","desc":"입력에서 지정한 문자열이 들어간 줄을 찾음"},{"term":"sleep n","desc":"n초 동안 대기"}],"memo":"until은 '~할 때까지', while은 '~하는 동안'. until 뒤 조건은 반복을 끝내는 조건이다."}},{"id":"written-2020-4-67","no":67,"unit":"프로그래밍 언어 활용","q":"다음 자바 코드를 실행한 결과는?\n<img src=\"data/img/eip_written_20200926_067.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["x＝7 y＝0","x＝6 y＝-1","x＝7 y＝-1","Unresolved compilation problem 오류 발생"],"ans":4,"rate":61,"exp":{"concept":"자바의 while 문 조건에는 반드시 boolean(true/false) 값이 와야 한다. C 언어는 0을 거짓, 0이 아닌 값을 참으로 보지만 자바는 정수를 조건으로 쓸 수 없다. y--는 int 값이므로 while (y--)는 컴파일 단계에서 '정수형을 boolean으로 변환할 수 없다'는 오류가 난다.","choices":[{"verdict":"오답","why":"x=7 y=0은 나올 수 없다. 자바에서는 컴파일 오류가 나고, 같은 코드를 C로 실행해도 마지막 비교에서 y--로 y가 한 번 더 줄어 -1이 된다."},{"verdict":"오답","why":"x=6 y=-1은 나올 수 없다. 자바에서는 컴파일 오류가 나며, C로 실행하면 x는 6번 증가해 7이 된다."},{"verdict":"오답","why":"x=7 y=-1은 같은 코드를 C 언어로 실행했을 때의 결과다. 자바는 정수를 조건식으로 쓸 수 없어 실행되지 않는다."},{"verdict":"정답","why":"while (y--)에서 y--는 int이므로 boolean이 필요한 자리에 맞지 않아 컴파일 오류가 난다. 이클립스에서는 Unresolved compilation problem으로 표시된다."}],"keywords":[{"term":"자바 조건식","desc":"if, while 조건에는 boolean만 허용"},{"term":"C 조건식","desc":"0은 거짓, 0이 아닌 값은 참"},{"term":"후위 감소(y--)","desc":"현재 값을 먼저 쓰고 나중에 1 감소"}],"memo":"자바 코드 문제에서 while(정수), if(정수)가 보이면 먼저 컴파일 오류를 의심한다."}},{"id":"written-2020-4-68","no":68,"unit":"프로그래밍 언어 활용","q":"다음 파이썬으로 구현된 프로그램의 실행 결과로 옳은 것은?\n<img src=\"data/img/eip_written_20200926_068.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["[20, 60]","[60, 20]","[0, 20, 40, 60]","[10, 30, 50, 70]"],"ans":3,"rate":70,"exp":{"concept":"파이썬 리스트 슬라이싱 a[시작:끝:간격]은 시작 인덱스부터 끝 인덱스 바로 앞까지 간격만큼 건너뛰며 꺼낸다. 시작을 비우면 0부터다. a[:7:2]는 인덱스 0, 2, 4, 6의 값을 꺼내므로 [0, 20, 40, 60]이다(끝 인덱스 7은 포함하지 않는다).","choices":[{"verdict":"오답","why":"[20, 60]은 인덱스 2와 6만 뽑은 결과다. 시작이 비어 있으므로 인덱스 0부터 2칸씩 꺼내야 한다."},{"verdict":"오답","why":"[60, 20]은 순서가 거꾸로다. 간격이 양수 2이므로 앞에서 뒤로 꺼낸다."},{"verdict":"정답","why":"인덱스 0, 2, 4, 6의 값 0, 20, 40, 60을 꺼낸다. 인덱스 8은 끝 값 7 이상이라 포함되지 않는다."},{"verdict":"오답","why":"[10, 30, 50, 70]은 인덱스 1, 3, 5, 7의 값이다. a[1:8:2]처럼 시작이 1일 때의 결과다."}],"keywords":[{"term":"슬라이싱 a[s:e:k]","desc":"인덱스 s부터 e-1까지 k 간격으로 추출"},{"term":"시작 생략","desc":"a[:e]는 처음(0)부터"},{"term":"끝 생략","desc":"a[s:]는 마지막까지"},{"term":"음수 간격","desc":"a[::-1]처럼 쓰면 거꾸로 추출"}],"memo":"슬라이싱 끝 인덱스는 '포함하지 않는다'. 0부터 2칸씩: 0, 2, 4, 6에서 멈춘다."}},{"id":"written-2020-4-69","no":69,"unit":"프로그래밍 언어 활용","q":"공통모듈의 재사용 범위에 따른 분류가 아닌 것은?","choices":["컴포넌트 재사용","더미코드 재사용","함수와 객체 재사용","애플리케이션 재사용"],"ans":2,"rate":71,"exp":{"concept":"공통 모듈은 여러 프로그램에서 함께 쓰는 기능을 모아 둔 모듈이다. 재사용 범위에 따라 함수와 객체 재사용, 컴포넌트 재사용, 애플리케이션 재사용으로 나뉜다. 범위가 작은 순서로 함수·객체 → 컴포넌트 → 애플리케이션이다.","choices":[{"verdict":"오답","why":"컴포넌트 재사용은 컴포넌트 단위로, 인터페이스를 통해 통신하며 재사용하는 방식이다."},{"verdict":"정답","why":"더미 코드 재사용은 재사용 범위에 따른 분류가 아니다. 더미 코드는 실제 기능 없이 자리를 채우는 임시 코드다."},{"verdict":"오답","why":"함수와 객체 재사용은 클래스나 메소드 단위로 소스 코드를 재사용하는 방식이다."},{"verdict":"오답","why":"애플리케이션 재사용은 공통 기능을 제공하는 애플리케이션을 공유해 재사용하는 방식이다."}],"keywords":[{"term":"함수와 객체 재사용","desc":"클래스·메소드 단위의 소스 코드 재사용"},{"term":"컴포넌트 재사용","desc":"컴포넌트 자체는 수정 없이 인터페이스로 통신해 재사용"},{"term":"애플리케이션 재사용","desc":"공통 기능을 제공하는 애플리케이션을 공유"}],"memo":"재사용 범위는 작은 것부터 '함수·객체 → 컴포넌트 → 애플리케이션' 세 단계."}},{"id":"written-2020-4-70","no":70,"unit":"프로그래밍 언어 활용","q":"다음과 같은 프로세스가 차례로 큐에 도착하였을 때, SJF(Shortest Job First) 정책을 사용할 경우 가장 먼저 처리되는 작업은?\n<img src=\"data/img/eip_written_20200926_070.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["P1","P2","P3","P4"],"ans":4,"rate":88,"exp":{"concept":"SJF(Shortest Job First)는 대기 중인 작업 가운데 실행 시간이 가장 짧은 작업을 먼저 처리하는 비선점 스케줄링이다. 도착 시간이 따로 주어지지 않았으므로 네 프로세스가 모두 큐에 있는 상태에서 고른다. 실행 시간은 P1 6, P2 8, P3 4, P4 3이므로 가장 짧은 P4가 먼저 처리되고, 이어서 P3 → P1 → P2 순서가 된다.","choices":[{"verdict":"오답","why":"P1은 실행 시간이 6으로, P4(3)와 P3(4) 다음인 세 번째로 처리된다. 먼저 도착한 순서로 처리하는 것은 FCFS다."},{"verdict":"오답","why":"P2는 실행 시간이 8로 가장 길어 마지막에 처리된다."},{"verdict":"오답","why":"P3는 실행 시간이 4로, P4(3) 다음에 처리된다."},{"verdict":"정답","why":"P4는 실행 시간이 3으로 가장 짧아 SJF에서 가장 먼저 처리된다."}],"keywords":[{"term":"SJF(Shortest Job First)","desc":"실행 시간이 가장 짧은 작업부터 처리, 비선점"},{"term":"FCFS(First Come First Served)","desc":"먼저 도착한 순서대로 처리, 비선점"},{"term":"SRT(Shortest Remaining Time)","desc":"남은 실행 시간이 가장 짧은 작업을 먼저, SJF의 선점 방식"},{"term":"HRN(Highest Response-ratio Next)","desc":"(대기 시간+서비스 시간)/서비스 시간이 큰 작업부터"}],"memo":"SJF는 '가장 짧은 일부터'. 표에서 실행 시간 최솟값을 찾으면 끝이다."}},{"id":"written-2020-4-71","no":71,"unit":"프로그래밍 언어 활용","q":"4개의 페이지를 수용할 수 있는 주기억장치가 있으며, 초기에는 모두 비어 있다고 가정한다. 다음의 순서로 페이지 참조가 발생할 때, FIFO 페이지 교체 알고리즘을 사용할 경우 페이지 결함의 발생 횟수는?\n<img src=\"data/img/eip_written_20200926_071.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["6회","7회","8회","9회"],"ans":1,"rate":75,"exp":{"concept":"FIFO(First In First Out) 페이지 교체는 주기억장치가 가득 찼을 때 가장 먼저 들어온 페이지를 내보내는 방식이다. 페이지 결함(Page Fault)은 참조하려는 페이지가 주기억장치에 없을 때 생긴다. 4개 프레임으로 1, 2, 3, 1, 2, 4, 5, 1을 참조하면 1(결함) [1], 2(결함) [1,2], 3(결함) [1,2,3], 1(적중), 2(적중), 4(결함) [1,2,3,4], 5(결함, 가장 먼저 들어온 1 교체) [2,3,4,5], 1(결함, 2 교체) [3,4,5,1]이 되어 결함은 총 6회다.","choices":[{"verdict":"정답","why":"1, 2, 3, 4, 5, 1을 참조할 때 각각 결함이 나서 6회다. 두 번째 1과 2는 이미 있어 적중한다."},{"verdict":"오답","why":"7회는 결함 횟수가 아니다. 네 번째와 다섯 번째 참조(1, 2)는 적중이다."},{"verdict":"오답","why":"8회는 모든 참조를 결함으로 센 값이다. 이미 적재된 페이지를 다시 참조하면 결함이 아니다."},{"verdict":"오답","why":"9회는 참조 횟수(8회)보다도 많아 나올 수 없는 값이다."}],"keywords":[{"term":"FIFO","desc":"가장 먼저 들어온 페이지를 먼저 교체"},{"term":"LRU(Least Recently Used)","desc":"가장 오랫동안 사용하지 않은 페이지를 교체"},{"term":"LFU(Least Frequently Used)","desc":"사용 횟수가 가장 적은 페이지를 교체"},{"term":"OPT(Optimal)","desc":"앞으로 가장 오랫동안 사용하지 않을 페이지를 교체"}],"memo":"빈 프레임이 남아 있는 동안 처음 보는 페이지는 모두 결함이다. 표를 그려 '없으면 결함'만 세면 실수가 없다."}},{"id":"written-2020-4-72","no":72,"unit":"프로그래밍 언어 활용","q":"TCP 흐름제어기법 중 프레임이 손실되었을 때, 손실된 프레임 1개를 전송하고 수신자의 응답을 기다리는 방식으로 한 번에 프레임 1개만 전송할 수 있는 기법은?","choices":["Slow Start","Sliding Window","Stop and Wait","Congestion Avoidance"],"ans":3,"rate":80,"exp":{"concept":"Stop and Wait는 송신 측이 프레임 하나를 보내고 수신 측의 응답(ACK)을 받은 뒤에야 다음 프레임을 보내는 방식이다. 한 번에 프레임 하나만 보내므로 단순하지만 효율이 낮다. 프레임이 손실되면 그 프레임 하나만 다시 보내고 또 응답을 기다린다.","choices":[{"verdict":"오답","why":"Slow Start는 TCP 혼잡 제어 기법으로, 윈도 크기를 1부터 시작해 응답을 받을 때마다 지수적으로 늘린다."},{"verdict":"오답","why":"Sliding Window는 수신 측의 응답 없이도 정해진 윈도 크기만큼 여러 프레임을 연속으로 보낼 수 있는 흐름 제어 기법이다."},{"verdict":"정답","why":"Stop and Wait는 프레임 하나를 보내고 응답을 기다리는 방식으로, 한 번에 프레임 하나만 전송한다."},{"verdict":"오답","why":"Congestion Avoidance(혼잡 회피)는 윈도 크기가 임계값에 도달한 뒤 선형적으로 조금씩 늘리는 TCP 혼잡 제어 기법이다."}],"keywords":[{"term":"Stop and Wait","desc":"프레임 1개 전송 후 ACK를 기다리는 흐름 제어"},{"term":"Sliding Window","desc":"윈도 크기만큼 여러 프레임을 연속 전송하는 흐름 제어"},{"term":"Slow Start","desc":"혼잡 윈도를 1부터 지수적으로 증가시키는 혼잡 제어"},{"term":"Congestion Avoidance","desc":"임계값 이후 윈도를 선형 증가시키는 혼잡 제어"}],"memo":"'한 번에 1개, 응답 기다림'이면 이름 그대로 멈추고 기다리는(Stop and Wait) 방식이다."}},{"id":"written-2020-4-73","no":73,"unit":"프로그래밍 언어 활용","q":"결합도(Coupling)에 대한 설명으로 틀린 것은?","choices":["데이터 결합도(Data Coupling)는 두 모듈이 매개변수로 자료를 전달할 때, 자료구조 형태로 전달되어 이용될 때 데이터가 결합되어 있다고 한다.","내용 결합도(Content Coupling)는 하나의 모듈이 직접적으로 다른 모듈의 내용을 참조할 때 두 모듈은 내용적으로 결합되어 있다고 한다.","공통 결합도(Common Coupling)는 두 모듈이 동일한 전역 데이터를 접근한다면 공통결합 되어 있다고 한다.","결합도(Coupling)는 두 모듈간의 상호작용, 또는 의존도 정도를 나타내는 것이다."],"ans":1,"rate":54,"wiki":[{"title":"결합도","url":"https://itwiki.kr/w/결합도"},{"title":"모듈화","url":"https://itwiki.kr/w/모듈화"}],"exp":{"concept":"결합도(Coupling)는 모듈 사이의 상호 의존 정도다. 약한 것부터 자료 → 스탬프 → 제어 → 외부 → 공통 → 내용 결합도 순이다. 자료(데이터) 결합도는 모듈 간 인터페이스가 단순한 자료 요소(값)로만 이루어진 경우이고, 배열이나 레코드 같은 자료 구조를 전달하면 스탬프 결합도다.","choices":[{"verdict":"정답","why":"매개변수로 자료 구조를 전달하는 것은 스탬프(Stamp) 결합도다. 데이터 결합도는 단순한 자료 요소만 전달할 때이므로 틀린 설명이다."},{"verdict":"오답","why":"내용 결합도는 한 모듈이 다른 모듈의 내부 기능이나 데이터를 직접 참조하거나 수정하는 경우다. 맞는 설명이다."},{"verdict":"오답","why":"공통 결합도는 여러 모듈이 같은 전역 데이터(공유 영역)를 사용하는 경우다. 맞는 설명이다."},{"verdict":"오답","why":"결합도는 두 모듈 사이의 상호 작용 또는 의존 정도를 나타낸다. 맞는 설명이다."}],"keywords":[{"term":"자료 결합도(Data Coupling)","desc":"단순 자료 요소만 매개변수로 전달, 가장 바람직"},{"term":"스탬프 결합도(Stamp Coupling)","desc":"배열·레코드 같은 자료 구조를 전달"},{"term":"제어 결합도(Control Coupling)","desc":"처리 방식을 제어하는 제어 신호를 전달"},{"term":"공통 결합도(Common Coupling)","desc":"전역 변수(공유 데이터)를 함께 사용"},{"term":"내용 결합도(Content Coupling)","desc":"다른 모듈의 내부를 직접 참조, 가장 나쁨"}],"memo":"결합도 순서는 '자스제외공내'(약함 → 강함). 자료 구조가 오가면 스탬프다."}},{"id":"written-2020-4-74","no":74,"unit":"프로그래밍 언어 활용","q":"응집도의 종류 중 서로 간에 어떠한 의미 있는 연관관계도 지니지 않은 기능 요소로 구성되는 경우이며, 서로 다른 상위 모듈에 의해 호출되어 처리상의 연관성이 없는 서로 다른 기능을 수행하는 경우의 응집도는?","choices":["Functional Cohesion","Sequential Cohesion","Logical Cohesion","Coincidental Cohesion"],"ans":4,"rate":59,"wiki":[{"title":"응집도","url":"https://itwiki.kr/w/응집도"}],"exp":{"concept":"응집도(Cohesion)는 한 모듈 안의 요소들이 얼마나 서로 관련되어 있는지를 나타낸다. 강한 것부터 기능적 → 순차적 → 교환적 → 절차적 → 시간적 → 논리적 → 우연적 응집도 순이다. 우연적 응집도는 서로 아무 관련 없는 기능이 한 모듈에 모여 있는 가장 나쁜 경우다.","choices":[{"verdict":"오답","why":"기능적 응집도(Functional Cohesion)는 모듈 안의 모든 요소가 하나의 기능을 위해 수행되는 가장 강한 응집도다."},{"verdict":"오답","why":"순차적 응집도(Sequential Cohesion)는 한 활동의 출력이 다음 활동의 입력으로 쓰이는 경우다."},{"verdict":"오답","why":"논리적 응집도(Logical Cohesion)는 비슷한 성격이나 유형의 처리 요소들을 한 모듈에 모은 경우다."},{"verdict":"정답","why":"우연적 응집도(Coincidental Cohesion)는 서로 의미 있는 연관이 없는 요소들로 구성된 경우로, 지문의 설명과 맞는다."}],"keywords":[{"term":"기능적 응집도","desc":"모든 요소가 단일 기능 수행, 가장 강함"},{"term":"순차적 응집도","desc":"앞 활동의 출력이 다음 활동의 입력"},{"term":"교환적 응집도","desc":"같은 입력·출력을 사용하는 서로 다른 기능을 모음"},{"term":"논리적 응집도","desc":"유사한 성격의 처리를 한 모듈에 모음"},{"term":"우연적 응집도","desc":"서로 관련 없는 요소들의 모음, 가장 약함"}],"memo":"응집도 순서는 '기순교절시논우'(강함 → 약함). '어떠한 연관도 없음'은 맨 끝 우연적이다."}},{"id":"written-2020-4-75","no":75,"unit":"프로그래밍 언어 활용","q":"자바에서 사용하는 접근제어자의 종류가 아닌 것은?","choices":["internal","private","default","public"],"ans":1,"rate":76,"exp":{"concept":"자바의 접근 제어자는 클래스나 멤버에 접근할 수 있는 범위를 정한다. public(어디서나), protected(같은 패키지와 자식 클래스), default(같은 패키지, 아무것도 안 쓴 경우), private(같은 클래스 안) 네 가지다. internal은 C#의 접근 제한자로, 자바에서는 키워드가 아니어서 쓰면 컴파일 오류가 난다.","choices":[{"verdict":"정답","why":"internal은 C#에서 같은 어셈블리 안에서만 접근을 허용하는 접근 제한자다. 자바의 접근 제어자가 아니다."},{"verdict":"오답","why":"private는 같은 클래스 안에서만 접근할 수 있는 자바의 접근 제어자다."},{"verdict":"오답","why":"default는 접근 제어자를 쓰지 않았을 때 적용되며, 같은 패키지 안에서만 접근할 수 있다."},{"verdict":"오답","why":"public은 모든 곳에서 접근할 수 있는 자바의 접근 제어자다."}],"keywords":[{"term":"public","desc":"모든 클래스에서 접근 가능"},{"term":"protected","desc":"같은 패키지와 다른 패키지의 자식 클래스에서 접근 가능"},{"term":"default","desc":"같은 패키지 안에서만 접근 가능, 제어자를 생략한 경우"},{"term":"private","desc":"같은 클래스 안에서만 접근 가능"}],"memo":"자바 접근 제어자는 넓은 순서로 public > protected > default > private 네 개뿐이다."}},{"id":"written-2020-4-76","no":76,"unit":"프로그래밍 언어 활용","q":"UDP 특성에 해당되는 것은?","choices":["데이터 전송 후, ACK를 받는다.","송신 중에 링크를 유지 관리하므로 신뢰성이 높다.","흐름제어나 순서제어가 없어 전송속도가 빠르다.","제어를 위한 오버헤드가 크다."],"ans":3,"rate":67,"wiki":[{"title":"UDP","url":"https://itwiki.kr/w/UDP"}],"exp":{"concept":"UDP(User Datagram Protocol)는 연결을 맺지 않고 데이터를 그냥 보내는 비연결형 전송 계층 프로토콜이다. 확인 응답(ACK), 흐름 제어, 순서 제어가 없어 신뢰성은 낮지만 오버헤드가 적어 빠르다. 그래서 실시간 스트리밍처럼 속도가 중요한 서비스에 쓰인다. 신뢰성을 챙기는 것은 TCP다.","choices":[{"verdict":"오답","why":"데이터 전송 후 ACK(확인 응답)를 받는 것은 TCP의 특성이다."},{"verdict":"오답","why":"연결을 설정하고 유지하며 신뢰성을 보장하는 것은 TCP의 특성이다."},{"verdict":"정답","why":"UDP는 흐름 제어나 순서 제어가 없어 전송 속도가 빠르다."},{"verdict":"오답","why":"제어를 위한 오버헤드가 큰 것은 TCP의 특성이다. UDP는 헤더가 단순해 오버헤드가 작다."}],"keywords":[{"term":"UDP","desc":"비연결형, 비신뢰성, 빠른 전송, 헤더 8바이트"},{"term":"TCP","desc":"연결형, 신뢰성 보장, 흐름·혼잡·오류 제어"},{"term":"3-way handshake","desc":"TCP의 연결 설정 과정(SYN, SYN+ACK, ACK)"}],"memo":"UDP는 '편지 던지기', TCP는 '등기 우편'. 확인·유지·제어가 붙으면 TCP다."}},{"id":"written-2020-4-77","no":77,"unit":"프로그래밍 언어 활용","q":"다음과 같은 세그먼트 테이블을 가지는 시스템에서 논리 주소(2, 176)에 대한 물리 주소는?\n<img src=\"data/img/eip_written_20200926_077.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["398","400","1928","1930"],"ans":1,"rate":69,"exp":{"concept":"세그먼트 기법에서 논리 주소는 (세그먼트 번호, 변위)로 나타낸다. 물리 주소는 세그먼트 테이블에서 해당 세그먼트의 시작 주소를 찾아 변위를 더해 구한다. 단, 변위가 세그먼트 길이보다 작아야 한다. (2, 176)은 세그먼트 2의 시작 주소 222에 변위 176을 더해 398이다. 176은 길이 198보다 작으므로 유효하다.","choices":[{"verdict":"정답","why":"세그먼트 2의 시작 주소 222 + 변위 176 = 398이다. 변위 176이 길이 198보다 작아 정상 주소다."},{"verdict":"오답","why":"400은 222 + 176 계산 결과와 맞지 않는다."},{"verdict":"오답","why":"1928은 세그먼트 1의 시작 주소 1752에 176을 더한 값이다. 세그먼트 번호는 2다."},{"verdict":"오답","why":"1930은 세그먼트 2의 주소 계산 결과가 아니다. 세그먼트 번호 2의 행을 봐야 한다."}],"keywords":[{"term":"세그먼테이션(Segmentation)","desc":"프로그램을 크기가 다른 논리적 단위(세그먼트)로 나눠 적재"},{"term":"물리 주소 계산","desc":"세그먼트 시작 주소 + 변위"},{"term":"세그먼트 테이블","desc":"각 세그먼트의 시작 주소와 길이를 기록한 표"},{"term":"변위 검사","desc":"변위가 세그먼트 길이 이상이면 주소 오류(트랩)"}],"memo":"세그먼트 번호는 '행 고르기', 변위는 '더하기'. 0번부터 세므로 2번은 세 번째 행이다."}},{"id":"written-2020-4-78","no":78,"unit":"프로그래밍 언어 활용","q":"TCP/IP에서 사용되는 논리주소를 물리주소로 변환시켜 주는 프로토콜은?","choices":["TCP","ARP","FTP","IP"],"ans":2,"rate":63,"wiki":[{"title":"ARP","url":"https://itwiki.kr/w/ARP"}],"exp":{"concept":"인터넷에서 컴퓨터는 IP 주소(논리 주소)로 상대를 찾지만, 같은 네트워크 안에서 실제로 데이터를 전달할 때는 MAC 주소(물리 주소)가 필요하다. ARP(Address Resolution Protocol)는 IP 주소를 MAC 주소로 바꿔 주고, 반대로 MAC 주소를 IP 주소로 바꾸는 것은 RARP다.","choices":[{"verdict":"오답","why":"TCP는 신뢰성 있는 연결형 데이터 전송을 담당하는 전송 계층 프로토콜이다."},{"verdict":"정답","why":"ARP는 IP 주소(논리 주소)를 MAC 주소(물리 주소)로 변환하는 프로토콜이다."},{"verdict":"오답","why":"FTP는 컴퓨터 사이에 파일을 주고받는 응용 계층 프로토콜이다."},{"verdict":"오답","why":"IP는 패킷의 주소 지정과 경로 설정을 담당하는 네트워크 계층 프로토콜이다."}],"keywords":[{"term":"ARP","desc":"IP 주소 → MAC 주소 변환"},{"term":"RARP","desc":"MAC 주소 → IP 주소 변환"},{"term":"ICMP","desc":"IP 전송 중 오류 보고와 진단 메시지 전달"},{"term":"IGMP","desc":"멀티캐스트 그룹 관리"}],"memo":"ARP는 논리 → 물리, 앞에 Reverse가 붙은 RARP는 물리 → 논리."}},{"id":"written-2020-4-79","no":79,"unit":"프로그래밍 언어 활용","q":"C언어에서 구조체를 사용하여 데이터를 처리할 때 사용하는 것은?","choices":["for","scanf","struct","abstract"],"ans":3,"rate":82,"wiki":[{"title":"C 언어 구조체","url":"https://itwiki.kr/w/C 언어 구조체"}],"exp":{"concept":"구조체는 서로 다른 자료형의 변수 여러 개를 하나로 묶어 쓰는 사용자 정의 자료형이다. C 언어에서는 struct 키워드로 정의한다. 예를 들어 struct student { char name[10]; int age; }; 처럼 이름과 나이를 한 덩어리로 다룬다.","choices":[{"verdict":"오답","why":"for는 반복문 키워드다."},{"verdict":"오답","why":"scanf는 키보드로 값을 입력받는 표준 입력 함수다."},{"verdict":"정답","why":"struct는 C 언어에서 구조체를 정의하고 선언할 때 쓰는 키워드다."},{"verdict":"오답","why":"abstract는 C 언어의 키워드가 아니다. 자바 등에서 추상 클래스와 추상 메서드를 선언할 때 쓴다."}],"keywords":[{"term":"struct","desc":"C의 구조체 정의 키워드"},{"term":"구조체 멤버 접근","desc":"변수는 점(.) 연산자, 포인터는 화살표(->) 연산자"},{"term":"typedef","desc":"자료형에 새 이름을 붙이는 키워드"}],"memo":"구조체(Structure)의 줄임말이 struct다."}},{"id":"written-2020-4-80","no":80,"unit":"프로그래밍 언어 활용","q":"PHP에서 사용 가능한 연산자가 아닌 것은?","choices":["@","#","＜＞","==="],"ans":2,"rate":53,"exp":{"concept":"PHP는 웹 서버에서 실행되는 스크립트 언어다. @는 오류 메시지를 숨기는 오류 제어 연산자, <>는 같지 않음을 뜻하는 비교 연산자(!=와 같음), ===는 값과 자료형이 모두 같은지 비교하는 연산자다. #은 연산자가 아니라 한 줄 주석을 시작하는 기호다.","choices":[{"verdict":"오답","why":"@는 식 앞에 붙여 그 식에서 나는 오류 메시지를 출력하지 않게 하는 PHP의 오류 제어 연산자다."},{"verdict":"정답","why":"#은 PHP에서 한 줄 주석을 표시하는 기호로, 연산자가 아니다."},{"verdict":"오답","why":"<>는 두 값이 같지 않으면 참이 되는 PHP의 비교 연산자다."},{"verdict":"오답","why":"===는 값과 자료형이 모두 같으면 참이 되는 PHP의 비교 연산자다."}],"keywords":[{"term":"@","desc":"PHP 오류 제어 연산자, 오류 메시지 숨김"},{"term":"==와 ===","desc":"==는 값만, ===는 값과 자료형까지 비교"},{"term":"<>와 !=","desc":"둘 다 같지 않음 비교"},{"term":"PHP 주석","desc":"//와 #은 한 줄 주석, /* */는 여러 줄 주석"}],"memo":"PHP에서 #은 주석이다. 주석 기호는 연산자가 아니다."}},{"id":"written-2020-4-81","no":81,"unit":"정보시스템 구축 관리","q":"이용자가 인터넷과 같은 공중망에 사설망을 구축하여 마치 전용망을 사용하는 효과를 가지는 보안 솔루션은?","choices":["ZIGBEE","KDD","IDS","VPN"],"ans":4,"rate":83,"wiki":[{"title":"ZIGBEE","url":"https://itwiki.kr/w/ZIGBEE"},{"title":"KDD","url":"https://itwiki.kr/w/KDD"},{"title":"IDS","url":"https://itwiki.kr/w/IDS"},{"title":"VPN","url":"https://itwiki.kr/w/VPN"}],"exp":{"concept":"VPN(Virtual Private Network, 가상 사설망)은 인터넷 같은 공중망 위에 암호화된 터널을 만들어, 마치 회사 전용 회선을 쓰는 것처럼 안전하게 통신하게 하는 보안 솔루션이다. 공용 도로 위에 나만 다니는 투명 터널을 만드는 것과 비슷하다.","choices":[{"verdict":"오답","why":"지그비(ZigBee)는 저전력·저속의 근거리 무선 통신 기술로, 센서 네트워크 등에 쓰인다."},{"verdict":"오답","why":"KDD(Knowledge Discovery in Databases)는 대량의 데이터베이스에서 유용한 지식을 찾아내는 과정이다."},{"verdict":"오답","why":"IDS(Intrusion Detection System, 침입 탐지 시스템)는 시스템에 대한 비정상적인 사용이나 침입을 실시간으로 탐지하는 시스템이다."},{"verdict":"정답","why":"VPN은 공중망에 암호화 기술로 사설망을 구축해 전용망을 쓰는 것과 같은 효과를 내는 보안 솔루션이다."}],"keywords":[{"term":"VPN(Virtual Private Network)","desc":"공중망에 암호화 터널로 사설망을 구축"},{"term":"IDS(Intrusion Detection System)","desc":"침입을 탐지하는 시스템"},{"term":"IPS(Intrusion Prevention System)","desc":"침입을 탐지하고 차단까지 하는 시스템"},{"term":"방화벽(Firewall)","desc":"내부망과 외부망 사이에서 허가되지 않은 트래픽을 차단"}],"memo":"'공중망에 사설망', '전용망 효과'가 나오면 VPN(가상 사설망)이다."}},{"id":"written-2020-4-82","no":82,"unit":"정보시스템 구축 관리","q":"CMM(Capability Maturity Model) 모델의 레벨로 옳지 않은 것은?","choices":["최적단계","관리단계","계획단계","정의단계"],"ans":3,"rate":52,"exp":{"concept":"CMM(Capability Maturity Model, 능력 성숙도 모델)은 소프트웨어 개발 조직의 업무 능력과 성숙도를 평가하는 모델이다. 성숙도는 초기(Initial) → 반복(Repeatable) → 정의(Defined) → 관리(Managed) → 최적화(Optimizing)의 5단계로 나뉜다. 계획 단계는 없다.","choices":[{"verdict":"오답","why":"최적(최적화) 단계는 프로세스를 지속적으로 개선하는 CMM의 5단계다."},{"verdict":"오답","why":"관리 단계는 프로세스를 정량적으로 측정·관리하는 CMM의 4단계다."},{"verdict":"정답","why":"계획 단계는 CMM의 성숙도 단계에 없다."},{"verdict":"오답","why":"정의 단계는 조직 차원의 표준 프로세스를 정의해 활용하는 CMM의 3단계다."}],"keywords":[{"term":"초기(Initial)","desc":"1단계, 정의된 프로세스 없이 개인 역량에 의존"},{"term":"반복(Repeatable)","desc":"2단계, 기본적인 프로젝트 관리 체계 확립"},{"term":"정의(Defined)","desc":"3단계, 조직의 표준 프로세스 정의"},{"term":"관리(Managed)","desc":"4단계, 프로세스를 정량적으로 관리"},{"term":"최적화(Optimizing)","desc":"5단계, 프로세스를 지속적으로 개선"}],"memo":"CMM 5단계는 '초·반·정·관·최'. 계획이라는 이름은 없다."}},{"id":"written-2020-4-83","no":83,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 생명주기 모형으로 가장 옳은 것은?\n<img src=\"data/img/eip_written_20200926_083.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["패키지 모형","코코모 모형","폭포수 모형","관계형 모델"],"ans":3,"rate":93,"exp":{"concept":"폭포수 모형(Waterfall Model)은 가장 오래되고 널리 쓰인 소프트웨어 생명 주기 모형으로, 요구 분석 → 설계 → 구현 → 테스트 → 유지보수를 순서대로 진행한다. 각 단계의 결과를 확인해야 다음 단계로 넘어가고, 앞 단계로 돌아가기 어려워 요구 사항 변경이 어렵다. 선형 순차적 모형, 고전적 생명 주기 모형이라고도 한다.","choices":[{"verdict":"오답","why":"패키지 모형은 지문이 설명하는 선형 순차적 생명 주기 모형이 아니다."},{"verdict":"오답","why":"코코모(COCOMO) 모형은 소스 코드 줄 수(LOC)를 바탕으로 개발 비용을 산정하는 비용 추정 모형이다. 생명 주기 모형이 아니다."},{"verdict":"정답","why":"폭포수 모형은 가장 오래된 모형으로 적용 사례가 많고, 단계별 결과를 확인해야 다음으로 넘어가며, 선형 순차적·고전적 생명 주기 모형이라고 부른다."},{"verdict":"오답","why":"관계형 모델은 데이터를 표(릴레이션) 형태로 표현하는 데이터 모델이다. 생명 주기 모형이 아니다."}],"keywords":[{"term":"폭포수 모형(Waterfall Model)","desc":"선형 순차적 모형, 고전적 생명 주기 모형"},{"term":"프로토타입 모형(Prototype Model)","desc":"견본을 만들어 사용자 요구를 확인하며 개발"},{"term":"나선형 모형(Spiral Model)","desc":"위험 분석을 더해 여러 번 반복하는 점진적 모형"},{"term":"COCOMO","desc":"LOC 기반 소프트웨어 비용 추정 모형"}],"memo":"'가장 오래된', '선형 순차적', '고전적'은 모두 폭포수 모형의 별명이다."}},{"id":"written-2020-4-84","no":84,"unit":"정보시스템 구축 관리","q":"서비스 지향 아키텍처 기반 애플리케이션을 구성하는 층이 아닌 것은?","choices":["표현층","프로세스층","제어 클래스층","비즈니스층"],"ans":3,"rate":54,"exp":{"concept":"서비스 지향 아키텍처(SOA, Service Oriented Architecture)는 기업의 기능을 재사용 가능한 서비스 단위로 만들어 조합하는 구조다. SOA 기반 애플리케이션은 표현 계층, 업무 프로세스 계층, 서비스 중간 계층, 애플리케이션 계층, 데이터 저장 계층처럼 업무 기능 단위의 계층으로 나누어 설명한다. 제어 클래스는 객체지향 분석에서 쓰는 클래스 분류 이름으로, SOA의 계층이 아니다.","choices":[{"verdict":"오답","why":"표현층(Presentation Layer)은 사용자에게 화면을 보여 주고 입력을 받는 SOA의 계층이다."},{"verdict":"오답","why":"프로세스층은 여러 서비스를 엮어 업무 흐름을 구성하는 SOA의 계층이다."},{"verdict":"정답","why":"제어 클래스층은 SOA 기반 애플리케이션의 계층이 아니다. 제어(Control) 클래스는 객체지향 분석에서 경계·엔티티 클래스와 함께 쓰는 클래스 분류다."},{"verdict":"오답","why":"비즈니스층은 업무(비즈니스) 로직을 처리하는 계층으로, SOA 계층 구분에서 업무 처리를 맡는 층에 해당한다."}],"keywords":[{"term":"SOA(Service Oriented Architecture)","desc":"기능을 재사용 가능한 서비스로 나누어 조합하는 아키텍처"},{"term":"ESB(Enterprise Service Bus)","desc":"SOA에서 서비스 사이의 통신을 중개하는 버스형 미들웨어"},{"term":"웹 서비스(Web Service)","desc":"SOAP, WSDL, UDDI로 서비스를 제공·검색하는 방식"}],"memo":"SOA 계층은 화면(표현), 업무 흐름(프로세스), 업무 로직(비즈니스) 같은 '업무' 단위다. 클래스 이름이 붙은 층은 없다."}},{"id":"written-2020-4-85","no":85,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 스토리지 시스템은?\n<img src=\"data/img/eip_written_20200926_085.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["DAS","NAS","N-SCREEN","NFC"],"ans":1,"rate":74,"exp":{"concept":"DAS(Direct Attached Storage)는 하드디스크 같은 저장 장치를 서버(호스트)에 직접 연결하는 방식이다. 중간에 네트워크 장비 없이 바로 꽂으므로 설치가 간단하고 빠르지만, 다른 서버와 저장 장치를 공유하기 어렵다. 지문의 '호스트 버스 어댑터에 직접 연결', '네트워크 디바이스 없이 직접 연결'이 DAS의 특징이다.","choices":[{"verdict":"정답","why":"DAS는 저장 장치를 호스트 버스 어댑터에 직접 연결하며, 저장 장치와 호스트 사이에 네트워크 장치가 없다."},{"verdict":"오답","why":"NAS(Network Attached Storage)는 저장 장치를 네트워크(LAN)를 통해 연결해 여러 서버가 파일 단위로 공유하는 방식이다."},{"verdict":"오답","why":"N-스크린(N-Screen)은 여러 단말기에서 같은 콘텐츠를 끊김 없이 이어서 이용하게 하는 서비스다. 스토리지 시스템이 아니다."},{"verdict":"오답","why":"NFC(Near Field Communication)는 약 10cm 이내에서 데이터를 주고받는 근거리 무선 통신 기술이다. 스토리지 시스템이 아니다."}],"keywords":[{"term":"DAS(Direct Attached Storage)","desc":"서버에 저장 장치를 직접 연결"},{"term":"NAS(Network Attached Storage)","desc":"네트워크로 연결된 파일 서버형 스토리지"},{"term":"SAN(Storage Area Network)","desc":"서버와 저장 장치를 전용 고속 네트워크로 연결"}],"memo":"Direct는 '직접', Network는 '네트워크 경유'. '직접 연결'이 반복되면 DAS."}},{"id":"written-2020-4-86","no":86,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 프레임워크의 적용 효과로 볼 수 없는 것은?","choices":["공통 컴포넌트 재사용으로 중복 예산 절감","기술종속으로 인한 선행사업자 의존도 증대","표준화된 연계모듈 활용으로 상호 운용성 향상","개발표준에 의한 모듈화로 유지보수 용이"],"ans":2,"rate":89,"exp":{"concept":"소프트웨어 개발 프레임워크는 개발에 필요한 공통 기능과 구조를 미리 만들어 제공하는 틀이다. 전자정부 표준 프레임워크처럼 표준화된 프레임워크를 쓰면 공통 컴포넌트를 재사용해 예산을 아끼고, 연계 모듈이 표준화되어 상호 운용성이 좋아지며, 특정 업체 기술에 묶이는 문제를 줄일 수 있다.","choices":[{"verdict":"오답","why":"공통 컴포넌트를 재사용하면 같은 기능을 반복 개발하지 않아 중복 예산이 절감된다. 맞는 효과다."},{"verdict":"정답","why":"표준 프레임워크는 특정 업체 기술에 종속되는 문제를 줄여 선행 사업자 의존도를 낮춘다. 의존도가 증대된다는 것은 적용 효과가 아니다."},{"verdict":"오답","why":"표준화된 연계 모듈을 활용하면 시스템 간 상호 운용성이 향상된다. 맞는 효과다."},{"verdict":"오답","why":"개발 표준에 따라 모듈화되어 있어 유지보수가 쉬워진다. 맞는 효과다."}],"keywords":[{"term":"프레임워크(Framework)","desc":"공통 구조와 기능을 제공하는 반제품 형태의 개발 틀"},{"term":"전자정부 표준 프레임워크","desc":"공공 정보화 사업에 쓰는 표준 개발 프레임워크"},{"term":"프레임워크 특성","desc":"모듈화, 재사용성, 확장성, 제어의 역흐름"}],"memo":"프레임워크는 의존도를 '낮추는' 쪽이다. 단점처럼 들리는 '증대'는 효과가 아니다."}},{"id":"written-2020-4-87","no":87,"unit":"정보시스템 구축 관리","q":"SoftTech사에서 개발된 것으로 구조적 요구 분석을 하기 위해 블록 다이어그램을 채택한 자동화 도구는?","choices":["SREM","PSL/PSA","HIPO","SADT"],"ans":4,"rate":51,"exp":{"concept":"요구 분석을 돕는 자동화 도구에는 SADT, SREM, PSL/PSA, TAGS 등이 있다. SADT(Structured Analysis and Design Technique)는 SoftTech사가 개발한 도구로, 블록 다이어그램을 사용해 구조적으로 요구를 분석하고 설계한다.","choices":[{"verdict":"오답","why":"SREM은 TRW사가 실시간 처리 소프트웨어 시스템의 요구 사항을 명세하기 위해 개발한 도구로, RSL과 REVS를 사용한다."},{"verdict":"오답","why":"PSL/PSA는 미시간 대학에서 개발한 도구로, 문제 기술 언어(PSL)와 이를 분석하는 PSA로 구성된다."},{"verdict":"오답","why":"HIPO(Hierarchy Input Process Output)는 시스템을 하향식으로 문서화하는 도구로, 도식 목차·총괄·세부 다이어그램으로 구성된다."},{"verdict":"정답","why":"SADT는 SoftTech사가 개발했으며, 블록 다이어그램을 채택해 구조적 요구 분석을 지원하는 자동화 도구다."}],"keywords":[{"term":"SADT","desc":"SoftTech사, 블록 다이어그램을 이용한 구조적 분석·설계 도구"},{"term":"SREM","desc":"TRW사, 실시간 처리 시스템 요구 명세, RSL·REVS 사용"},{"term":"PSL/PSA","desc":"미시간 대학, 문제 기술 언어와 분석기"},{"term":"HIPO","desc":"하향식 문서화 도구, 가시적 도표 사용"}],"memo":"SADT는 SoftTech사·블록 다이어그램, SREM은 TRW사, PSL/PSA는 미시간 대학. 도구와 개발처를 짝지어 외운다."}},{"id":"written-2020-4-88","no":88,"unit":"정보시스템 구축 관리","q":"익스트림 프로그래밍 (eXtreme Programming)의 5가지 가치에 속하지 않는 것은?","choices":["의사소통","단순성","피드백","고객 배제"],"ans":4,"rate":95,"exp":{"concept":"XP(eXtreme Programming)는 고객과 함께 짧은 주기로 개발하는 애자일 방법론이다. 핵심 가치는 용기(Courage), 단순성(Simplicity), 의사소통(Communication), 피드백(Feedback), 존중(Respect) 다섯 가지다. 고객을 개발에 적극 참여시키는 것이 XP의 특징이므로 고객 배제는 정반대다.","choices":[{"verdict":"오답","why":"의사소통은 XP의 핵심 가치로, 개발자와 고객, 팀원 사이의 원활한 소통을 강조한다."},{"verdict":"오답","why":"단순성은 XP의 핵심 가치로, 필요한 것만 가장 단순하게 만든다."},{"verdict":"오답","why":"피드백은 XP의 핵심 가치로, 테스트와 고객 의견을 빠르게 반영한다."},{"verdict":"정답","why":"고객 배제는 XP의 가치가 아니다. XP는 고객이 개발 과정에 직접 참여하는 것을 중시한다."}],"keywords":[{"term":"XP 5가지 가치","desc":"용기, 단순성, 의사소통, 피드백, 존중"},{"term":"고객 상주(On-Site Customer)","desc":"고객이 개발 현장에 함께 있으며 요구를 바로 전달"},{"term":"짧은 릴리즈(Small Releases)","desc":"작은 기능 단위로 자주 배포"}],"memo":"XP 가치는 '용·단·의·피·존'. 애자일은 고객과 함께하므로 '배제'는 무조건 오답."}},{"id":"written-2020-4-89","no":89,"unit":"정보시스템 구축 관리","q":"다음은 정보의 접근통제 정책에 대한 설명이다. (ㄱ)에 들어갈 내용으로 옳은 것은?\n<img src=\"data/img/eip_written_20200926_089.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["NAC","MAC","SDAC","AAC"],"ans":2,"rate":67,"exp":{"concept":"접근 통제 정책은 누가 어떤 자원에 접근할 수 있는지 정하는 규칙이다. MAC(강제적 접근 통제)는 시스템이 주체와 객체의 보안 등급(Label)을 비교해 접근을 결정하며, 정책이 고정적이고 중앙 집중적이다. DAC(임의적 접근 통제)는 데이터 소유자가 신분(Identity)에 따라 권한을 주고, RBAC(역할 기반 접근 통제)는 중앙 관리자가 역할(Role)에 따라 권한을 준다. 표의 (ㄱ) 열은 권한 부여가 시스템, 접근 결정이 보안 등급이므로 MAC이다.","choices":[{"verdict":"오답","why":"NAC(Network Access Control)는 네트워크에 접속하는 단말기의 보안 상태를 검사해 접속을 통제하는 솔루션으로, 표의 접근 통제 정책 분류가 아니다."},{"verdict":"정답","why":"MAC(Mandatory Access Control)는 시스템이 권한을 부여하고 보안 등급(Label)으로 접근을 결정하며, 정책 변경이 어렵고 안정적·중앙 집중적이다."},{"verdict":"오답","why":"SDAC는 출제 범위의 표준 접근 통제 정책 이름이 아니다."},{"verdict":"오답","why":"AAC는 출제 범위의 표준 접근 통제 정책 이름이 아니다."}],"keywords":[{"term":"MAC(Mandatory Access Control)","desc":"강제적 접근 통제, 보안 등급(Label) 기반, 시스템이 권한 부여"},{"term":"DAC(Discretionary Access Control)","desc":"임의적 접근 통제, 신분(Identity) 기반, 데이터 소유자가 권한 부여"},{"term":"RBAC(Role Based Access Control)","desc":"역할 기반 접근 통제, 역할(Role) 기반, 중앙 관리자가 권한 부여"}],"memo":"MAC은 Label, DAC는 Identity, RBAC은 Role. 'Mandatory=강제'라 시스템이 정하고 바꾸기 어렵다."}},{"id":"written-2020-4-90","no":90,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 모델 중 나선형 모델의 4가지 주요 활동이 순서대로 나열된 것은?\n<img src=\"data/img/eip_written_20200926_090.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Ⓐ-Ⓑ-Ⓓ-Ⓒ순으로 반복","Ⓐ-Ⓓ-Ⓒ-Ⓑ순으로 반복","Ⓐ-Ⓑ-Ⓒ-Ⓓ순으로 반복","Ⓐ-Ⓒ-Ⓑ-Ⓓ순으로 반복"],"ans":2,"rate":79,"exp":{"concept":"나선형 모형(Spiral Model)은 보헴(Boehm)이 제안한 모형으로, 여러 번의 개발 과정을 나선처럼 반복하며 점진적으로 완성한다. 한 바퀴는 계획 수립 → 위험 분석 → 개발 및 검증(공학적 개발) → 고객 평가 순서로 이루어진다. 기호로 바꾸면 Ⓐ계획 수립 → Ⓓ위험 분석 → Ⓒ개발 및 검증 → Ⓑ고객 평가다.","choices":[{"verdict":"오답","why":"Ⓐ-Ⓑ-Ⓓ-Ⓒ는 계획 수립 다음에 고객 평가가 오는 순서로, 나선형 모형의 순서가 아니다."},{"verdict":"정답","why":"Ⓐ계획 수립 → Ⓓ위험 분석 → Ⓒ개발 및 검증 → Ⓑ고객 평가 순서로 반복하는 것이 나선형 모형이다."},{"verdict":"오답","why":"Ⓐ-Ⓑ-Ⓒ-Ⓓ는 기호를 순서대로 나열한 것일 뿐, 위험 분석이 맨 끝에 와서 틀렸다."},{"verdict":"오답","why":"Ⓐ-Ⓒ-Ⓑ-Ⓓ는 위험 분석을 맨 뒤로 미루고 계획 다음에 바로 개발로 넘어가는 순서로, 나선형 모형의 순서가 아니다."}],"keywords":[{"term":"나선형 모형(Spiral Model)","desc":"위험 분석을 포함해 반복하는 점진적 생명 주기 모형"},{"term":"위험 분석(Risk Analysis)","desc":"나선형 모형의 핵심, 개발 전에 위험을 찾아 줄임"},{"term":"나선형 4단계","desc":"계획 수립 → 위험 분석 → 개발 및 검증 → 고객 평가"}],"memo":"나선형은 '계·위·개·고'. 위험 분석이 개발보다 먼저라는 것이 핵심이다."}},{"id":"written-2020-4-91","no":91,"unit":"정보시스템 구축 관리","q":"소프트웨어 비용 추정모형(estimation models)이 아닌 것은?","choices":["COCOMO","Putnam","Function-Point","PERT"],"ans":4,"rate":62,"exp":{"concept":"소프트웨어 비용 추정 모형은 개발에 드는 노력과 비용을 미리 계산하는 방법이다. COCOMO(소스 코드 줄 수 기반), Putnam(생명 주기 전 과정의 노력 분포 기반), 기능 점수(FP, 기능 수와 복잡도 기반) 모형이 대표적이다. PERT는 비용이 아니라 프로젝트 일정을 계획·관리하는 기법이다.","choices":[{"verdict":"오답","why":"COCOMO는 보헴이 제안한 모형으로, 소스 코드 줄 수(LOC)를 바탕으로 비용을 산정한다."},{"verdict":"오답","why":"Putnam 모형은 소프트웨어 생명 주기 전 과정에 투입될 노력의 분포를 가정해 비용을 산정한다."},{"verdict":"오답","why":"기능 점수(Function Point) 모형은 소프트웨어 기능을 점수화하고 가중치를 곱해 비용을 산정한다."},{"verdict":"정답","why":"PERT(Program Evaluation and Review Technique)는 작업의 일정을 낙관치·기대치·비관치로 추정하는 일정 관리 기법이다. 비용 추정 모형이 아니다."}],"keywords":[{"term":"COCOMO","desc":"LOC 기반 비용 추정, 조직형·반분리형·내장형"},{"term":"Putnam","desc":"Rayleigh-Norden 곡선의 노력 분포를 가정한 비용 추정"},{"term":"기능 점수(FP)","desc":"기능별 가중치로 기능 점수를 구해 비용 추정"},{"term":"PERT","desc":"일정 관리 기법, 낙관치·기대치·비관치로 작업 기간 추정"},{"term":"CPM","desc":"임계 경로를 찾아 일정을 관리하는 기법"}],"memo":"PERT, CPM, 간트 차트는 '일정' 관리 도구다. 비용 추정 모형 문제에 나오면 지운다."}},{"id":"written-2020-4-92","no":92,"unit":"정보시스템 구축 관리","q":"공개키 암호화 방식에 대한 설명으로 틀린 것은?","choices":["공개키로 암호화된 메시지는 반드시 공개키로 복호화 해야 한다.","비대칭 암호기법이라고도 한다.","대표적인 기법은 RSA 기법이 있다.","키 분배가 용이하고, 관리해야 할 키 개수가 적다."],"ans":1,"rate":61,"exp":{"concept":"공개키 암호화 방식은 암호화할 때와 복호화할 때 서로 다른 키를 쓰는 비대칭 암호 기법이다. 누구나 아는 공개키로 암호화하면, 그 짝인 개인키(비밀키)를 가진 사람만 복호화할 수 있다. 자물쇠(공개키)는 누구에게 나눠 줘도 되지만 열쇠(개인키)는 나만 갖는 것과 같다. 대표적인 기법은 RSA다.","choices":[{"verdict":"정답","why":"공개키로 암호화한 메시지는 그 짝인 개인키(비밀키)로만 복호화할 수 있다. 공개키로 복호화해야 한다는 설명은 틀렸다."},{"verdict":"오답","why":"암호화 키와 복호화 키가 서로 달라 비대칭 암호 기법이라고 한다. 맞는 설명이다."},{"verdict":"오답","why":"RSA는 큰 수의 소인수 분해가 어렵다는 점을 이용한 대표적인 공개키 암호 기법이다. 맞는 설명이다."},{"verdict":"오답","why":"공개키는 공개해도 되므로 키 분배가 쉽고, 사용자 n명에게 필요한 키가 2n개로 대칭키 방식의 n(n-1)/2개보다 적다. 맞는 설명이다."}],"keywords":[{"term":"공개키 암호(비대칭키)","desc":"암호화 키(공개키)와 복호화 키(개인키)가 다름, RSA"},{"term":"대칭키 암호(비밀키)","desc":"암호화와 복호화에 같은 키 사용, DES·AES·SEED"},{"term":"키 개수","desc":"n명일 때 공개키 방식 2n개, 대칭키 방식 n(n-1)/2개"}],"memo":"공개키로 잠그면 개인키로 연다. 같은 키로 잠그고 여는 것은 대칭키 방식이다."}},{"id":"written-2020-4-93","no":93,"unit":"정보시스템 구축 관리","q":"다음이 설명하는 다중화 기술은?\n<img src=\"data/img/eip_written_20200926_093.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Wavelength Division Multiplexing","Frequency Division Multiplexing","Code Division Multiplexing","Time Division Multiplexing"],"ans":1,"rate":80,"exp":{"concept":"다중화는 하나의 통신 회선으로 여러 신호를 동시에 보내는 기술이다. 파장 분할 다중화(WDM)는 광섬유에서 빛의 파장을 다르게 해 여러 광신호를 동시에 보내는 방식이다. 파장이 다른 빛끼리는 서로 간섭하지 않는다는 성질을 이용한다. 무지개의 여러 색을 한 유리관에 동시에 흘려보내는 모습을 떠올리면 된다.","choices":[{"verdict":"정답","why":"파장 분할 다중화(WDM)는 광섬유에서 파장이 서로 다른 여러 광신호를 동시에 전송하는 방식으로, 지문과 맞는다."},{"verdict":"오답","why":"주파수 분할 다중화(FDM)는 회선의 주파수 대역을 여러 작은 대역으로 나눠 동시에 전송하는 방식이다."},{"verdict":"오답","why":"코드 분할 다중화(CDM)는 각 신호에 서로 다른 코드를 부여해 같은 대역에서 동시에 전송하는 방식이다."},{"verdict":"오답","why":"시분할 다중화(TDM)는 전송 시간을 일정한 간격(타임 슬롯)으로 나눠 번갈아 전송하는 방식이다."}],"keywords":[{"term":"WDM(Wavelength Division Multiplexing)","desc":"광섬유에서 파장별로 나눠 다중화"},{"term":"FDM(Frequency Division Multiplexing)","desc":"주파수 대역별로 나눠 다중화"},{"term":"TDM(Time Division Multiplexing)","desc":"시간 슬롯별로 나눠 다중화"},{"term":"CDM(Code Division Multiplexing)","desc":"고유 코드별로 나눠 다중화"}],"memo":"'광섬유'와 '파장'이 나오면 WDM. Wavelength가 파장이다."}},{"id":"written-2020-4-94","no":94,"unit":"정보시스템 구축 관리","q":"웹페이지에 악의적인 스크립트를 포함시켜 사용자 측에서 실행되게 유도함으로써, 정보유출 등의 공격을 유발할 수 있는 취약점은?","choices":["Ransomware","Pharming","Phishing","XSS"],"ans":4,"rate":54,"exp":{"concept":"XSS(Cross Site Scripting)는 웹 페이지에 악의적인 스크립트를 몰래 넣어, 그 페이지를 방문한 사용자의 브라우저에서 스크립트가 실행되게 하는 공격이다. 쿠키·세션 정보 탈취, 악성 사이트로 이동시키기 등의 피해가 생긴다. 입력 값에 들어 있는 스크립트를 걸러 내 막는다.","choices":[{"verdict":"오답","why":"랜섬웨어(Ransomware)는 사용자의 파일을 암호화해 쓸 수 없게 만든 뒤 풀어 주는 대가로 돈을 요구하는 악성 프로그램이다."},{"verdict":"오답","why":"파밍(Pharming)은 DNS 정보를 조작하는 등의 방법으로 사용자가 진짜 주소를 입력해도 가짜 사이트로 접속하게 만드는 공격이다."},{"verdict":"오답","why":"피싱(Phishing)은 믿을 만한 기관이나 사람인 것처럼 속인 메일·메시지로 개인 정보를 빼내는 공격이다."},{"verdict":"정답","why":"XSS는 웹 페이지에 악의적인 스크립트를 넣어 사용자 측에서 실행되게 함으로써 정보 유출 등을 일으키는 취약점이다."}],"keywords":[{"term":"XSS(Cross Site Scripting)","desc":"웹 페이지에 악성 스크립트를 삽입해 사용자 브라우저에서 실행"},{"term":"SQL 삽입(SQL Injection)","desc":"입력란에 SQL 문을 넣어 데이터베이스를 조작"},{"term":"파밍(Pharming)","desc":"DNS 조작 등으로 가짜 사이트로 유도"},{"term":"피싱(Phishing)","desc":"사칭 메일·메시지로 개인 정보 탈취"}],"memo":"'스크립트'와 '사용자 측 실행'이 보이면 XSS. 데이터베이스를 노리면 SQL 삽입이다."}},{"id":"written-2020-4-95","no":95,"unit":"정보시스템 구축 관리","q":"CBD(Component Based Development) 에 대한 설명으로 틀린 것은?","choices":["개발 기간 단축으로 인한 생산성 향상","새로운 기능 추가가 쉬운 확장성","소프트웨어 재사용이 가능","1960년대까지 가장 많이 적용되었던 소프트웨어 개발 방법"],"ans":4,"rate":77,"wiki":[{"title":"CBD 방법론","url":"https://itwiki.kr/w/CBD 방법론"}],"exp":{"concept":"CBD(Component Based Development, 컴포넌트 기반 개발)는 미리 만들어 둔 컴포넌트(부품)를 조립해 새 소프트웨어를 만드는 방법론이다. 레고 블록을 조립하듯 개발하므로 재사용으로 개발 기간이 줄고, 새 기능을 추가하기도 쉽다. 1990년대 후반 이후 널리 쓰이기 시작한 비교적 최근의 방법론이다.","choices":[{"verdict":"오답","why":"컴포넌트를 재사용해 개발 기간이 줄어들어 생산성이 향상된다. 맞는 설명이다."},{"verdict":"오답","why":"필요한 컴포넌트를 추가·교체하기 쉬워 새로운 기능 추가가 쉬운 확장성을 가진다. 맞는 설명이다."},{"verdict":"오답","why":"이미 만든 컴포넌트를 다시 사용할 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"CBD는 1960년대가 아니라 1990년대 후반 이후 널리 쓰인 방법론이다. 틀린 설명이다."}],"keywords":[{"term":"CBD(Component Based Development)","desc":"재사용 가능한 컴포넌트를 조립해 개발하는 방법론"},{"term":"컴포넌트(Component)","desc":"독립적으로 배포·교체할 수 있는 소프트웨어 부품, 인터페이스로 통신"},{"term":"구조적 방법론","desc":"기능 중심으로 정형화된 분석 절차에 따라 분해하는 방법론"}],"memo":"CBD는 '부품 조립'이다. 장점은 재사용·생산성·확장성이고, 1960년대처럼 오래된 시기와는 맞지 않는다."}},{"id":"written-2020-4-96","no":96,"unit":"정보시스템 구축 관리","q":"소프트웨어 정의 데이터센터(SDDC : Software Defined Data Center)에 대한 설명으로 틀린 것은?","choices":["컴퓨팅, 네트워킹, 스토리지, 관리 등을 모두 소프트웨어로 정의한다.","인력 개입 없이 소프트웨어 조작만으로 자동 제어 관리한다.","데이터센터 내 모든 자원을 가상화하여 서비스한다.","특정 하드웨어 에 종속되어 특화된 업무를 서비스하기에 적합하다."],"ans":4,"rate":60,"exp":{"concept":"SDDC(Software Defined Data Center, 소프트웨어 정의 데이터 센터)는 컴퓨팅, 네트워킹, 스토리지, 관리 등 데이터 센터의 모든 자원을 가상화하고 소프트웨어로 정의해 운영하는 데이터 센터다. 사람의 개입 없이 소프트웨어 조작만으로 자원을 자동 관리하며, 특정 하드웨어에 묶이지 않는다.","choices":[{"verdict":"오답","why":"SDDC는 컴퓨팅, 네트워킹, 스토리지, 관리 등을 모두 소프트웨어로 정의한다. 맞는 설명이다."},{"verdict":"오답","why":"인력 개입 없이 소프트웨어 조작만으로 자동 제어·관리한다. 맞는 설명이다."},{"verdict":"오답","why":"데이터 센터 안의 모든 자원을 가상화해 서비스로 제공한다. 맞는 설명이다."},{"verdict":"정답","why":"SDDC는 특정 하드웨어에 종속되지 않고 자원을 유연하게 쓰는 것이 핵심이다. 하드웨어에 종속되어 특화 업무에 적합하다는 설명은 틀렸다."}],"keywords":[{"term":"SDDC","desc":"데이터 센터의 모든 자원을 가상화해 소프트웨어로 정의·관리"},{"term":"SDN(Software Defined Networking)","desc":"네트워크를 소프트웨어로 제어·관리"},{"term":"SDS(Software Defined Storage)","desc":"물리 스토리지를 가상화해 하나의 저장소처럼 관리"}],"memo":"'소프트웨어 정의(Software Defined)'의 반대말이 '하드웨어 종속'이다."}},{"id":"written-2020-4-97","no":97,"unit":"정보시스템 구축 관리","q":"컴퓨터 운영체제의 커널에 보안 기능을 추가한 것으로 운영체제의 보안상 결함으로 인하여 발생 가능한 각종 해킹으로부터 시스템을 보호하기 위하여 사용되는 것은?","choices":["GPIB","CentOS","XSS","Secure OS"],"ans":4,"rate":83,"exp":{"concept":"Secure OS(보안 운영체제)는 운영체제의 커널에 보안 기능을 추가해, 운영체제의 보안 결함을 노린 해킹으로부터 시스템을 보호하는 운영체제다. 식별·인증, 강제적 접근 통제, 감사 기록 같은 기능을 커널 수준에서 수행한다.","choices":[{"verdict":"오답","why":"GPIB(General Purpose Interface Bus)는 컴퓨터와 계측기 등 주변 장치를 연결하는 범용 인터페이스 버스 표준(IEEE 488)이다."},{"verdict":"오답","why":"CentOS는 레드햇 엔터프라이즈 리눅스를 바탕으로 만든 무료 리눅스 배포판이다. 커널 보안 기능을 위한 제품 분류가 아니다."},{"verdict":"오답","why":"XSS는 웹 페이지에 악성 스크립트를 넣는 공격 기법이다."},{"verdict":"정답","why":"Secure OS는 커널에 보안 기능을 추가해 운영체제의 보안 결함으로 생기는 해킹으로부터 시스템을 보호한다."}],"keywords":[{"term":"Secure OS","desc":"커널에 보안 기능을 추가한 운영체제"},{"term":"참조 모니터(Reference Monitor)","desc":"주체의 객체 접근을 검사하는 보안 커널의 핵심 개념"},{"term":"GPIB","desc":"계측기 연결용 범용 인터페이스 버스, IEEE 488"}],"memo":"'커널에 보안 기능 추가'는 이름 그대로 보안(Secure) 운영체제(OS)다."}},{"id":"written-2020-4-98","no":98,"unit":"정보시스템 구축 관리","q":"NS(Nassi-Schneiderman) chart에 대한 설명으로 거리가 먼 것은?","choices":["논리의 기술에 중점을 둔 도형식 표현 방법이다.","연속, 선택 및 다중 선택, 반복 등의 제어논리 구조로 표현한다.","주로 화살표를 사용하여 논리적인 제어구조로 흐름을 표현한다.","조건이 복합되어 있는 곳의 처리를 시각적으로 명확히 식별하는데 적합하다."],"ans":3,"rate":61,"exp":{"concept":"NS 차트(Nassi-Shneiderman Chart)는 프로그램 논리를 상자 모양 도형으로 표현하는 구조적 표현 도구다. 순차, 선택·다중 선택, 반복 구조만으로 표현하고, GOTO나 화살표를 쓰지 않는다. 박스 다이어그램, Chapin Chart라고도 한다.","choices":[{"verdict":"오답","why":"NS 차트는 논리의 기술에 중점을 둔 도형식 표현 방법이다. 맞는 설명이다."},{"verdict":"오답","why":"NS 차트는 연속(순차), 선택 및 다중 선택, 반복 등의 제어 논리 구조로 표현한다. 맞는 설명이다."},{"verdict":"정답","why":"NS 차트는 화살표나 GOTO를 사용하지 않는다. 화살표로 흐름을 표현하는 것은 순서도(Flowchart)이므로 틀린 설명이다."},{"verdict":"오답","why":"NS 차트는 조건이 복합된 곳의 처리를 시각적으로 명확히 식별하는 데 적합하다. 맞는 설명이다."}],"keywords":[{"term":"NS 차트(Nassi-Shneiderman Chart)","desc":"상자 모양으로 논리를 표현, GOTO·화살표 없음"},{"term":"순서도(Flowchart)","desc":"도형과 화살표로 처리 흐름을 표현"},{"term":"구조적 프로그래밍 3구조","desc":"순차(Sequence), 선택(Selection), 반복(Iteration)"}],"memo":"NS 차트는 '상자 안에 상자', 화살표가 없다. 화살표가 나오면 순서도다."}},{"id":"written-2020-4-99","no":99,"unit":"정보시스템 구축 관리","q":"다음 내용에 적합한 용어는?\n<img src=\"data/img/eip_written_20200926_099.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["MapReduce","SQL","Hijacking","Logs"],"ans":1,"rate":71,"exp":{"concept":"맵리듀스(MapReduce)는 구글이 고안한 대용량 데이터 분산 처리 프로그래밍 모델이다. 데이터를 잘게 나눠 여러 서버에서 동시에 처리(Map)하고, 그 결과를 다시 모아 합치는(Reduce) 과정을 거친다. 하둡(Hadoop)이 이 방식을 사용한다.","choices":[{"verdict":"정답","why":"맵리듀스는 대용량 데이터를 분산 처리하기 위해 구글이 고안한 프로그래밍 모델로, 정렬된 데이터를 분산 처리(Map)하고 다시 합치는(Reduce) 과정을 거친다."},{"verdict":"오답","why":"SQL은 관계형 데이터베이스에서 데이터를 정의·조작·제어하는 질의 언어다."},{"verdict":"오답","why":"하이재킹(Hijacking)은 세션 하이재킹처럼 다른 사용자의 연결이나 세션을 가로채는 공격이다."},{"verdict":"오답","why":"로그(Logs)는 시스템에서 일어난 사건을 기록한 것이다."}],"keywords":[{"term":"맵리듀스(MapReduce)","desc":"Map(분산 처리)과 Reduce(결과 병합)로 대용량 데이터를 처리하는 모델"},{"term":"하둡(Hadoop)","desc":"오픈소스 대용량 데이터 분산 처리 프레임워크"},{"term":"HDFS","desc":"하둡의 분산 파일 시스템"}],"memo":"'나눠서 처리(Map)하고 다시 합친다(Reduce)'는 설명이 나오면 이름 그대로 맵리듀스다."}},{"id":"written-2020-4-100","no":100,"unit":"정보시스템 구축 관리","q":"소프트웨어 프로세스에 대한 개선 및 능력 측정 기준에 대한 국제 표준은?","choices":["ISO 14001","IEEE 802.5","IEEE 488","SPICE"],"ans":4,"rate":57,"wiki":[{"title":"SPICE","url":"https://itwiki.kr/w/SPICE"}],"exp":{"concept":"SPICE(Software Process Improvement and Capability dEtermination)는 소프트웨어 프로세스를 평가하고 개선하기 위한 국제 표준(ISO/IEC 15504)이다. 프로세스 수행 능력을 불완전 → 수행 → 관리 → 확립 → 예측 → 최적화의 6단계(0~5단계)로 평가한다.","choices":[{"verdict":"오답","why":"ISO 14001은 환경 경영 시스템에 관한 국제 표준이다."},{"verdict":"오답","why":"IEEE 802.5는 토큰 링(Token Ring) LAN에 관한 표준이다."},{"verdict":"오답","why":"IEEE 488은 계측기 연결용 범용 인터페이스 버스(GPIB) 표준이다."},{"verdict":"정답","why":"SPICE는 소프트웨어 프로세스의 개선과 능력 측정 기준에 대한 국제 표준(ISO/IEC 15504)이다."}],"keywords":[{"term":"SPICE","desc":"소프트웨어 프로세스 평가·개선 국제 표준, ISO/IEC 15504"},{"term":"SPICE 수행 능력 6단계","desc":"불완전, 수행, 관리, 확립, 예측, 최적화(0~5단계)"},{"term":"CMMI","desc":"소프트웨어 개발 조직의 업무 능력과 성숙도를 평가하는 모델"}],"memo":"프로세스 개선(Improvement)과 능력 측정(Capability Determination)이 이름에 들어 있는 표준이 SPICE다."}}]};